      const dbPayload = {
        id: targetId,
        symbol: newInsight.symbol,
        category: newInsight.category,
        status: newInsight.status,
        focus_points: newInsight.focusPoints,
        strategy: newInsight.strategy,
        entry_level: newInsight.entryLevel,
        updated_at: updatedTimestamp,
        completion_status: newInsight.completionStatus
      };
      await supabase.from('insights').upsert(dbPayload);
