  const [searchQuery, setSearchQuery] = useState('');

  const [isAdmin, setIsAdmin] = useState(() => localStorage.getItem('is_admin') === 'true');
  const [clickCount, setClickCount] = useState(0);

  // Load from Supabase or LocalStorage fallback
  const fetchInsights = async () => {
    setLoading(true);

    if (isSupabaseConfigured && supabase) {
      const { data, error } = await supabase
        .from('insights')
        .select('*')
        .order('updated_at', { ascending: false });

      if (!error && data) {
        const mappedData = data.map((item: any) => ({
          id: item.id,
          symbol: item.symbol,
          category: item.category,
          status: item.status as any,
          focusPoints: item.focus_points,
          strategy: item.strategy,
          entryLevel: item.entry_level,
          updatedAt: item.updated_at,
          completionStatus: item.completion_status as any
        }));
        setInsights(mappedData);
        localStorage.setItem('local_insights', JSON.stringify(mappedData));
      } else {
        console.warn('Supabase fetch failed, falling back to local data');
        loadLocalData();
      }
    } else {
      loadLocalData();
    }
    setLoading(false);
  };

  const loadLocalData = () => {
    const saved = localStorage.getItem('local_insights');
    if (saved) {
