                  <button key={month} onClick={() => setSelectedMonth(month)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === month ? 'bg-[#12141c] text-white shadow-xl shadow-gray-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                    <span>{month}</span>
                    <span className={`text-[10px] px-2 py-0.5 rounded-md ${selectedMonth === month ? 'bg-white/20' : 'bg-gray-100'}`}>{count}</span>
