          ) : (
            <>
              <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-20">
                <div>
                  <h2 className="text-6xl font-black text-[#12141c] tracking-tighter leading-tight italic mb-4">
                    追踪行情，<br />每日洞察。
                  </h2>
                </div>
                <div className="flex bg-gray-100/80 p-1.5 rounded-2xl border border-gray-100 shadow-inner shrink-0">
                  <button onClick={() => setSortMode('category')} className={`flex items-center gap-2 px-6 py-3 rounded-xl text-[13px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-sm border border-gray-100' : 'text-gray-400 hover:text-gray-600'}`}>
                    <ListFilter className="w-4 h-4" /> 类别视图
                  </button>
                  <button onClick={() => setSortMode('timeline')} className={`flex items-center gap-2 px-6 py-3 rounded-xl text-[13px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-sm border border-gray-100' : 'text-gray-400 hover:text-gray-600'}`}>
                    <CalendarDays className="w-4 h-4" /> 时间轴视图
                  </button>
                </div>
              </div>

              {activeItems.length > 0 ? (
                <div className="space-y-24">
                  {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                    <section key={groupLabel} className="animate-in fade-in duration-1000">
                      <div className="flex items-center gap-6 mb-12">
                        <span className="text-[14px] font-black tracking-widest uppercase bg-[#12141c] text-white px-6 py-2 rounded-2xl shadow-xl shadow-gray-200">{groupLabel}</span>
                        <div className="flex-grow h-[1px] bg-gray-100" />
                        <span className="text-[12px] font-bold text-gray-300 uppercase tracking-widest">{groupItems.length} 条洞察</span>
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                        {groupItems.map(insight => (
                          <MarketCard 
                            key={insight.id} 
                            insight={insight} 
                            onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}}
                            onDelete={isAdmin ? handleDeleteInsight : () => {}}
                            onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}}
                            isEditable={isAdmin}
                          />
                        ))}
                      </div>
                    </section>
                  ))}
                </div>
              ) : (
                <div className="text-center py-40 border-4 border-dashed border-gray-50 rounded-[4rem] bg-gray-50/30">
                  <div className="w-20 h-20 bg-white rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-xl shadow-gray-100">
                    <Plus className="w-10 h-10 text-gray-200" />
                  </div>
                  <h3 className="text-2xl font-black text-gray-900 tracking-tight">{searchQuery ? '没有找到匹配的记录' : '当前暂无进行中的洞察'}</h3>
                  <p className="text-gray-400 font-bold mt-2">点击“记录观点”开始追踪市场动态</p>
                </div>
              )}

              {archivedItems.length > 0 && (
                <div className="mt-60 pt-32 border-t border-gray-100">
                  <div className="flex items-center justify-between mb-16">
                      <div className="flex items-center gap-6">
                        <div className="w-14 h-14 bg-gray-100 rounded-2xl flex items-center justify-center">
                          <Archive className="w-6 h-6 text-gray-400" />
                        </div>
                        <div>
                          <h3 className="text-3xl font-black text-[#12141c] tracking-tight italic">历史归档</h3>
                          <p className="text-gray-400 font-bold">已结项或失效的市场研判</p>
                        </div>
                      </div>
                      <div className="px-5 py-2 bg-gray-100 rounded-full text-[12px] font-black text-gray-400">
                        {archivedItems.length} 份记录
                      </div>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10 grayscale opacity-40 hover:opacity-100 transition-opacity duration-700">
                    {archivedItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}}
                        onDelete={isAdmin ? handleDeleteInsight : () => {}}
                        onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}}
                        isEditable={isAdmin}
                      />
                    ))}
                  </div>
                </div>
              )}
            </>
          )}
        </main>
      </div>

      {showForm && isAdmin && (
        <InsightForm initialData={editingInsight} onSave={handleSaveInsight} onCancel={() => { setShowForm(false); setEditingInsight(undefined); }} />
      )}

      <footer className="mt-40 border-t border-gray-50 py-20 px-8">
        <div className="max-w-[1600px] mx-auto flex flex-col md:flex-row justify-between items-center gap-8">
          <div className="flex items-center gap-4">
             <div className="w-8 h-8 bg-[#12141c] rounded-lg" />
             <span className="text-xl font-black italic tracking-tighter">市场周刊.</span>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { supabase, isSupabaseConfigured } from './services/supabaseClient';
import { 
  Plus, 
  LayoutGrid, 
  ListFilter, 
  CalendarDays, 
  Archive, 
  Search, 
  X, 
  Lock,
  Unlock
} from 'lucide-react';

const ADMIN_PASSWORD = "8888"; 

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('category');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');

  const [isAdmin, setIsAdmin] = useState(() => localStorage.getItem('is_admin') === 'true');
  const [clickCount, setClickCount] = useState(0);

  // 快捷键监听：Ctrl + Shift + A (Add)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.shiftKey && e.key.toLowerCase() === 'a') {
        if (!isAdmin) {
          triggerAdminLogin();
        } else {
          setEditingInsight(undefined);
          setShowForm(true);
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isAdmin]);

  const triggerAdminLogin = () => {
    const pwd = prompt("请输入管理密钥以开启编辑模式：");
    if (pwd === ADMIN_PASSWORD) {
      setIsAdmin(true);
      localStorage.setItem('is_admin', 'true');
      alert("管理模式已启用");
    } else if (pwd !== null) {
      alert("密钥错误");
    }
  };

  const fetchInsights = async () => {
    setLoading(true);
    if (isSupabaseConfigured && supabase) {
      const { data, error } = await supabase
        .from('insights')
        .select('*')
        .order('updated_at', { ascending: false });

      if (!error && data) {
        const mappedData = data.map((item: any) => ({
          id: item.id,
          symbol: item.symbol,
          category: item.category,
          status: item.status as any,
          focusPoints: item.focus_points,
          strategy: item.strategy,
          entryLevel: item.entry_level,
          updatedAt: item.updated_at,
          completionStatus: item.completion_status as any
        }));
        setInsights(mappedData);
        localStorage.setItem('local_insights', JSON.stringify(mappedData));
      } else {
        loadLocalData();
      }
    } else {
      loadLocalData();
    }
    setLoading(false);
  };

  const loadLocalData = () => {
    const saved = localStorage.getItem('local_insights');
    if (saved) {
      setInsights(JSON.parse(saved));
    } else {
      setInsights(INITIAL_INSIGHTS);
    }
  };

  useEffect(() => {
    fetchInsights();
  }, []);

  const handleLogoClick = () => {
    if (isAdmin) return;
    const newCount = clickCount + 1;
    if (newCount >= 5) {
      triggerAdminLogin();
      setClickCount(0);
    } else {
      setClickCount(newCount);
      // 3秒内不连点则重置
      setTimeout(() => setClickCount(0), 3000);
    }
  };

  const handleLogout = () => {
    if (window.confirm("确定退出管理模式吗？")) {
      setIsAdmin(false);
      localStorage.removeItem('is_admin');
    }
  };

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(i => 
        i.symbol.toLowerCase().includes(query) || 
        i.focusPoints.toLowerCase().includes(query) || 
        i.strategy.toLowerCase().includes(query)
      );
    }
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    return result;
  }, [insights, activeCategory, selectedMonth, searchQuery]);

  const { activeItems, archivedItems } = useMemo(() => {
    return {
      activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
      archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
    };
  }, [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' 
        ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' })
        : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    const entries = Object.entries(groups);
    return sortMode === 'category' 
      ? entries.sort((a, b) => CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any))
      : entries.sort((a, b) => b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  const handleSaveInsight = async (data: Partial<MarketInsight>) => {
    if (!isAdmin) return;
    const targetId = editingInsight ? editingInsight.id : Math.random().toString(36).substr(2, 9);
    const updatedTimestamp = data.updatedAt || Date.now();

    const newInsight: MarketInsight = {
      id: targetId,
      symbol: data.symbol || '',
      category: data.category || '美股',
      status: data.status || '震荡',
      focusPoints: data.focusPoints || '',
      strategy: data.strategy || '',
      entryLevel: data.entryLevel || '',
      updatedAt: updatedTimestamp,
      completionStatus: data.completionStatus || '进行中'
    };

    if (isSupabaseConfigured && supabase) {
      const dbPayload = {
        id: targetId,
        symbol: newInsight.symbol,
        category: newInsight.category,
        status: newInsight.status,
        focus_points: newInsight.focusPoints,
        strategy: newInsight.strategy,
        entry_level: newInsight.entryLevel,
        updated_at: updatedTimestamp,
        completion_status: newInsight.completionStatus
      };
      await supabase.from('insights').upsert(dbPayload);
    }

    const updatedInsights = editingInsight 
      ? insights.map(i => i.id === targetId ? newInsight : i)
      : [newInsight, ...insights];

    setInsights(updatedInsights);
    localStorage.setItem('local_insights', JSON.stringify(updatedInsights));
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = async (id: string) => {
    if (!isAdmin) return;
    if (window.confirm('确定要删除这条记录吗？')) {
      if (isSupabaseConfigured && supabase) {
        await supabase.from('insights').delete().eq('id', id);
      }
      const updated = insights.filter(i => i.id !== id);
      setInsights(updated);
      localStorage.setItem('local_insights', JSON.stringify(updated));
    }
  };

  const handleToggleCompletionStatus = async (id: string) => {
    if (!isAdmin) return;
    const item = insights.find(i => i.id === id);
    if (!item) return;

    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    const currentIndex = statuses.indexOf(item.completionStatus);
    const nextStatus = statuses[(currentIndex + 1) % statuses.length];

    if (isSupabaseConfigured && supabase) {
      await supabase.from('insights').update({ completion_status: nextStatus, updated_at: Date.now() }).eq('id', id);
    }

    const updated = insights.map(i => i.id === id ? { ...i, completionStatus: nextStatus, updatedAt: Date.now() } : i);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-amber-100">
      <header className="sticky top-0 z-[100] bg-white/90 backdrop-blur-2xl border-b border-gray-100 px-8 h-[72px]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between h-full gap-8">
          <div className="flex items-center gap-3 shrink-0">
            <button 
              onClick={handleLogoClick}
              className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all active:scale-90 ${isAdmin ? 'bg-amber-500 shadow-xl shadow-amber-200 ring-2 ring-white/50' : 'bg-[#12141c]'}`}
            >
              <LayoutGrid className="w-5 h-5 text-white" />
            </button>
            <div className="flex flex-col -space-y-1">
              <h1 className="text-xl font-black text-[#12141c] tracking-tighter">市场周刊</h1>
            </div>
          </div>

          <div className="flex-grow flex items-center gap-4 max-w-3xl">
            <div className="relative group flex-grow">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <Search className={`w-4 h-4 transition-colors ${searchQuery ? 'text-gray-900' : 'text-gray-300'}`} />
              </div>
              <input
                type="text"
                className="w-full bg-gray-100/60 border border-transparent focus:bg-white focus:border-gray-200 py-3 pl-11 pr-10 rounded-2xl text-[14px] font-bold outline-none transition-all placeholder:text-gray-400"
                placeholder="搜索洞察记录..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
              {searchQuery && (
                <button onClick={() => setSearchQuery('')} className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-300 hover:text-gray-900 transition-colors">
                  <X className="w-4 h-4" />
                </button>
              )}
            </div>

            <nav className="hidden xl:flex items-center gap-1 bg-gray-100/60 p-1.5 rounded-2xl shrink-0 border border-gray-50">
              {CATEGORIES.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`px-5 py-2.5 rounded-xl text-[13px] font-black transition-all ${activeCategory === cat ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400 hover:text-gray-900'}`}
                >
                  {cat}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4 shrink-0">
            {isAdmin && (
              <div className="flex items-center gap-3 animate-in fade-in slide-in-from-right-4 duration-500">
                <button 
                  onClick={() => { setEditingInsight(undefined); setShowForm(true); }} 
                  className="bg-[#12141c] text-white flex items-center gap-2 px-6 py-3 rounded-full hover:scale-105 transition-all shadow-xl shadow-gray-200 active:scale-95"
                >
                  <Plus className="w-4 h-4" />
                  <span className="text-sm font-black">记录观点</span>
                </button>
                <button 
                  onClick={handleLogout} 
                  title="退出管理模式"
                  className="p-3 bg-red-50 text-red-500 hover:bg-red-100 rounded-full transition-colors"
                >
                   <Lock className="w-4 h-4" />
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        <aside className="lg:w-64 space-y-12 flex-shrink-0">
          <div className="sticky top-[104px] space-y-10">
            <div>
              <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
                <CalendarDays className="w-3.5 h-3.5" /> 历史归档
              </h3>
              <div className="space-y-1">
                <button onClick={() => setSelectedMonth(null)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === null ? 'bg-[#12141c] text-white shadow-xl shadow-gray-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                  <span>全部记录</span>
                  <span className={`text-[10px] px-2 py-0.5 rounded-md ${selectedMonth === null ? 'bg-white/20' : 'bg-gray-100'}`}>{insights.length}</span>
                </button>
                {timelineGroups.map(([month, count]) => (
                  <button key={month} onClick={() => setSelectedMonth(month)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === month ? 'bg-[#12141c] text-white shadow-xl shadow-gray-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                    <span>{month}</span>
                    <span className={`text-[10px] px-2 py-0.5 rounded-md ${selectedMonth === month ? 'bg-white/20' : 'bg-gray-100'}`}>{count}</span>
                  </button>
                ))}
              </div>
            </div>

            {isAdmin && (
              <div className="p-6 rounded-[2rem] bg-emerald-50 border border-emerald-100 animate-pulse-slow">
                <div className="flex items-center gap-2 text-emerald-700 font-black text-xs mb-2">
                  <Unlock className="w-3 h-3" />
                  管理模式激活
                </div>
                <p className="text-[10px] font-bold text-emerald-600/70 leading-relaxed uppercase tracking-widest">
                  您现在可以直接编辑或删除任何卡片。
                </p>
              </div>
            )}
          </div>
        </aside>

        <main className="flex-grow">
          {loading && insights.length === 0 ? (
             <div className="flex flex-col items-center justify-center py-48 opacity-40">
                <p className="font-black tracking-[0.2em] uppercase text-xs text-gray-400">正在同步行情洞察...</p>
             </div>
          ) : (
            <>
              <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-20">
                <div>
                  <h2 className="text-6xl font-black text-[#12141c] tracking-tighter leading-tight italic mb-4">
                    追踪行情，<br />每日洞察。
                  </h2>
                </div>
                <div className="flex bg-gray-100/80 p-1.5 rounded-2xl border border-gray-100 shadow-inner shrink-0">
                  <button onClick={() => setSortMode('category')} className={`flex items-center gap-2 px-6 py-3 rounded-xl text-[13px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-sm border border-gray-100' : 'text-gray-400 hover:text-gray-600'}`}>
                    <ListFilter className="w-4 h-4" /> 类别视图
                  </button>
                  <button onClick={() => setSortMode('timeline')} className={`flex items-center gap-2 px-6 py-3 rounded-xl text-[13px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-sm border border-gray-100' : 'text-gray-400 hover:text-gray-600'}`}>
                    <CalendarDays className="w-4 h-4" /> 时间轴视图
                  </button>
                </div>
              </div>

              {activeItems.length > 0 ? (
                <div className="space-y-24">
                  {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                    <section key={groupLabel} className="animate-in fade-in duration-1000">
                      <div className="flex items-center gap-6 mb-12">
                        <span className="text-[14px] font-black tracking-widest uppercase bg-[#12141c] text-white px-6 py-2 rounded-2xl shadow-xl shadow-gray-200">{groupLabel}</span>
                        <div className="flex-grow h-[1px] bg-gray-100" />
                        <span className="text-[12px] font-bold text-gray-300 uppercase tracking-widest">{groupItems.length} 条洞察</span>
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                        {groupItems.map(insight => (
                          <MarketCard 
                            key={insight.id} 
                            insight={insight} 
                            onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}}
                            onDelete={isAdmin ? handleDeleteInsight : () => {}}
                            onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}}
                            isEditable={isAdmin}
                          />
                        ))}
                      </div>
                    </section>
                  ))}
                </div>
              ) : (
                <div className="text-center py-40 border-4 border-dashed border-gray-50 rounded-[4rem] bg-gray-50/30">
                  <div className="w-20 h-20 bg-white rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-xl shadow-gray-100">
                    <Plus className="w-10 h-10 text-gray-200" />
                  </div>
                  <h3 className="text-2xl font-black text-gray-900 tracking-tight">{searchQuery ? '没有找到匹配的记录' : '当前暂无进行中的洞察'}</h3>
                  {!isAdmin && <p className="text-gray-400 font-bold mt-2">请联系博主获取最新动态</p>}
                  {isAdmin && <p className="text-gray-400 font-bold mt-2">点击“记录观点”开始追踪市场动态</p>}
                </div>
              )}

              {archivedItems.length > 0 && (
                <div className="mt-60 pt-32 border-t border-gray-100">
                  <div className="flex items-center justify-between mb-16">
                      <div className="flex items-center gap-6">
                        <div className="w-14 h-14 bg-gray-100 rounded-2xl flex items-center justify-center">
                          <Archive className="w-6 h-6 text-gray-400" />
                        </div>
                        <div>
                          <h3 className="text-3xl font-black text-[#12141c] tracking-tight italic">历史归档</h3>
                          <p className="text-gray-400 font-bold">已结项或失效的市场研判</p>
                        </div>
                      </div>
                      <div className="px-5 py-2 bg-gray-100 rounded-full text-[12px] font-black text-gray-400">
                        {archivedItems.length} 份记录
                      </div>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10 grayscale opacity-40 hover:opacity-100 transition-opacity duration-700">
                    {archivedItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}}
                        onDelete={isAdmin ? handleDeleteInsight : () => {}}
                        onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}}
                        isEditable={isAdmin}
                      />
                    ))}
                  </div>
                </div>
              )}
            </>
          )}
        </main>
      </div>

      {showForm && isAdmin && (
        <InsightForm initialData={editingInsight} onSave={handleSaveInsight} onCancel={() => { setShowForm(false); setEditingInsight(undefined); }} />
      )}

      <footer className="mt-40 border-t border-gray-50 py-20 px-8">
        <div className="max-w-[1600px] mx-auto flex flex-col md:flex-row justify-between items-center gap-8">
          <div className="flex items-center gap-4">
             <div className="w-8 h-8 bg-[#12141c] rounded-lg" />
             <span className="text-xl font-black italic tracking-tighter">市场周刊.</span>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { supabase, isSupabaseConfigured } from './services/supabaseClient';
import { 
  Plus, 
  LayoutGrid, 
  ListFilter, 
  CalendarDays, 
  Archive, 
  Search, 
  X, 
  Lock,
  Unlock
} from 'lucide-react';

const ADMIN_PASSWORD = "8888"; 

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('category');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');

  const [isAdmin, setIsAdmin] = useState(() => localStorage.getItem('is_admin') === 'true');
  const [clickCount, setClickCount] = useState(0);

  // 统一的登录触发器
  const triggerAdminLogin = useCallback(() => {
    const pwd = prompt("请输入管理密钥以开启编辑模式：");
    if (pwd === ADMIN_PASSWORD) {
      setIsAdmin(true);
      localStorage.setItem('is_admin', 'true');
      alert("管理模式已启用");
    } else if (pwd !== null) {
      alert("密钥错误");
    }
  }, []);

  // 快捷键监听：Ctrl + Shift + A
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.shiftKey && e.key.toLowerCase() === 'a') {
        if (!isAdmin) {
          triggerAdminLogin();
        } else {
          setEditingInsight(undefined);
          setShowForm(true);
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isAdmin, triggerAdminLogin]);

  const fetchInsights = async () => {
    setLoading(true);
    if (isSupabaseConfigured && supabase) {
      try {
        const { data, error } = await supabase
          .from('insights')
          .select('*')
          .order('updated_at', { ascending: false });

        if (!error && data) {
          const mappedData = data.map((item: any) => ({
            id: item.id,
            symbol: item.symbol,
            category: item.category,
            status: item.status as any,
            focusPoints: item.focus_points,
            strategy: item.strategy,
            entryLevel: item.entry_level,
            updatedAt: item.updated_at,
            completionStatus: item.completion_status as any
          }));
          setInsights(mappedData);
          localStorage.setItem('local_insights', JSON.stringify(mappedData));
        } else {
          loadLocalData();
        }
      } catch (e) {
        loadLocalData();
      }
    } else {
      loadLocalData();
    }
    setLoading(false);
  };

  const loadLocalData = () => {
    const saved = localStorage.getItem('local_insights');
    if (saved) {
      setInsights(JSON.parse(saved));
    } else {
      setInsights(INITIAL_INSIGHTS);
    }
  };

  useEffect(() => {
    fetchInsights();
  }, []);

  // 优化后的 Logo 点击逻辑
  const handleLogoClick = () => {
    if (isAdmin) return;

    setClickCount(prev => {
      const next = prev + 1;
      if (next >= 5) {
        // 使用 setTimeout 确保在状态更新周期外触发 prompt
        setTimeout(triggerAdminLogin, 50);
        return 0;
      }
      return next;
    });

    // 自动重置计数器（如果用户点击太慢）
    const timer = setTimeout(() => setClickCount(0), 2000);
    return () => clearTimeout(timer);
  };

  const handleLogout = () => {
    if (window.confirm("确定退出管理模式吗？")) {
      setIsAdmin(false);
      localStorage.removeItem('is_admin');
    }
  };

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(i => 
        i.symbol.toLowerCase().includes(query) || 
        i.focusPoints.toLowerCase().includes(query) || 
        i.strategy.toLowerCase().includes(query)
      );
    }
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    return result;
  }, [insights, activeCategory, selectedMonth, searchQuery]);

  const { activeItems, archivedItems } = useMemo(() => {
    return {
      activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
      archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
    };
  }, [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' 
        ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' })
        : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    const entries = Object.entries(groups);
    return sortMode === 'category' 
      ? entries.sort((a, b) => CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any))
      : entries.sort((a, b) => b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  const handleSaveInsight = async (data: Partial<MarketInsight>) => {
    if (!isAdmin) return;
    const targetId = editingInsight ? editingInsight.id : Math.random().toString(36).substr(2, 9);
    const updatedTimestamp = data.updatedAt || Date.now();

    const newInsight: MarketInsight = {
      id: targetId,
      symbol: data.symbol || '',
      category: data.category || '美股',
      status: data.status || '震荡',
      focusPoints: data.focusPoints || '',
      strategy: data.strategy || '',
      entryLevel: data.entryLevel || '',
      updatedAt: updatedTimestamp,
      completionStatus: data.completionStatus || '进行中'
    };

    if (isSupabaseConfigured && supabase) {
      try {
        await supabase.from('insights').upsert({
          id: targetId,
          symbol: newInsight.symbol,
          category: newInsight.category,
          status: newInsight.status,
          focus_points: newInsight.focusPoints,
          strategy: newInsight.strategy,
          entry_level: newInsight.entryLevel,
          updated_at: updatedTimestamp,
          completion_status: newInsight.completionStatus
        });
      } catch (e) {
        console.error("Supabase upsert failed:", e);
      }
    }

    const updatedInsights = editingInsight 
      ? insights.map(i => i.id === targetId ? newInsight : i)
      : [newInsight, ...insights];

    setInsights(updatedInsights);
    localStorage.setItem('local_insights', JSON.stringify(updatedInsights));
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = async (id: string) => {
    if (!isAdmin) return;
    if (window.confirm('确定要删除这条记录吗？')) {
      if (isSupabaseConfigured && supabase) {
        await supabase.from('insights').delete().eq('id', id);
      }
      const updated = insights.filter(i => i.id !== id);
      setInsights(updated);
      localStorage.setItem('local_insights', JSON.stringify(updated));
    }
  };

  const handleToggleCompletionStatus = async (id: string) => {
    if (!isAdmin) return;
    const item = insights.find(i => i.id === id);
    if (!item) return;

    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    const currentIndex = statuses.indexOf(item.completionStatus);
    const nextStatus = statuses[(currentIndex + 1) % statuses.length];

    const newTime = Date.now();
    if (isSupabaseConfigured && supabase) {
      await supabase.from('insights').update({ completion_status: nextStatus, updated_at: newTime }).eq('id', id);
    }

    const updated = insights.map(i => i.id === id ? { ...i, completionStatus: nextStatus, updatedAt: newTime } : i);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-amber-100">
      <header className="sticky top-0 z-[100] bg-white/90 backdrop-blur-2xl border-b border-gray-100 px-8 h-[72px]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between h-full gap-8">
          <div className="flex items-center gap-3 shrink-0">
            <button 
              onClick={handleLogoClick}
              className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all active:scale-90 ${isAdmin ? 'bg-amber-500 shadow-xl shadow-amber-200 ring-2 ring-white/50' : 'bg-[#12141c]'}`}
            >
              <LayoutGrid className="w-5 h-5 text-white" />
            </button>
            <div className="flex flex-col -space-y-1">
              <h1 className="text-xl font-black text-[#12141c] tracking-tighter">市场周刊</h1>
            </div>
          </div>

          <div className="flex-grow flex items-center gap-4 max-w-3xl">
            <div className="relative group flex-grow">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <Search className={`w-4 h-4 transition-colors ${searchQuery ? 'text-gray-900' : 'text-gray-300'}`} />
              </div>
              <input
                type="text"
                className="w-full bg-gray-100/60 border border-transparent focus:bg-white focus:border-gray-200 py-3 pl-11 pr-10 rounded-2xl text-[14px] font-bold outline-none transition-all placeholder:text-gray-400"
                placeholder="搜索洞察记录..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
              {searchQuery && (
                <button onClick={() => setSearchQuery('')} className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-300 hover:text-gray-900 transition-colors">
                  <X className="w-4 h-4" />
                </button>
              )}
            </div>

            <nav className="hidden xl:flex items-center gap-1 bg-gray-100/60 p-1.5 rounded-2xl shrink-0 border border-gray-50">
              {CATEGORIES.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`px-5 py-2.5 rounded-xl text-[13px] font-black transition-all ${activeCategory === cat ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400 hover:text-gray-900'}`}
                >
                  {cat}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4 shrink-0">
            {isAdmin && (
              <div className="flex items-center gap-3 animate-in fade-in slide-in-from-right-4 duration-500">
                <button 
                  onClick={() => { setEditingInsight(undefined); setShowForm(true); }} 
                  className="bg-[#12141c] text-white flex items-center gap-2 px-6 py-3 rounded-full hover:scale-105 transition-all shadow-xl shadow-gray-200 active:scale-95"
                >
                  <Plus className="w-4 h-4" />
                  <span className="text-sm font-black">记录观点</span>
                </button>
                <button 
                  onClick={handleLogout} 
                  title="退出管理模式"
                  className="p-3 bg-red-50 text-red-500 hover:bg-red-100 rounded-full transition-colors"
                >
                   <Lock className="w-4 h-4" />
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        <aside className="lg:w-64 space-y-12 flex-shrink-0">
          <div className="sticky top-[104px] space-y-10">
            <div>
              <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
                <CalendarDays className="w-3.5 h-3.5" /> 历史归档
              </h3>
              <div className="space-y-1">
                <button onClick={() => setSelectedMonth(null)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === null ? 'bg-[#12141c] text-white shadow-xl shadow-gray-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                  <span>全部记录</span>
                  <span className={`text-[10px] px-2 py-0.5 rounded-md ${selectedMonth === null ? 'bg-white/20' : 'bg-gray-100'}`}>{insights.length}</span>
                </button>
                {timelineGroups.map(([month, count]) => (
                  <button key={month} onClick={() => setSelectedMonth(month)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === month ? 'bg-[#12141c] text-white shadow-xl shadow-gray-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                    <span>{month}</span>
                    <span className={`text-[10px] px-2 py-0.5 rounded-md ${selectedMonth === month ? 'bg-white/20' : 'bg-gray-100'}`}>{count}</span>
                  </button>
                ))}
              </div>
            </div>

            {isAdmin && (
              <div className="p-6 rounded-[2rem] bg-emerald-50 border border-emerald-100 animate-pulse-slow">
                <div className="flex items-center gap-2 text-emerald-700 font-black text-xs mb-2">
                  <Unlock className="w-3 h-3" />
                  管理模式激活
                </div>
                <p className="text-[10px] font-bold text-emerald-600/70 leading-relaxed uppercase tracking-widest">
                  您现在可以直接编辑或删除任何卡片。
                </p>
              </div>
            )}
          </div>
        </aside>

        <main className="flex-grow">
          {loading && insights.length === 0 ? (
             <div className="flex flex-col items-center justify-center py-48 opacity-40">
                <p className="font-black tracking-[0.2em] uppercase text-xs text-gray-400">正在同步行情洞察...</p>
             </div>
          ) : (
            <>
              <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-20">
                <div>
                  <h2 className="text-6xl font-black text-[#12141c] tracking-tighter leading-tight italic mb-4">
                    追踪行情，<br />每日洞察。
                  </h2>
                </div>
                <div className="flex bg-gray-100/80 p-1.5 rounded-2xl border border-gray-100 shadow-inner shrink-0">
                  <button onClick={() => setSortMode('category')} className={`flex items-center gap-2 px-6 py-3 rounded-xl text-[13px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-sm border border-gray-100' : 'text-gray-400 hover:text-gray-600'}`}>
                    <ListFilter className="w-4 h-4" /> 类别视图
                  </button>
                  <button onClick={() => setSortMode('timeline')} className={`flex items-center gap-2 px-6 py-3 rounded-xl text-[13px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-sm border border-gray-100' : 'text-gray-400 hover:text-gray-600'}`}>
                    <CalendarDays className="w-4 h-4" /> 时间轴视图
                  </button>
                </div>
              </div>

              {activeItems.length > 0 ? (
                <div className="space-y-24">
                  {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                    <section key={groupLabel} className="animate-in fade-in duration-1000">
                      <div className="flex items-center gap-6 mb-12">
                        <span className="text-[14px] font-black tracking-widest uppercase bg-[#12141c] text-white px-6 py-2 rounded-2xl shadow-xl shadow-gray-200">{groupLabel}</span>
                        <div className="flex-grow h-[1px] bg-gray-100" />
                        <span className="text-[12px] font-bold text-gray-300 uppercase tracking-widest">{groupItems.length} 条洞察</span>
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                        {groupItems.map(insight => (
                          <MarketCard 
                            key={insight.id} 
                            insight={insight} 
                            onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}}
                            onDelete={isAdmin ? handleDeleteInsight : () => {}}
                            onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}}
                            isEditable={isAdmin}
                          />
                        ))}
                      </div>
                    </section>
                  ))}
                </div>
              ) : (
                <div className="text-center py-40 border-4 border-dashed border-gray-50 rounded-[4rem] bg-gray-50/30">
                  <div className="w-20 h-20 bg-white rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-xl shadow-gray-100">
                    <Plus className="w-10 h-10 text-gray-200" />
                  </div>
                  <h3 className="text-2xl font-black text-gray-900 tracking-tight">{searchQuery ? '没有找到匹配的记录' : '当前暂无进行中的洞察'}</h3>
                  {!isAdmin && <p className="text-gray-400 font-bold mt-2">请联系博主获取最新动态</p>}
                  {isAdmin && <p className="text-gray-400 font-bold mt-2">点击“记录观点”开始追踪市场动态</p>}
                </div>
              )}

              {archivedItems.length > 0 && (
                <div className="mt-60 pt-32 border-t border-gray-100">
                  <div className="flex items-center justify-between mb-16">
                      <div className="flex items-center gap-6">
                        <div className="w-14 h-14 bg-gray-100 rounded-2xl flex items-center justify-center">
                          <Archive className="w-6 h-6 text-gray-400" />
                        </div>
                        <div>
                          <h3 className="text-3xl font-black text-[#12141c] tracking-tight italic">历史归档</h3>
                          <p className="text-gray-400 font-bold">已结项或失效的市场研判</p>
                        </div>
                      </div>
                      <div className="px-5 py-2 bg-gray-100 rounded-full text-[12px] font-black text-gray-400">
                        {archivedItems.length} 份记录
                      </div>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10 grayscale opacity-40 hover:opacity-100 transition-opacity duration-700">
                    {archivedItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}}
                        onDelete={isAdmin ? handleDeleteInsight : () => {}}
                        onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}}
                        isEditable={isAdmin}
                      />
                    ))}
                  </div>
                </div>
              )}
            </>
          )}
        </main>
      </div>

      {showForm && isAdmin && (
        <InsightForm initialData={editingInsight} onSave={handleSaveInsight} onCancel={() => { setShowForm(false); setEditingInsight(undefined); }} />
      )}

      <footer className="mt-40 border-t border-gray-50 py-20 px-8">
        <div className="max-w-[1600px] mx-auto flex flex-col md:flex-row justify-between items-center gap-8">
          <div className="flex items-center gap-4">
             <div className="w-8 h-8 bg-[#12141c] rounded-lg" />
             <span className="text-xl font-black italic tracking-tighter">市场周刊.</span>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { supabase, isSupabaseConfigured } from './services/supabaseClient';
import { 
  Plus, 
  LayoutGrid, 
  ListFilter, 
  CalendarDays, 
  Archive, 
  Search, 
  X, 
  Lock,
  Unlock
} from 'lucide-react';

const ADMIN_PASSWORD = "8888"; 

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('category');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');

  const [isAdmin, setIsAdmin] = useState(() => localStorage.getItem('is_admin') === 'true');
  const [clickCount, setClickCount] = useState(0);

  // 统一的登录触发器
  const triggerAdminLogin = useCallback(() => {
    const pwd = prompt("管理模式：请输入管理密钥");
    if (pwd === ADMIN_PASSWORD) {
      setIsAdmin(true);
      localStorage.setItem('is_admin', 'true');
      alert("管理模式已开启");
    } else if (pwd !== null) {
      alert("密钥错误");
    }
  }, []);

  // 快捷键监听：Ctrl + Shift + A
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.shiftKey && e.key.toLowerCase() === 'a') {
        if (!isAdmin) {
          triggerAdminLogin();
        } else {
          setEditingInsight(undefined);
          setShowForm(true);
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isAdmin, triggerAdminLogin]);

  // 计数器自动重置逻辑
  useEffect(() => {
    if (clickCount > 0) {
      const timer = setTimeout(() => setClickCount(0), 3000);
      return () => clearTimeout(timer);
    }
  }, [clickCount]);

  const fetchInsights = async () => {
    setLoading(true);
    if (isSupabaseConfigured && supabase) {
      try {
        const { data, error } = await supabase
          .from('insights')
          .select('*')
          .order('updated_at', { ascending: false });

        if (!error && data) {
          const mappedData = data.map((item: any) => ({
            id: item.id,
            symbol: item.symbol,
            category: item.category,
            status: item.status as any,
            focusPoints: item.focus_points,
            strategy: item.strategy,
            entryLevel: item.entry_level,
            updatedAt: item.updated_at,
            completionStatus: item.completion_status as any
          }));
          setInsights(mappedData);
          localStorage.setItem('local_insights', JSON.stringify(mappedData));
        } else {
          loadLocalData();
        }
      } catch (e) {
        loadLocalData();
      }
    } else {
      loadLocalData();
    }
    setLoading(false);
  };

  const loadLocalData = () => {
    const saved = localStorage.getItem('local_insights');
    if (saved) {
      setInsights(JSON.parse(saved));
    } else {
      setInsights(INITIAL_INSIGHTS);
    }
  };

  useEffect(() => {
    fetchInsights();
  }, []);

  // 点击 Logo/品牌区触发逻辑
  const handleBrandClick = () => {
    if (isAdmin) return;

    setClickCount(prev => {
      const next = prev + 1;
      if (next >= 5) {
        setTimeout(triggerAdminLogin, 100);
        return 0;
      }
      return next;
    });
  };

  const handleLogout = () => {
    if (window.confirm("确定退出管理模式吗？")) {
      setIsAdmin(false);
      localStorage.removeItem('is_admin');
    }
  };

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(i => 
        i.symbol.toLowerCase().includes(query) || 
        i.focusPoints.toLowerCase().includes(query) || 
        i.strategy.toLowerCase().includes(query)
      );
    }
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    return result;
  }, [insights, activeCategory, selectedMonth, searchQuery]);

  const { activeItems, archivedItems } = useMemo(() => {
    return {
      activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
      archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
    };
  }, [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' 
        ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' })
        : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    const entries = Object.entries(groups);
    return sortMode === 'category' 
      ? entries.sort((a, b) => CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any))
      : entries.sort((a, b) => b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  const handleSaveInsight = async (data: Partial<MarketInsight>) => {
    if (!isAdmin) return;
    const targetId = editingInsight ? editingInsight.id : Math.random().toString(36).substr(2, 9);
    const updatedTimestamp = data.updatedAt || Date.now();

    const newInsight: MarketInsight = {
      id: targetId,
      symbol: data.symbol || '',
      category: data.category || '美股',
      status: data.status || '震荡',
      focusPoints: data.focusPoints || '',
      strategy: data.strategy || '',
      entryLevel: data.entryLevel || '',
      updatedAt: updatedTimestamp,
      completionStatus: data.completionStatus || '进行中'
    };

    if (isSupabaseConfigured && supabase) {
      try {
        await supabase.from('insights').upsert({
          id: targetId,
          symbol: newInsight.symbol,
          category: newInsight.category,
          status: newInsight.status,
          focus_points: newInsight.focusPoints,
          strategy: newInsight.strategy,
          entry_level: newInsight.entryLevel,
          updated_at: updatedTimestamp,
          completion_status: newInsight.completionStatus
        });
      } catch (e) {
        console.error("Supabase upsert failed:", e);
      }
    }

    const updatedInsights = editingInsight 
      ? insights.map(i => i.id === targetId ? newInsight : i)
      : [newInsight, ...insights];

    setInsights(updatedInsights);
    localStorage.setItem('local_insights', JSON.stringify(updatedInsights));
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = async (id: string) => {
    if (!isAdmin) return;
    if (window.confirm('确定要删除这条记录吗？')) {
      if (isSupabaseConfigured && supabase) {
        await supabase.from('insights').delete().eq('id', id);
      }
      const updated = insights.filter(i => i.id !== id);
      setInsights(updated);
      localStorage.setItem('local_insights', JSON.stringify(updated));
    }
  };

  const handleToggleCompletionStatus = async (id: string) => {
    if (!isAdmin) return;
    const item = insights.find(i => i.id === id);
    if (!item) return;

    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    const currentIndex = statuses.indexOf(item.completionStatus);
    const nextStatus = statuses[(currentIndex + 1) % statuses.length];

    const newTime = Date.now();
    if (isSupabaseConfigured && supabase) {
      await supabase.from('insights').update({ completion_status: nextStatus, updated_at: newTime }).eq('id', id);
    }

    const updated = insights.map(i => i.id === id ? { ...i, completionStatus: nextStatus, updatedAt: newTime } : i);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-amber-100">
      <header className="sticky top-0 z-[100] bg-white/90 backdrop-blur-2xl border-b border-gray-100 px-8 h-[72px]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between h-full gap-8">
          {/* 品牌区 - 点击此处 5 次触发管理模式 */}
          <div 
            onClick={handleBrandClick}
            className="flex items-center gap-3 shrink-0 cursor-pointer group active:scale-95 transition-transform"
          >
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isAdmin ? 'bg-amber-500 shadow-xl shadow-amber-200 ring-2 ring-white/50' : 'bg-[#12141c]'}`}>
              <LayoutGrid className="w-5 h-5 text-white" />
            </div>
            <div className="flex flex-col -space-y-1">
              <h1 className="text-xl font-black text-[#12141c] tracking-tighter">市场周刊</h1>
              {clickCount > 0 && !isAdmin && (
                <div className="h-0.5 bg-amber-500 transition-all" style={{ width: `${(clickCount/5)*100}%` }} />
              )}
            </div>
          </div>

          <div className="flex-grow flex items-center gap-4 max-w-3xl">
            <div className="relative group flex-grow">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <Search className={`w-4 h-4 transition-colors ${searchQuery ? 'text-gray-900' : 'text-gray-300'}`} />
              </div>
              <input
                type="text"
                className="w-full bg-gray-100/60 border border-transparent focus:bg-white focus:border-gray-200 py-3 pl-11 pr-10 rounded-2xl text-[14px] font-bold outline-none transition-all placeholder:text-gray-400"
                placeholder="搜索洞察记录..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
              {searchQuery && (
                <button onClick={() => setSearchQuery('')} className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-300 hover:text-gray-900 transition-colors">
                  <X className="w-4 h-4" />
                </button>
              )}
            </div>

            <nav className="hidden xl:flex items-center gap-1 bg-gray-100/60 p-1.5 rounded-2xl shrink-0 border border-gray-50">
              {CATEGORIES.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`px-5 py-2.5 rounded-xl text-[13px] font-black transition-all ${activeCategory === cat ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400 hover:text-gray-900'}`}
                >
                  {cat}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4 shrink-0">
            {isAdmin && (
              <div className="flex items-center gap-3 animate-in fade-in slide-in-from-right-4 duration-500">
                <button 
                  onClick={() => { setEditingInsight(undefined); setShowForm(true); }} 
                  className="bg-[#12141c] text-white flex items-center gap-2 px-6 py-3 rounded-full hover:scale-105 transition-all shadow-xl shadow-gray-200 active:scale-95"
                >
                  <Plus className="w-4 h-4" />
                  <span className="text-sm font-black">记录观点</span>
                </button>
                <button 
                  onClick={handleLogout} 
                  title="退出管理模式"
                  className="p-3 bg-red-50 text-red-500 hover:bg-red-100 rounded-full transition-colors"
                >
                   <Lock className="w-4 h-4" />
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        <aside className="lg:w-64 space-y-12 flex-shrink-0">
          <div className="sticky top-[104px] space-y-10">
            <div>
              <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
                <CalendarDays className="w-3.5 h-3.5" /> 历史归档
              </h3>
              <div className="space-y-1">
                <button onClick={() => setSelectedMonth(null)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === null ? 'bg-[#12141c] text-white shadow-xl shadow-gray-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                  <span>全部记录</span>
                  <span className={`text-[10px] px-2 py-0.5 rounded-md ${selectedMonth === null ? 'bg-white/20' : 'bg-gray-100'}`}>{insights.length}</span>
                </button>
                {timelineGroups.map(([month, count]) => (
                  <button key={month} onClick={() => setSelectedMonth(month)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === month ? 'bg-[#12141c] text-white shadow-xl shadow-gray-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                    <span>{month}</span>
                    <span className={`text-[10px] px-2 py-0.5 rounded-md ${selectedMonth === month ? 'bg-white/20' : 'bg-gray-100'}`}>{count}</span>
                  </button>
                ))}
              </div>
            </div>

            {isAdmin && (
              <div className="p-6 rounded-[2rem] bg-emerald-50 border border-emerald-100 animate-pulse-slow">
                <div className="flex items-center gap-2 text-emerald-700 font-black text-xs mb-2">
                  <Unlock className="w-3 h-3" />
                  管理模式激活
                </div>
                <p className="text-[10px] font-bold text-emerald-600/70 leading-relaxed uppercase tracking-widest">
                  您现在可以直接编辑或删除任何卡片。
                </p>
              </div>
            )}
          </div>
        </aside>

        <main className="flex-grow">
          {loading && insights.length === 0 ? (
             <div className="flex flex-col items-center justify-center py-48 opacity-40">
                <p className="font-black tracking-[0.2em] uppercase text-xs text-gray-400">正在同步行情洞察...</p>
             </div>
          ) : (
            <>
              <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-20">
                <div>
                  <h2 className="text-6xl font-black text-[#12141c] tracking-tighter leading-tight italic mb-4">
                    追踪行情，<br />每日洞察。
                  </h2>
                </div>
                <div className="flex bg-gray-100/80 p-1.5 rounded-2xl border border-gray-100 shadow-inner shrink-0">
                  <button onClick={() => setSortMode('category')} className={`flex items-center gap-2 px-6 py-3 rounded-xl text-[13px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-sm border border-gray-100' : 'text-gray-400 hover:text-gray-600'}`}>
                    <ListFilter className="w-4 h-4" /> 类别视图
                  </button>
                  <button onClick={() => setSortMode('timeline')} className={`flex items-center gap-2 px-6 py-3 rounded-xl text-[13px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-sm border border-gray-100' : 'text-gray-400 hover:text-gray-600'}`}>
                    <CalendarDays className="w-4 h-4" /> 时间轴视图
                  </button>
                </div>
              </div>

              {activeItems.length > 0 ? (
                <div className="space-y-24">
                  {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                    <section key={groupLabel} className="animate-in fade-in duration-1000">
                      <div className="flex items-center gap-6 mb-12">
                        <span className="text-[14px] font-black tracking-widest uppercase bg-[#12141c] text-white px-6 py-2 rounded-2xl shadow-xl shadow-gray-200">{groupLabel}</span>
                        <div className="flex-grow h-[1px] bg-gray-100" />
                        <span className="text-[12px] font-bold text-gray-300 uppercase tracking-widest">{groupItems.length} 条洞察</span>
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                        {groupItems.map(insight => (
                          <MarketCard 
                            key={insight.id} 
                            insight={insight} 
                            onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}}
                            onDelete={isAdmin ? handleDeleteInsight : () => {}}
                            onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}}
                            isEditable={isAdmin}
                          />
                        ))}
                      </div>
                    </section>
                  ))}
                </div>
              ) : (
                <div className="text-center py-40 border-4 border-dashed border-gray-50 rounded-[4rem] bg-gray-50/30">
                  <div className="w-20 h-20 bg-white rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-xl shadow-gray-100">
                    <Plus className="w-10 h-10 text-gray-200" />
                  </div>
                  <h3 className="text-2xl font-black text-gray-900 tracking-tight">{searchQuery ? '没有找到匹配的记录' : '当前暂无进行中的洞察'}</h3>
                  {!isAdmin && <p className="text-gray-400 font-bold mt-2">请联系博主获取最新动态</p>}
                  {isAdmin && <p className="text-gray-400 font-bold mt-2">点击“记录观点”开始追踪市场动态</p>}
                </div>
              )}

              {archivedItems.length > 0 && (
                <div className="mt-60 pt-32 border-t border-gray-100">
                  <div className="flex items-center justify-between mb-16">
                      <div className="flex items-center gap-6">
                        <div className="w-14 h-14 bg-gray-100 rounded-2xl flex items-center justify-center">
                          <Archive className="w-6 h-6 text-gray-400" />
                        </div>
                        <div>
                          <h3 className="text-3xl font-black text-[#12141c] tracking-tight italic">历史归档</h3>
                          <p className="text-gray-400 font-bold">已结项或失效的市场研判</p>
                        </div>
                      </div>
                      <div className="px-5 py-2 bg-gray-100 rounded-full text-[12px] font-black text-gray-400">
                        {archivedItems.length} 份记录
                      </div>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10 grayscale opacity-40 hover:opacity-100 transition-opacity duration-700">
                    {archivedItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}}
                        onDelete={isAdmin ? handleDeleteInsight : () => {}}
                        onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}}
                        isEditable={isAdmin}
                      />
                    ))}
                  </div>
                </div>
              )}
            </>
          )}
        </main>
      </div>

      {showForm && isAdmin && (
        <InsightForm initialData={editingInsight} onSave={handleSaveInsight} onCancel={() => { setShowForm(false); setEditingInsight(undefined); }} />
      )}

      <footer className="mt-40 border-t border-gray-50 py-20 px-8">
        <div className="max-w-[1600px] mx-auto flex flex-col md:flex-row justify-between items-center gap-8">
          <div className="flex items-center gap-4">
             <div className="w-8 h-8 bg-[#12141c] rounded-lg" />
             <span className="text-xl font-black italic tracking-tighter">市场周刊.</span>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { supabase, isSupabaseConfigured } from './services/supabaseClient';
import { 
  Plus, 
  LayoutGrid, 
  ListFilter, 
  CalendarDays, 
  Archive, 
  Search, 
  X, 
  Lock,
  Unlock,
  Settings
} from 'lucide-react';

const ADMIN_PASSWORD = "8888"; 

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('category');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');

  const [isAdmin, setIsAdmin] = useState(() => localStorage.getItem('is_admin') === 'true');
  const [clickCount, setClickCount] = useState(0);
  const clickTimes = useRef<number[]>([]);

  // 统一的登录触发器
  const triggerAdminLogin = useCallback(() => {
    const pwd = prompt("管理模式身份确认：请输入密钥");
    if (pwd === ADMIN_PASSWORD) {
      setIsAdmin(true);
      localStorage.setItem('is_admin', 'true');
      alert("身份验证成功，管理功能已开启");
    } else if (pwd !== null) {
      alert("密钥错误，请重试");
    }
  }, []);

  // 快捷键监听：Ctrl + Shift + A
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.shiftKey && e.key.toLowerCase() === 'a') {
        e.preventDefault();
        if (!isAdmin) {
          triggerAdminLogin();
        } else {
          setEditingInsight(undefined);
          setShowForm(true);
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isAdmin, triggerAdminLogin]);

  // 自动重置进度条
  useEffect(() => {
    if (clickCount > 0) {
      const timer = setTimeout(() => setClickCount(0), 1500);
      return () => clearTimeout(timer);
    }
  }, [clickCount]);

  const fetchInsights = async () => {
    setLoading(true);
    if (isSupabaseConfigured && supabase) {
      try {
        const { data, error } = await supabase
          .from('insights')
          .select('*')
          .order('updated_at', { ascending: false });

        if (!error && data) {
          const mappedData = data.map((item: any) => ({
            id: item.id,
            symbol: item.symbol,
            category: item.category,
            status: item.status as any,
            focusPoints: item.focus_points,
            strategy: item.strategy,
            entryLevel: item.entry_level,
            updatedAt: item.updated_at,
            completionStatus: item.completion_status as any
          }));
          setInsights(mappedData);
          localStorage.setItem('local_insights', JSON.stringify(mappedData));
        } else {
          loadLocalData();
        }
      } catch (e) {
        loadLocalData();
      }
    } else {
      loadLocalData();
    }
    setLoading(false);
  };

  const loadLocalData = () => {
    const saved = localStorage.getItem('local_insights');
    if (saved) {
      setInsights(JSON.parse(saved));
    } else {
      setInsights(INITIAL_INSIGHTS);
    }
  };

  useEffect(() => {
    fetchInsights();
  }, []);

  // 全新设计的极速点击判定逻辑
  const handleBrandClick = () => {
    if (isAdmin) return;

    const now = Date.now();
    clickTimes.current.push(now);

    // 只保留最近5次点击
    if (clickTimes.current.length > 5) {
      clickTimes.current.shift();
    }

    setClickCount(clickTimes.current.length);

    // 判定：如果最近5次点击发生在2.5秒内
    if (clickTimes.current.length === 5) {
      const duration = now - clickTimes.current[0];
      if (duration < 2500) {
        clickTimes.current = [];
        setClickCount(0);
        // 稍微延迟确保UI反馈后再弹出
        setTimeout(triggerAdminLogin, 200);
      }
    }
  };

  const handleLogout = () => {
    if (window.confirm("确定退出管理模式吗？退出后将隐藏所有编辑按钮。")) {
      setIsAdmin(false);
      localStorage.removeItem('is_admin');
    }
  };

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(i => 
        i.symbol.toLowerCase().includes(query) || 
        i.focusPoints.toLowerCase().includes(query) || 
        i.strategy.toLowerCase().includes(query)
      );
    }
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    return result;
  }, [insights, activeCategory, selectedMonth, searchQuery]);

  const { activeItems, archivedItems } = useMemo(() => {
    return {
      activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
      archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
    };
  }, [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' 
        ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' })
        : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    const entries = Object.entries(groups);
    return sortMode === 'category' 
      ? entries.sort((a, b) => CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any))
      : entries.sort((a, b) => b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  const handleSaveInsight = async (data: Partial<MarketInsight>) => {
    if (!isAdmin) return;
    const targetId = editingInsight ? editingInsight.id : Math.random().toString(36).substr(2, 9);
    const updatedTimestamp = data.updatedAt || Date.now();

    const newInsight: MarketInsight = {
      id: targetId,
      symbol: data.symbol || '',
      category: data.category || '美股',
      status: data.status || '震荡',
      focusPoints: data.focusPoints || '',
      strategy: data.strategy || '',
      entryLevel: data.entryLevel || '',
      updatedAt: updatedTimestamp,
      completionStatus: data.completionStatus || '进行中'
    };

    if (isSupabaseConfigured && supabase) {
      try {
        await supabase.from('insights').upsert({
          id: targetId,
          symbol: newInsight.symbol,
          category: newInsight.category,
          status: newInsight.status,
          focus_points: newInsight.focusPoints,
          strategy: newInsight.strategy,
          entry_level: newInsight.entryLevel,
          updated_at: updatedTimestamp,
          completion_status: newInsight.completionStatus
        });
      } catch (e) {
        console.error("Supabase upsert failed:", e);
      }
    }

    const updatedInsights = editingInsight 
      ? insights.map(i => i.id === targetId ? newInsight : i)
      : [newInsight, ...insights];

    setInsights(updatedInsights);
    localStorage.setItem('local_insights', JSON.stringify(updatedInsights));
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = async (id: string) => {
    if (!isAdmin) return;
    if (window.confirm('确定要删除这条记录吗？')) {
      if (isSupabaseConfigured && supabase) {
        await supabase.from('insights').delete().eq('id', id);
      }
      const updated = insights.filter(i => i.id !== id);
      setInsights(updated);
      localStorage.setItem('local_insights', JSON.stringify(updated));
    }
  };

  const handleToggleCompletionStatus = async (id: string) => {
    if (!isAdmin) return;
    const item = insights.find(i => i.id === id);
    if (!item) return;

    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    const currentIndex = statuses.indexOf(item.completionStatus);
    const nextStatus = statuses[(currentIndex + 1) % statuses.length];

    const newTime = Date.now();
    if (isSupabaseConfigured && supabase) {
      await supabase.from('insights').update({ completion_status: nextStatus, updated_at: newTime }).eq('id', id);
    }

    const updated = insights.map(i => i.id === id ? { ...i, completionStatus: nextStatus, updatedAt: newTime } : i);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-amber-100">
      <header className="sticky top-0 z-[100] bg-white/90 backdrop-blur-2xl border-b border-gray-100 px-8 h-[72px]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between h-full gap-8">
          {/* 品牌区 - 点击此处 5 次触发密码框 */}
          <div 
            onClick={handleBrandClick}
            className="flex items-center gap-3 shrink-0 cursor-pointer group select-none"
          >
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all group-active:scale-75 ${isAdmin ? 'bg-amber-500 shadow-xl shadow-amber-200 ring-2 ring-white/50' : 'bg-[#12141c]'}`}>
              <LayoutGrid className="w-5 h-5 text-white" />
            </div>
            <div className="flex flex-col -space-y-1 relative">
              <h1 className="text-xl font-black text-[#12141c] tracking-tighter">市场周刊</h1>
              {/* 显眼的进度指示器 */}
              {!isAdmin && clickCount > 0 && (
                <div className="absolute -bottom-2 left-0 h-1 bg-amber-400 rounded-full transition-all duration-200" style={{ width: `${(clickCount/5)*100}%` }} />
              )}
            </div>
          </div>

          <div className="flex-grow flex items-center gap-4 max-w-3xl">
            <div className="relative group flex-grow">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <Search className={`w-4 h-4 transition-colors ${searchQuery ? 'text-gray-900' : 'text-gray-300'}`} />
              </div>
              <input
                type="text"
                className="w-full bg-gray-100/60 border border-transparent focus:bg-white focus:border-gray-200 py-3 pl-11 pr-10 rounded-2xl text-[14px] font-bold outline-none transition-all placeholder:text-gray-400"
                placeholder="搜索洞察记录..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
              {searchQuery && (
                <button onClick={() => setSearchQuery('')} className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-300 hover:text-gray-900 transition-colors">
                  <X className="w-4 h-4" />
                </button>
              )}
            </div>

            <nav className="hidden xl:flex items-center gap-1 bg-gray-100/60 p-1.5 rounded-2xl shrink-0 border border-gray-50">
              {CATEGORIES.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`px-5 py-2.5 rounded-xl text-[13px] font-black transition-all ${activeCategory === cat ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400 hover:text-gray-900'}`}
                >
                  {cat}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4 shrink-0">
            {isAdmin && (
              <div className="flex items-center gap-3 animate-in fade-in slide-in-from-right-4 duration-500">
                <button 
                  onClick={() => { setEditingInsight(undefined); setShowForm(true); }} 
                  className="bg-[#12141c] text-white flex items-center gap-2 px-6 py-3 rounded-full hover:scale-105 transition-all shadow-xl shadow-gray-200 active:scale-95"
                >
                  <Plus className="w-4 h-4" />
                  <span className="text-sm font-black">记录观点</span>
                </button>
                <button 
                  onClick={handleLogout} 
                  title="退出管理模式"
                  className="p-3 bg-red-50 text-red-500 hover:bg-red-100 rounded-full transition-colors"
                >
                   <Lock className="w-4 h-4" />
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        <aside className="lg:w-64 space-y-12 flex-shrink-0">
          <div className="sticky top-[104px] space-y-10">
            <div>
              <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
                <CalendarDays className="w-3.5 h-3.5" /> 历史归档
              </h3>
              <div className="space-y-1">
                <button onClick={() => setSelectedMonth(null)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === null ? 'bg-[#12141c] text-white shadow-xl shadow-gray-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                  <span>全部记录</span>
                  <span className={`text-[10px] px-2 py-0.5 rounded-md ${selectedMonth === null ? 'bg-white/20' : 'bg-gray-100'}`}>{insights.length}</span>
                </button>
                {timelineGroups.map(([month, count]) => (
                  <button key={month} onClick={() => setSelectedMonth(month)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === month ? 'bg-[#12141c] text-white shadow-xl shadow-gray-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                    <span>{month}</span>
                    <span className={`text-[10px] px-2 py-0.5 rounded-md ${selectedMonth === month ? 'bg-white/20' : 'bg-gray-100'}`}>{count}</span>
                  </button>
                ))}
              </div>
            </div>

            {isAdmin && (
              <div className="p-6 rounded-[2rem] bg-emerald-50 border border-emerald-100 animate-pulse-slow">
                <div className="flex items-center gap-2 text-emerald-700 font-black text-xs mb-2">
                  <Unlock className="w-3 h-3" />
                  管理模式激活
                </div>
                <p className="text-[10px] font-bold text-emerald-600/70 leading-relaxed uppercase tracking-widest">
                  您现在可以直接编辑或删除任何卡片。
                </p>
              </div>
            )}
          </div>
        </aside>

        <main className="flex-grow">
          {loading && insights.length === 0 ? (
             <div className="flex flex-col items-center justify-center py-48 opacity-40">
                <p className="font-black tracking-[0.2em] uppercase text-xs text-gray-400">正在同步行情洞察...</p>
             </div>
          ) : (
            <>
              <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-20">
                <div>
                  <h2 className="text-6xl font-black text-[#12141c] tracking-tighter leading-tight italic mb-4">
                    追踪行情，<br />每日洞察。
                  </h2>
                </div>
                <div className="flex bg-gray-100/80 p-1.5 rounded-2xl border border-gray-100 shadow-inner shrink-0">
                  <button onClick={() => setSortMode('category')} className={`flex items-center gap-2 px-6 py-3 rounded-xl text-[13px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-sm border border-gray-100' : 'text-gray-400 hover:text-gray-600'}`}>
                    <ListFilter className="w-4 h-4" /> 类别视图
                  </button>
                  <button onClick={() => setSortMode('timeline')} className={`flex items-center gap-2 px-6 py-3 rounded-xl text-[13px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-sm border border-gray-100' : 'text-gray-400 hover:text-gray-600'}`}>
                    <CalendarDays className="w-4 h-4" /> 时间轴视图
                  </button>
                </div>
              </div>

              {activeItems.length > 0 ? (
                <div className="space-y-24">
                  {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                    <section key={groupLabel} className="animate-in fade-in duration-1000">
                      <div className="flex items-center gap-6 mb-12">
                        <span className="text-[14px] font-black tracking-widest uppercase bg-[#12141c] text-white px-6 py-2 rounded-2xl shadow-xl shadow-gray-200">{groupLabel}</span>
                        <div className="flex-grow h-[1px] bg-gray-100" />
                        <span className="text-[12px] font-bold text-gray-300 uppercase tracking-widest">{groupItems.length} 条洞察</span>
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                        {groupItems.map(insight => (
                          <MarketCard 
                            key={insight.id} 
                            insight={insight} 
                            onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}}
                            onDelete={isAdmin ? handleDeleteInsight : () => {}}
                            onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}}
                            isEditable={isAdmin}
                          />
                        ))}
                      </div>
                    </section>
                  ))}
                </div>
              ) : (
                <div className="text-center py-40 border-4 border-dashed border-gray-50 rounded-[4rem] bg-gray-50/30">
                  <div className="w-20 h-20 bg-white rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-xl shadow-gray-100">
                    <Plus className="w-10 h-10 text-gray-200" />
                  </div>
                  <h3 className="text-2xl font-black text-gray-900 tracking-tight">{searchQuery ? '没有找到匹配的记录' : '当前暂无进行中的洞察'}</h3>
                  {!isAdmin && <p className="text-gray-400 font-bold mt-2">请联系博主获取最新动态</p>}
                  {isAdmin && <p className="text-gray-400 font-bold mt-2">点击“记录观点”开始追踪市场动态</p>}
                </div>
              )}

              {archivedItems.length > 0 && (
                <div className="mt-60 pt-32 border-t border-gray-100">
                  <div className="flex items-center justify-between mb-16">
                      <div className="flex items-center gap-6">
                        <div className="w-14 h-14 bg-gray-100 rounded-2xl flex items-center justify-center">
                          <Archive className="w-6 h-6 text-gray-400" />
                        </div>
                        <div>
                          <h3 className="text-3xl font-black text-[#12141c] tracking-tight italic">历史归档</h3>
                          <p className="text-gray-400 font-bold">已结项或失效的市场研判</p>
                        </div>
                      </div>
                      <div className="px-5 py-2 bg-gray-100 rounded-full text-[12px] font-black text-gray-400">
                        {archivedItems.length} 份记录
                      </div>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10 grayscale opacity-40 hover:opacity-100 transition-opacity duration-700">
                    {archivedItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}}
                        onDelete={isAdmin ? handleDeleteInsight : () => {}}
                        onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}}
                        isEditable={isAdmin}
                      />
                    ))}
                  </div>
                </div>
              )}
            </>
          )}
        </main>
      </div>

      {showForm && isAdmin && (
        <InsightForm initialData={editingInsight} onSave={handleSaveInsight} onCancel={() => { setShowForm(false); setEditingInsight(undefined); }} />
      )}

      <footer className="mt-40 border-t border-gray-50 py-20 px-8">
        <div className="max-w-[1600px] mx-auto flex flex-col md:flex-row justify-between items-center gap-8">
          <div className="flex items-center gap-4">
             <div className="w-8 h-8 bg-[#12141c] rounded-lg" />
             <span className="text-xl font-black italic tracking-tighter">市场周刊.</span>
          </div>
          {/* 底部隐形备用入口 - 万一 Logo 点击依然失效，可以点击这里 */}
          {!isAdmin && (
            <button 
              onClick={triggerAdminLogin}
              className="opacity-0 hover:opacity-10 text-[10px] text-gray-300 flex items-center gap-1 transition-opacity"
            >
              <Settings className="w-3 h-3" /> Admin Entry
            </button>
          )}
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { supabase, isSupabaseConfigured } from './services/supabaseClient';
import { 
  Plus, 
  LayoutGrid, 
  ListFilter, 
  CalendarDays, 
  Archive, 
  Search, 
  X, 
  Lock,
  Unlock,
  Settings,
  KeyRound
} from 'lucide-react';

const ADMIN_PASSWORD = "8888"; 

// 自定义登录组件，解决 prompt 被浏览器拦截的问题
const LoginModal: React.FC<{ isOpen: boolean; onClose: () => void; onVerify: (pwd: string) => void }> = ({ isOpen, onClose, onVerify }) => {
  const [pwd, setPwd] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen) {
      setTimeout(() => inputRef.current?.focus(), 100);
      setPwd('');
    }
  }, [isOpen]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-[#12141c]/80 backdrop-blur-xl animate-in fade-in duration-300">
      <div className="bg-white rounded-[2.5rem] p-10 w-full max-w-sm shadow-2xl border border-gray-100 animate-in zoom-in-95 duration-300">
        <div className="flex flex-col items-center text-center space-y-6">
          <div className="w-16 h-16 bg-amber-100 rounded-3xl flex items-center justify-center text-amber-600">
            <KeyRound className="w-8 h-8" />
          </div>
          <div>
            <h3 className="text-2xl font-black text-gray-900 tracking-tight">管理模式解锁</h3>
            <p className="text-gray-400 font-bold text-sm mt-1 uppercase tracking-widest">请输入身份密钥以继续</p>
          </div>
          <input
            ref={inputRef}
            type="password"
            value={pwd}
            onChange={(e) => setPwd(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && onVerify(pwd)}
            placeholder="••••"
            className="w-full bg-gray-50 border-2 border-transparent focus:border-amber-400 focus:bg-white p-5 rounded-2xl text-center text-2xl font-black tracking-[1em] outline-none transition-all placeholder:tracking-normal placeholder:text-sm placeholder:font-bold"
          />
          <div className="flex gap-3 w-full">
            <button onClick={onClose} className="flex-1 py-4 px-6 rounded-2xl border border-gray-100 text-gray-400 font-black text-sm hover:bg-gray-50 transition-colors">取消</button>
            <button onClick={() => onVerify(pwd)} className="flex-1 py-4 px-6 rounded-2xl bg-[#12141c] text-white font-black text-sm hover:scale-105 active:scale-95 transition-all shadow-xl shadow-gray-200">确认解锁</button>
          </div>
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('category');
  const [showForm, setShowForm] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');

  const [isAdmin, setIsAdmin] = useState(() => localStorage.getItem('is_admin') === 'true');
  const [clickCount, setClickCount] = useState(0);

  // 快捷键监听：Ctrl + Shift + A
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.shiftKey && e.key.toLowerCase() === 'a') {
        e.preventDefault();
        if (!isAdmin) {
          setShowLogin(true);
        } else {
          setEditingInsight(undefined);
          setShowForm(true);
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isAdmin]);

  // 点击 Logo 判定逻辑
  const handleBrandClick = () => {
    if (isAdmin) return;
    setClickCount(prev => {
      const next = prev + 1;
      if (next >= 5) {
        setShowLogin(true);
        return 0;
      }
      return next;
    });
  };

  // 自动重置进度条
  useEffect(() => {
    if (clickCount > 0) {
      const timer = setTimeout(() => setClickCount(0), 1500);
      return () => clearTimeout(timer);
    }
  }, [clickCount]);

  const onVerifyAdmin = (pwd: string) => {
    if (pwd === ADMIN_PASSWORD) {
      setIsAdmin(true);
      localStorage.setItem('is_admin', 'true');
      setShowLogin(false);
      alert("解锁成功！欢迎回来，管理员。");
    } else {
      alert("密钥错误，请重试");
    }
  };

  const fetchInsights = async () => {
    setLoading(true);
    if (isSupabaseConfigured && supabase) {
      try {
        const { data, error } = await supabase
          .from('insights')
          .select('*')
          .order('updated_at', { ascending: false });

        if (!error && data) {
          const mappedData = data.map((item: any) => ({
            id: item.id,
            symbol: item.symbol,
            category: item.category,
            status: item.status as any,
            focusPoints: item.focus_points,
            strategy: item.strategy,
            entryLevel: item.entry_level,
            updatedAt: item.updated_at,
            completionStatus: item.completion_status as any
          }));
          setInsights(mappedData);
          localStorage.setItem('local_insights', JSON.stringify(mappedData));
        } else {
          loadLocalData();
        }
      } catch (e) {
        loadLocalData();
      }
    } else {
      loadLocalData();
    }
    setLoading(false);
  };

  const loadLocalData = () => {
    const saved = localStorage.getItem('local_insights');
    if (saved) {
      setInsights(JSON.parse(saved));
    } else {
      setInsights(INITIAL_INSIGHTS);
    }
  };

  useEffect(() => {
    fetchInsights();
  }, []);

  const handleLogout = () => {
    if (window.confirm("确定退出管理模式吗？")) {
      setIsAdmin(false);
      localStorage.removeItem('is_admin');
    }
  };

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(i => 
        i.symbol.toLowerCase().includes(query) || 
        i.focusPoints.toLowerCase().includes(query) || 
        i.strategy.toLowerCase().includes(query)
      );
    }
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    return result;
  }, [insights, activeCategory, selectedMonth, searchQuery]);

  const { activeItems, archivedItems } = useMemo(() => {
    return {
      activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
      archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
    };
  }, [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' 
        ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' })
        : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    const entries = Object.entries(groups);
    return sortMode === 'category' 
      ? entries.sort((a, b) => CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any))
      : entries.sort((a, b) => b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  const handleSaveInsight = async (data: Partial<MarketInsight>) => {
    if (!isAdmin) return;
    const targetId = editingInsight ? editingInsight.id : Math.random().toString(36).substr(2, 9);
    const updatedTimestamp = data.updatedAt || Date.now();

    const newInsight: MarketInsight = {
      id: targetId,
      symbol: data.symbol || '',
      category: data.category || '美股',
      status: data.status || '震荡',
      focusPoints: data.focusPoints || '',
      strategy: data.strategy || '',
      entryLevel: data.entryLevel || '',
      updatedAt: updatedTimestamp,
      completionStatus: data.completionStatus || '进行中'
    };

    if (isSupabaseConfigured && supabase) {
      try {
        await supabase.from('insights').upsert({
          id: targetId,
          symbol: newInsight.symbol,
          category: newInsight.category,
          status: newInsight.status,
          focus_points: newInsight.focusPoints,
          strategy: newInsight.strategy,
          entry_level: newInsight.entryLevel,
          updated_at: updatedTimestamp,
          completion_status: newInsight.completionStatus
        });
      } catch (e) {
        console.error("Supabase upsert failed:", e);
      }
    }

    const updatedInsights = editingInsight 
      ? insights.map(i => i.id === targetId ? newInsight : i)
      : [newInsight, ...insights];

    setInsights(updatedInsights);
    localStorage.setItem('local_insights', JSON.stringify(updatedInsights));
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = async (id: string) => {
    if (!isAdmin) return;
    if (window.confirm('确定要删除这条记录吗？')) {
      if (isSupabaseConfigured && supabase) {
        await supabase.from('insights').delete().eq('id', id);
      }
      const updated = insights.filter(i => i.id !== id);
      setInsights(updated);
      localStorage.setItem('local_insights', JSON.stringify(updated));
    }
  };

  const handleToggleCompletionStatus = async (id: string) => {
    if (!isAdmin) return;
    const item = insights.find(i => i.id === id);
    if (!item) return;

    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    const currentIndex = statuses.indexOf(item.completionStatus);
    const nextStatus = statuses[(currentIndex + 1) % statuses.length];

    const newTime = Date.now();
    if (isSupabaseConfigured && supabase) {
      await supabase.from('insights').update({ completion_status: nextStatus, updated_at: newTime }).eq('id', id);
    }

    const updated = insights.map(i => i.id === id ? { ...i, completionStatus: nextStatus, updatedAt: newTime } : i);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-amber-100">
      <header className="sticky top-0 z-[100] bg-white/90 backdrop-blur-2xl border-b border-gray-100 px-8 h-[72px]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between h-full gap-8">
          {/* Logo 触发区 - 点击 5 次 */}
          <div 
            onClick={handleBrandClick}
            className="flex items-center gap-3 shrink-0 cursor-pointer group select-none active:scale-90 transition-transform"
          >
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isAdmin ? 'bg-amber-500 shadow-xl shadow-amber-200 ring-2 ring-white/50 animate-pulse' : 'bg-[#12141c]'}`}>
              <LayoutGrid className="w-5 h-5 text-white" />
            </div>
            <div className="flex flex-col -space-y-1 relative">
              <h1 className="text-xl font-black text-[#12141c] tracking-tighter">市场周刊</h1>
              {/* 进度提示条 */}
              {!isAdmin && clickCount > 0 && (
                <div className="absolute -bottom-2 left-0 h-1 bg-amber-400 rounded-full transition-all duration-200" style={{ width: `${(clickCount/5)*100}%` }} />
              )}
            </div>
          </div>

          <div className="flex-grow flex items-center gap-4 max-w-3xl">
            <div className="relative group flex-grow">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <Search className={`w-4 h-4 transition-colors ${searchQuery ? 'text-gray-900' : 'text-gray-300'}`} />
              </div>
              <input
                type="text"
                className="w-full bg-gray-100/60 border border-transparent focus:bg-white focus:border-gray-200 py-3 pl-11 pr-10 rounded-2xl text-[14px] font-bold outline-none transition-all placeholder:text-gray-400"
                placeholder="搜索洞察记录..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
              {searchQuery && (
                <button onClick={() => setSearchQuery('')} className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-300 hover:text-gray-900 transition-colors">
                  <X className="w-4 h-4" />
                </button>
              )}
            </div>

            <nav className="hidden xl:flex items-center gap-1 bg-gray-100/60 p-1.5 rounded-2xl shrink-0 border border-gray-50">
              {CATEGORIES.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`px-5 py-2.5 rounded-xl text-[13px] font-black transition-all ${activeCategory === cat ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400 hover:text-gray-900'}`}
                >
                  {cat}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4 shrink-0">
            {isAdmin && (
              <div className="flex items-center gap-3 animate-in fade-in slide-in-from-right-4 duration-500">
                <button 
                  onClick={() => { setEditingInsight(undefined); setShowForm(true); }} 
                  className="bg-[#12141c] text-white flex items-center gap-2 px-6 py-3 rounded-full hover:scale-105 transition-all shadow-xl shadow-gray-200 active:scale-95"
                >
                  <Plus className="w-4 h-4" />
                  <span className="text-sm font-black">记录观点</span>
                </button>
                <button 
                  onClick={handleLogout} 
                  title="退出管理模式"
                  className="p-3 bg-red-50 text-red-500 hover:bg-red-100 rounded-full transition-colors"
                >
                   <Lock className="w-4 h-4" />
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        <aside className="lg:w-64 space-y-12 flex-shrink-0">
          <div className="sticky top-[104px] space-y-10">
            <div>
              <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
                <CalendarDays className="w-3.5 h-3.5" /> 历史归档
              </h3>
              <div className="space-y-1">
                <button onClick={() => setSelectedMonth(null)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === null ? 'bg-[#12141c] text-white shadow-xl shadow-gray-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                  <span>全部记录</span>
                  <span className={`text-[10px] px-2 py-0.5 rounded-md ${selectedMonth === null ? 'bg-white/20' : 'bg-gray-100'}`}>{insights.length}</span>
                </button>
                {timelineGroups.map(([month, count]) => (
                  <button key={month} onClick={() => setSelectedMonth(month)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === month ? 'bg-[#12141c] text-white shadow-xl shadow-gray-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                    <span>{month}</span>
                    <span className={`text-[10px] px-2 py-0.5 rounded-md ${selectedMonth === month ? 'bg-white/20' : 'bg-gray-100'}`}>{count}</span>
                  </button>
                ))}
              </div>
            </div>

            {isAdmin && (
              <div className="p-6 rounded-[2rem] bg-emerald-50 border border-emerald-100 animate-pulse-slow">
                <div className="flex items-center gap-2 text-emerald-700 font-black text-xs mb-2">
                  <Unlock className="w-3 h-3" />
                  管理模式激活
                </div>
                <p className="text-[10px] font-bold text-emerald-600/70 leading-relaxed uppercase tracking-widest">
                  您现在可以直接编辑或删除任何卡片。
                </p>
              </div>
            )}
          </div>
        </aside>

        <main className="flex-grow">
          {loading && insights.length === 0 ? (
             <div className="flex flex-col items-center justify-center py-48 opacity-40">
                <p className="font-black tracking-[0.2em] uppercase text-xs text-gray-400">正在同步行情洞察...</p>
             </div>
          ) : (
            <>
              <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-20">
                <div>
                  <h2 className="text-6xl font-black text-[#12141c] tracking-tighter leading-tight italic mb-4">
                    追踪行情，<br />每日洞察。
                  </h2>
                </div>
                <div className="flex bg-gray-100/80 p-1.5 rounded-2xl border border-gray-100 shadow-inner shrink-0">
                  <button onClick={() => setSortMode('category')} className={`flex items-center gap-2 px-6 py-3 rounded-xl text-[13px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-sm border border-gray-100' : 'text-gray-400 hover:text-gray-600'}`}>
                    <ListFilter className="w-4 h-4" /> 类别视图
                  </button>
                  <button onClick={() => setSortMode('timeline')} className={`flex items-center gap-2 px-6 py-3 rounded-xl text-[13px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-sm border border-gray-100' : 'text-gray-400 hover:text-gray-600'}`}>
                    <CalendarDays className="w-4 h-4" /> 时间轴视图
                  </button>
                </div>
              </div>

              {activeItems.length > 0 ? (
                <div className="space-y-24">
                  {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                    <section key={groupLabel} className="animate-in fade-in duration-1000">
                      <div className="flex items-center gap-6 mb-12">
                        <span className="text-[14px] font-black tracking-widest uppercase bg-[#12141c] text-white px-6 py-2 rounded-2xl shadow-xl shadow-gray-200">{groupLabel}</span>
                        <div className="flex-grow h-[1px] bg-gray-100" />
                        <span className="text-[12px] font-bold text-gray-300 uppercase tracking-widest">{groupItems.length} 条洞察</span>
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                        {groupItems.map(insight => (
                          <MarketCard 
                            key={insight.id} 
                            insight={insight} 
                            onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}}
                            onDelete={isAdmin ? handleDeleteInsight : () => {}}
                            onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}}
                            isEditable={isAdmin}
                          />
                        ))}
                      </div>
                    </section>
                  ))}
                </div>
              ) : (
                <div className="text-center py-40 border-4 border-dashed border-gray-50 rounded-[4rem] bg-gray-50/30">
                  <div className="w-20 h-20 bg-white rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-xl shadow-gray-100">
                    <Plus className="w-10 h-10 text-gray-200" />
                  </div>
                  <h3 className="text-2xl font-black text-gray-900 tracking-tight">{searchQuery ? '没有找到匹配的记录' : '当前暂无进行中的洞察'}</h3>
                  {!isAdmin && <p className="text-gray-400 font-bold mt-2">请联系博主获取最新动态</p>}
                  {isAdmin && <p className="text-gray-400 font-bold mt-2">点击“记录观点”开始追踪市场动态</p>}
                </div>
              )}

              {archivedItems.length > 0 && (
                <div className="mt-60 pt-32 border-t border-gray-100">
                  <div className="flex items-center justify-between mb-16">
                      <div className="flex items-center gap-6">
                        <div className="w-14 h-14 bg-gray-100 rounded-2xl flex items-center justify-center">
                          <Archive className="w-6 h-6 text-gray-400" />
                        </div>
                        <div>
                          <h3 className="text-3xl font-black text-[#12141c] tracking-tight italic">历史归档</h3>
                          <p className="text-gray-400 font-bold">已结项或失效的市场研判</p>
                        </div>
                      </div>
                      <div className="px-5 py-2 bg-gray-100 rounded-full text-[12px] font-black text-gray-400">
                        {archivedItems.length} 份记录
                      </div>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10 grayscale opacity-40 hover:opacity-100 transition-opacity duration-700">
                    {archivedItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}}
                        onDelete={isAdmin ? handleDeleteInsight : () => {}}
                        onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}}
                        isEditable={isAdmin}
                      />
                    ))}
                  </div>
                </div>
              )}
            </>
          )}
        </main>
      </div>

      {showForm && isAdmin && (
        <InsightForm initialData={editingInsight} onSave={handleSaveInsight} onCancel={() => { setShowForm(false); setEditingInsight(undefined); }} />
      )}

      {/* 管理模式登录层 */}
      <LoginModal 
        isOpen={showLogin} 
        onClose={() => setShowLogin(false)} 
        onVerify={onVerifyAdmin} 
      />

      <footer className="mt-40 border-t border-gray-50 py-20 px-8">
        <div className="max-w-[1600px] mx-auto flex flex-col md:flex-row justify-between items-center gap-8">
          <div className="flex items-center gap-4">
             <div className="w-8 h-8 bg-[#12141c] rounded-lg" />
             <span className="text-xl font-black italic tracking-tighter">市场周刊.</span>
          </div>
          {!isAdmin && (
            <button 
              onClick={() => setShowLogin(true)}
              className="opacity-0 hover:opacity-10 text-[10px] text-gray-300 flex items-center gap-1 transition-opacity"
            >
              <Settings className="w-3 h-3" /> Admin Entry
            </button>
          )}
        </div>
      </footer>
    </div>
  );
};

export default App;

export type AssetStatus = '看涨' | '看跌' | '震荡';
export type CompletionStatus = '进行中' | '已完成' | '已失效';
export type SortMode = 'timeline' | 'category' | 'journal';
export type MarketMood = '贪婪' | '恐惧' | '冷静' | '警惕';

export interface MarketInsight {
  id: string;
  symbol: string;
  category: string;
  status: AssetStatus;
  focusPoints: string;
  strategy: string;
  entryLevel?: string;
  updatedAt: number;
  completionStatus: CompletionStatus;
}

export interface JournalEntry {
  id: string;
  date: number;
  content: string;
  mood: MarketMood;
  title: string;
}

export type Category = '全部' | '指数' | '加密货币' | '美股' | 'A股' | '外汇';

export interface AppState {
  insights: MarketInsight[];
  activeCategory: Category;
  isEditing: boolean;
  selectedInsight?: MarketInsight;
  sortMode: SortMode;
}

import React from 'react';
import { JournalEntry, MarketMood } from '../types';
import { Quote, Smile, Frown, Zap, ShieldAlert, Trash2, Edit3 } from 'lucide-react';

interface JournalSectionProps {
  entries: JournalEntry[];
  isAdmin: boolean;
  onEdit: (entry: JournalEntry) => void;
  onDelete: (id: string) => void;
}

const MoodIcon = ({ mood }: { mood: MarketMood }) => {
  switch (mood) {
    case '贪婪': return <Zap className="w-5 h-5 text-amber-500" />;
    case '恐惧': return <Frown className="w-5 h-5 text-purple-500" />;
    case '冷静': return <Smile className="w-5 h-5 text-blue-500" />;
    case '警惕': return <ShieldAlert className="w-5 h-5 text-red-500" />;
    default: return null;
  }
};

const JournalSection: React.FC<JournalSectionProps> = ({ entries, isAdmin, onEdit, onDelete }) => {
  return (
    <div className="max-w-4xl mx-auto space-y-16 py-10">
      {entries.length === 0 && (
        <div className="text-center py-20 opacity-30 italic font-serif text-xl">
          尚未记录任何市场随笔...
        </div>
      )}
      {entries.map((entry, index) => (
        <article key={entry.id} className="relative group animate-in fade-in slide-in-from-bottom-8 duration-700" style={{ animationDelay: `${index * 100}ms` }}>
          <div className="flex flex-col md:flex-row gap-8 md:gap-16">
            <div className="md:w-32 shrink-0">
              <div className="sticky top-28">
                <div className="text-sm font-black text-gray-300 uppercase tracking-[0.2em] mb-2">
                  {new Date(entry.date).toLocaleDateString('zh-CN', { month: 'short', day: 'numeric' })}
                </div>
                <div className="text-3xl font-serif italic text-gray-200">{new Date(entry.date).getFullYear()}</div>
                <div className="mt-4 flex items-center gap-2 px-3 py-1.5 rounded-full bg-gray-50 border border-gray-100 w-fit">
                   <MoodIcon mood={entry.mood} />
                   <span className="text-[10px] font-black uppercase text-gray-400">{entry.mood}</span>
                </div>
              </div>
            </div>

            <div className="flex-grow space-y-4">
              <div className="flex justify-between items-start">
                <h3 className="text-3xl font-black text-[#12141c] tracking-tight leading-tight group-hover:text-amber-600 transition-colors">
                  {entry.title}
                </h3>
                {isAdmin && (
                  <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button onClick={() => onEdit(entry)} className="p-2 hover:bg-amber-50 rounded-full text-amber-600"><Edit3 className="w-4 h-4" /></button>
                    <button onClick={() => onDelete(entry.id)} className="p-2 hover:bg-red-50 rounded-full text-red-500"><Trash2 className="w-4 h-4" /></button>
                  </div>
                )}
              </div>
              <div className="relative">
                <Quote className="absolute -left-8 -top-2 w-12 h-12 text-gray-50 -z-10" />
                <div className="text-lg leading-relaxed text-gray-600 font-medium whitespace-pre-wrap">
                  {entry.content}
                </div>
              </div>
            </div>
          </div>
          {index !== entries.length - 1 && (
            <div className="mt-16 h-px bg-gradient-to-r from-transparent via-gray-100 to-transparent" />
          )}
        </article>
      ))}
    </div>
  );
};

export default JournalSection;

import React, { useState } from 'react';
import { JournalEntry, MarketMood } from '../types';
import { X, Save } from 'lucide-react';

interface JournalFormProps {
  initialData?: JournalEntry;
  onSave: (data: Partial<JournalEntry>) => void;
  onCancel: () => void;
}

const JournalForm: React.FC<JournalFormProps> = ({ initialData, onSave, onCancel }) => {
  const [formData, setFormData] = useState<Partial<JournalEntry>>(
    initialData || {
      title: '',
      content: '',
      mood: '冷静',
      date: Date.now()
    }
  );

  const moods: MarketMood[] = ['冷静', '贪婪', '恐惧', '警惕'];

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-xl">
      <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-2xl overflow-hidden animate-in zoom-in-95 duration-300">
        <div className="px-10 py-8 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
          <h2 className="text-2xl font-black text-gray-900 italic">记录今日市场随笔</h2>
          <button onClick={onCancel} className="p-2 hover:bg-gray-200 rounded-full transition-colors"><X className="w-6 h-6" /></button>
        </div>
        <form onSubmit={(e) => { e.preventDefault(); onSave(formData); }} className="p-10 space-y-8">
          <div className="space-y-2">
             <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">今日标题</label>
             <input 
               required
               className="w-full text-3xl font-black text-[#12141c] outline-none placeholder:text-gray-100"
               placeholder="给今天的行情起个名字..."
               value={formData.title}
               onChange={e => setFormData({...formData, title: e.target.value})}
             />
          </div>

          <div className="flex gap-4">
            <div className="flex-1 space-y-2">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">市场情绪</label>
              <div className="flex gap-2">
                {moods.map(m => (
                  <button
                    key={m}
                    type="button"
                    onClick={() => setFormData({...formData, mood: m})}
                    className={`flex-1 py-3 rounded-2xl text-xs font-black border transition-all ${formData.mood === m ? 'bg-[#12141c] text-white border-transparent' : 'bg-white text-gray-400 border-gray-100 hover:border-gray-300'}`}
                  >
                    {m}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">随笔内容</label>
            <textarea 
              required
              rows={8}
              className="w-full p-6 bg-gray-50 rounded-[2rem] outline-none text-lg leading-relaxed font-medium focus:bg-white border-2 border-transparent focus:border-amber-100 transition-all"
              placeholder="写下你对目前宏观环境的思考、心态的变化、或者对未来走势的研判..."
              value={formData.content}
              onChange={e => setFormData({...formData, content: e.target.value})}
            />
          </div>

          <div className="flex gap-4 pt-4">
            <button type="button" onClick={onCancel} className="flex-1 py-5 rounded-full border border-gray-100 text-gray-400 font-black">取消</button>
            <button type="submit" className="flex-[2] py-5 rounded-full bg-[#12141c] text-white font-black flex items-center justify-center gap-2 hover:scale-[1.02] active:scale-95 transition-all">
              <Save className="w-5 h-5" /> 封存随笔
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default JournalForm;

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode, JournalEntry } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import JournalSection from './components/JournalSection';
import JournalForm from './components/JournalForm';
import { supabase, isSupabaseConfigured } from './services/supabaseClient';
import { 
  Plus, 
  LayoutGrid, 
  ListFilter, 
  CalendarDays, 
  Archive, 
  Search, 
  X, 
  Lock,
  Unlock,
  Settings,
  KeyRound,
  BookOpen
} from 'lucide-react';

const ADMIN_PASSWORD = "8888"; 

const LoginModal: React.FC<{ isOpen: boolean; onClose: () => void; onVerify: (pwd: string) => void }> = ({ isOpen, onClose, onVerify }) => {
  const [pwd, setPwd] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (isOpen) {
      setTimeout(() => inputRef.current?.focus(), 100);
      setPwd('');
    }
  }, [isOpen]);
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-[#12141c]/80 backdrop-blur-xl animate-in fade-in duration-300">
      <div className="bg-white rounded-[2.5rem] p-10 w-full max-w-sm shadow-2xl border border-gray-100 animate-in zoom-in-95 duration-300">
        <div className="flex flex-col items-center text-center space-y-6">
          <div className="w-16 h-16 bg-amber-100 rounded-3xl flex items-center justify-center text-amber-600"><KeyRound className="w-8 h-8" /></div>
          <div>
            <h3 className="text-2xl font-black text-gray-900 tracking-tight">管理模式解锁</h3>
            <p className="text-gray-400 font-bold text-sm mt-1 uppercase tracking-widest">请输入身份密钥以继续</p>
          </div>
          <input ref={inputRef} type="password" value={pwd} onChange={(e) => setPwd(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && onVerify(pwd)} placeholder="••••" className="w-full bg-gray-50 border-2 border-transparent focus:border-amber-400 focus:bg-white p-5 rounded-2xl text-center text-2xl font-black tracking-[1em] outline-none transition-all placeholder:tracking-normal placeholder:text-sm placeholder:font-bold" />
          <div className="flex gap-3 w-full">
            <button onClick={onClose} className="flex-1 py-4 px-6 rounded-2xl border border-gray-100 text-gray-400 font-black text-sm hover:bg-gray-50 transition-colors">取消</button>
            <button onClick={() => onVerify(pwd)} className="flex-1 py-4 px-6 rounded-2xl bg-[#12141c] text-white font-black text-sm hover:scale-105 active:scale-95 transition-all shadow-xl shadow-gray-200">确认解锁</button>
          </div>
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>([]);
  const [journals, setJournals] = useState<JournalEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('category');
  const [showForm, setShowForm] = useState(false);
  const [showJournalForm, setShowJournalForm] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [editingJournal, setEditingJournal] = useState<JournalEntry | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');

  const [isAdmin, setIsAdmin] = useState(() => localStorage.getItem('is_admin') === 'true');
  const [clickCount, setClickCount] = useState(0);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.shiftKey && e.key.toLowerCase() === 'a') {
        e.preventDefault();
        if (!isAdmin) setShowLogin(true);
        else sortMode === 'journal' ? setShowJournalForm(true) : setShowForm(true);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isAdmin, sortMode]);

  const handleBrandClick = () => {
    if (isAdmin) return;
    setClickCount(prev => {
      const next = prev + 1;
      if (next >= 5) { setShowLogin(true); return 0; }
      return next;
    });
  };

  useEffect(() => {
    if (clickCount > 0) {
      const timer = setTimeout(() => setClickCount(0), 1500);
      return () => clearTimeout(timer);
    }
  }, [clickCount]);

  const onVerifyAdmin = (pwd: string) => {
    if (pwd === ADMIN_PASSWORD) {
      setIsAdmin(true);
      localStorage.setItem('is_admin', 'true');
      setShowLogin(false);
      alert("解锁成功！欢迎回来，管理员。");
    } else {
      alert("密钥错误，请重试");
    }
  };

  const fetchAllData = async () => {
    setLoading(true);
    // Fetch Insights
    const savedInsights = localStorage.getItem('local_insights');
    setInsights(savedInsights ? JSON.parse(savedInsights) : INITIAL_INSIGHTS);

    // Fetch Journals
    const savedJournals = localStorage.getItem('local_journals');
    if (savedJournals) setJournals(JSON.parse(savedJournals));

    if (isSupabaseConfigured && supabase) {
      const { data: insData } = await supabase.from('insights').select('*').order('updated_at', { ascending: false });
      if (insData) {
        const mapped = insData.map((item: any) => ({
          id: item.id, symbol: item.symbol, category: item.category, status: item.status,
          focusPoints: item.focus_points, strategy: item.strategy, entryLevel: item.entry_level,
          updatedAt: item.updated_at, completionStatus: item.completion_status
        }));
        setInsights(mapped);
        localStorage.setItem('local_insights', JSON.stringify(mapped));
      }

      const { data: jrData } = await supabase.from('journals').select('*').order('date', { ascending: false });
      if (jrData) {
        setJournals(jrData);
        localStorage.setItem('local_journals', JSON.stringify(jrData));
      }
    }
    setLoading(false);
  };

  useEffect(() => { fetchAllData(); }, []);

  const handleLogout = () => {
    if (window.confirm("确定退出管理模式吗？")) {
      setIsAdmin(false);
      localStorage.removeItem('is_admin');
    }
  };

  // Journal Handlers
  const handleSaveJournal = async (data: Partial<JournalEntry>) => {
    const id = editingJournal ? editingJournal.id : Math.random().toString(36).substr(2, 9);
    const newEntry: JournalEntry = {
      id,
      title: data.title || '无题随笔',
      content: data.content || '',
      mood: data.mood || '冷静',
      date: data.date || Date.now()
    };

    if (isSupabaseConfigured && supabase) {
      await supabase.from('journals').upsert(newEntry);
    }

    const updated = editingJournal 
      ? journals.map(j => j.id === id ? newEntry : j)
      : [newEntry, ...journals];

    setJournals(updated);
    localStorage.setItem('local_journals', JSON.stringify(updated));
    setShowJournalForm(false);
    setEditingJournal(undefined);
  };

  const handleDeleteJournal = async (id: string) => {
    if (!window.confirm("确定删除这篇随笔吗？")) return;
    if (isSupabaseConfigured && supabase) await supabase.from('journals').delete().eq('id', id);
    const updated = journals.filter(j => j.id !== id);
    setJournals(updated);
    localStorage.setItem('local_journals', JSON.stringify(updated));
  };

  const handleSaveInsight = async (data: Partial<MarketInsight>) => {
    const id = editingInsight ? editingInsight.id : Math.random().toString(36).substr(2, 9);
    const updatedTimestamp = data.updatedAt || Date.now();
    const newInsight: MarketInsight = {
      id, symbol: data.symbol || '', category: data.category || '美股', status: data.status || '震荡',
      focusPoints: data.focusPoints || '', strategy: data.strategy || '', entryLevel: data.entryLevel || '',
      updatedAt: updatedTimestamp, completionStatus: data.completionStatus || '进行中'
    };
    if (isSupabaseConfigured && supabase) {
      await supabase.from('insights').upsert({
        id, symbol: newInsight.symbol, category: newInsight.category, status: newInsight.status,
        focus_points: newInsight.focusPoints, strategy: newInsight.strategy, entry_level: newInsight.entryLevel,
        updated_at: updatedTimestamp, completion_status: newInsight.completionStatus
      });
    }
    const updated = editingInsight ? insights.map(i => i.id === id ? newInsight : i) : [newInsight, ...insights];
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = async (id: string) => {
    if (!window.confirm('确定要删除这条记录吗？')) return;
    if (isSupabaseConfigured && supabase) await supabase.from('insights').delete().eq('id', id);
    const updated = insights.filter(i => i.id !== id);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  const handleToggleCompletionStatus = async (id: string) => {
    const item = insights.find(i => i.id === id);
    if (!item) return;
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    const nextStatus = statuses[(statuses.indexOf(item.completionStatus) + 1) % statuses.length];
    const newTime = Date.now();
    if (isSupabaseConfigured && supabase) await supabase.from('insights').update({ completion_status: nextStatus, updated_at: newTime }).eq('id', id);
    const updated = insights.map(i => i.id === id ? { ...i, completionStatus: nextStatus, updatedAt: newTime } : i);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(i => i.symbol.toLowerCase().includes(query) || i.focusPoints.toLowerCase().includes(query));
    }
    if (activeCategory !== '全部') result = result.filter(i => i.category === activeCategory);
    if (selectedMonth) {
      result = result.filter(i => `${new Date(i.updatedAt).getFullYear()}年${new Date(i.updatedAt).getMonth() + 1}月` === selectedMonth);
    }
    return result;
  }, [insights, activeCategory, selectedMonth, searchQuery]);

  const { activeItems, archivedItems } = useMemo(() => ({
    activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
    archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
  }), [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' }) : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    return Object.entries(groups).sort((a, b) => sortMode === 'category' ? CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any) : b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  return (
    <div className="min-h-screen flex flex-col selection:bg-amber-100">
      <header className="sticky top-0 z-[100] bg-white/90 backdrop-blur-2xl border-b border-gray-100 px-8 h-[72px]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between h-full gap-8">
          <div onClick={handleBrandClick} className="flex items-center gap-3 shrink-0 cursor-pointer group select-none active:scale-90 transition-transform">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isAdmin ? 'bg-amber-500 shadow-xl shadow-amber-200 ring-2 ring-white/50 animate-pulse' : 'bg-[#12141c]'}`}>
              <LayoutGrid className="w-5 h-5 text-white" />
            </div>
            <div className="flex flex-col -space-y-1 relative">
              <h1 className="text-xl font-black text-[#12141c] tracking-tighter">市场周刊</h1>
              {!isAdmin && clickCount > 0 && <div className="absolute -bottom-2 left-0 h-1 bg-amber-400 rounded-full transition-all duration-200" style={{ width: `${(clickCount/5)*100}%` }} />}
            </div>
          </div>
          <div className="flex-grow flex items-center gap-4 max-w-3xl">
            <div className="relative group flex-grow">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <Search className={`w-4 h-4 transition-colors ${searchQuery ? 'text-gray-900' : 'text-gray-300'}`} />
              </div>
              <input type="text" className="w-full bg-gray-100/60 border border-transparent focus:bg-white focus:border-gray-200 py-3 pl-11 pr-10 rounded-2xl text-[14px] font-bold outline-none transition-all placeholder:text-gray-400" placeholder="搜索行情..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
            </div>
            <nav className="hidden xl:flex items-center gap-1 bg-gray-100/60 p-1.5 rounded-2xl shrink-0">
              {CATEGORIES.map(cat => (
                <button key={cat} onClick={() => { setActiveCategory(cat); setSortMode('category'); }} className={`px-5 py-2.5 rounded-xl text-[13px] font-black transition-all ${activeCategory === cat && sortMode !== 'journal' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400 hover:text-gray-900'}`}>{cat}</button>
              ))}
            </nav>
          </div>
          <div className="flex items-center gap-4 shrink-0">
            {isAdmin && (
              <div className="flex items-center gap-3">
                <button onClick={() => { if (sortMode === 'journal') setShowJournalForm(true); else setShowForm(true); }} className="bg-[#12141c] text-white flex items-center gap-2 px-6 py-3 rounded-full hover:scale-105 transition-all shadow-xl shadow-gray-200"><Plus className="w-4 h-4" /><span className="text-sm font-black">记录{sortMode === 'journal' ? '随笔' : '观点'}</span></button>
                <button onClick={handleLogout} className="p-3 bg-red-50 text-red-500 rounded-full"><Lock className="w-4 h-4" /></button>
              </div>
            )}
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        <aside className="lg:w-64 space-y-12 shrink-0">
          <div className="sticky top-[104px] space-y-10">
            <div>
              <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2"><BookOpen className="w-3.5 h-3.5" /> 研判维度</h3>
              <div className="space-y-1">
                 <button onClick={() => setSortMode('category')} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center gap-3 ${sortMode === 'category' || sortMode === 'timeline' ? 'bg-[#12141c] text-white shadow-xl shadow-gray-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                   <LayoutGrid className="w-4 h-4" /> 资产视图
                 </button>
                 <button onClick={() => setSortMode('journal')} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center gap-3 ${sortMode === 'journal' ? 'bg-amber-500 text-white shadow-xl shadow-amber-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                   <BookOpen className="w-4 h-4" /> 宏观随笔
                 </button>
              </div>
            </div>

            {(sortMode === 'category' || sortMode === 'timeline') && (
              <div>
                <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2"><CalendarDays className="w-3.5 h-3.5" /> 历史归档</h3>
                <div className="space-y-1">
                  <button onClick={() => setSelectedMonth(null)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === null ? 'bg-gray-200 text-gray-900' : 'text-gray-500 hover:bg-gray-100'}`}>
                    <span>全部记录</span>
                    <span className="text-[10px] px-2 py-0.5 rounded-md bg-white/50">{insights.length}</span>
                  </button>
                  {timelineGroups.map(([month, count]) => (
                    <button key={month} onClick={() => setSelectedMonth(month)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === month ? 'bg-gray-200 text-gray-900' : 'text-gray-500 hover:bg-gray-100'}`}>
                      <span>{month}</span>
                      <span className="text-[10px] px-2 py-0.5 rounded-md bg-white/50">{count}</span>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </aside>

        <main className="flex-grow">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-20">
            <h2 className="text-6xl font-black text-[#12141c] tracking-tighter leading-tight italic">
              {sortMode === 'journal' ? <>市场情绪<br />交易日记。</> : <>追踪行情，<br />每日洞察。</>}
            </h2>
            {sortMode !== 'journal' && (
              <div className="flex bg-gray-100/80 p-1.5 rounded-2xl border border-gray-100 shadow-inner shrink-0">
                <button onClick={() => setSortMode('category')} className={`flex items-center gap-2 px-6 py-3 rounded-xl text-[13px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400'}`}><ListFilter className="w-4 h-4" /> 类别</button>
                <button onClick={() => setSortMode('timeline')} className={`flex items-center gap-2 px-6 py-3 rounded-xl text-[13px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400'}`}><CalendarDays className="w-4 h-4" /> 时间</button>
              </div>
            )}
          </div>

          {sortMode === 'journal' ? (
            <JournalSection entries={journals} isAdmin={isAdmin} onEdit={(j) => { setEditingJournal(j); setShowJournalForm(true); }} onDelete={handleDeleteJournal} />
          ) : (
            <>
              {activeItems.length > 0 ? (
                <div className="space-y-24">
                  {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                    <section key={groupLabel}>
                      <div className="flex items-center gap-6 mb-12">
                        <span className="text-[14px] font-black tracking-widest uppercase bg-[#12141c] text-white px-6 py-2 rounded-2xl">{groupLabel}</span>
                        <div className="flex-grow h-[1px] bg-gray-100" />
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                        {groupItems.map(i => <MarketCard key={i.id} insight={i} onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}} onDelete={isAdmin ? handleDeleteInsight : () => {}} onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}} isEditable={isAdmin} />)}
                      </div>
                    </section>
                  ))}
                </div>
              ) : (
                <div className="text-center py-40 bg-gray-50/30 border-4 border-dashed border-gray-50 rounded-[4rem]">
                  <h3 className="text-2xl font-black text-gray-900">暂无匹配记录</h3>
                </div>
              )}
              {archivedItems.length > 0 && (
                <div className="mt-60 pt-32 border-t border-gray-100">
                  <h3 className="text-3xl font-black mb-16 italic">历史归档</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10 grayscale opacity-40 hover:opacity-100 transition-all duration-700">
                    {archivedItems.map(i => <MarketCard key={i.id} insight={i} onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}} onDelete={isAdmin ? handleDeleteInsight : () => {}} onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}} isEditable={isAdmin} />)}
                  </div>
                </div>
              )}
            </>
          )}
        </main>
      </div>

      {showForm && isAdmin && <InsightForm initialData={editingInsight} onSave={handleSaveInsight} onCancel={() => { setShowForm(false); setEditingInsight(undefined); }} />}
      {showJournalForm && isAdmin && <JournalForm initialData={editingJournal} onSave={handleSaveJournal} onCancel={() => { setShowJournalForm(false); setEditingJournal(undefined); }} />}
      <LoginModal isOpen={showLogin} onClose={() => setShowLogin(false)} onVerify={onVerifyAdmin} />
      <footer className="mt-40 border-t border-gray-50 py-20 px-8">
        <div className="max-w-[1600px] mx-auto flex justify-between items-center italic font-black">市场周刊.</div>
      </footer>
    </div>
  );
};

export default App;

export type AssetStatus = '看涨' | '看跌' | '震荡';
export type CompletionStatus = '进行中' | '已完成' | '已失效';
export type SortMode = 'timeline' | 'category' | 'journal';
export type MarketMood = '贪婪' | '恐惧' | '冷静' | '警惕';
export type EntryType = '随笔' | '新闻' | '逻辑' | '灵感';

export interface MarketInsight {
  id: string;
  symbol: string;
  category: string;
  status: AssetStatus;
  focusPoints: string;
  strategy: string;
  entryLevel?: string;
  updatedAt: number;
  completionStatus: CompletionStatus;
}

export interface JournalEntry {
  id: string;
  date: number;
  content: string;
  mood: MarketMood;
  title?: string;
  type?: EntryType;
  source?: string;
}

export type Category = '全部' | '指数' | '加密货币' | '美股' | 'A股' | '外汇';

export interface AppState {
  insights: MarketInsight[];
  activeCategory: Category;
  isEditing: boolean;
  selectedInsight?: MarketInsight;
  sortMode: SortMode;
}

import React from 'react';
import { JournalEntry, MarketMood, EntryType } from '../types';
import { Quote, Smile, Frown, Zap, ShieldAlert, Trash2, Edit3, Link, MessageSquare, Lightbulb, Newspaper } from 'lucide-react';

interface JournalSectionProps {
  entries: JournalEntry[];
  isAdmin: boolean;
  onEdit: (entry: JournalEntry) => void;
  onDelete: (id: string) => void;
}

const MoodIcon = ({ mood }: { mood: MarketMood }) => {
  switch (mood) {
    case '贪婪': return <Zap className="w-4 h-4 text-amber-500" />;
    case '恐惧': return <Frown className="w-4 h-4 text-purple-500" />;
    case '冷静': return <Smile className="w-4 h-4 text-emerald-500" />;
    case '警惕': return <ShieldAlert className="w-4 h-4 text-red-500" />;
    default: return null;
  }
};

const TypeIcon = ({ type }: { type?: EntryType }) => {
  switch (type) {
    case '新闻': return <Newspaper className="w-4 h-4" />;
    case '灵感': return <Lightbulb className="w-4 h-4" />;
    case '逻辑': return <Zap className="w-4 h-4" />;
    default: return <MessageSquare className="w-4 h-4" />;
  }
};

const formatTime = (timestamp: number) => {
  const now = Date.now();
  const diff = now - timestamp;
  if (diff < 60000) return '刚刚';
  if (diff < 3600000) return `${Math.floor(diff / 60000)}分钟前`;
  if (diff < 86400000) return `${Math.floor(diff / 3600000)}小时前`;
  return new Date(timestamp).toLocaleDateString('zh-CN', { month: 'short', day: 'numeric' });
};

