    }

    setNotifications(prev => {
      const updated = [newNote, ...prev].slice(0, 30);
      localStorage.setItem('local_notifications', JSON.stringify(updated));
      return updated;
    });
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.shiftKey && e.key.toLowerCase() === 'a') {
        e.preventDefault();
        if (!isAdmin) setShowLogin(true);
        else sortMode === 'journal' ? setShowJournalForm(true) : setShowForm(true);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isAdmin, sortMode]);

  const handleBrandClick = () => {
    if (isAdmin) return;
    setClickCount(prev => {
      const next = prev + 1;
      if (next >= 5) { setShowLogin(true); return 0; }
      return next;
    });
  };

  useEffect(() => {
    if (clickCount > 0) {
      const timer = setTimeout(() => setClickCount(0), 1500);
      return () => clearTimeout(timer);
    }
  }, [clickCount]);

  const onVerifyAdmin = (pwd: string) => {
    if (pwd === ADMIN_PASSWORD) {
      setIsAdmin(true);
      localStorage.setItem('is_admin', 'true');
      setShowLogin(false);
      addNotification('系统消息', '管理模式已解锁', 'system');
    } else {
      alert("密钥错误，请重试");
    }
  };

  const fetchAllData = async () => {
    setLoading(true);
    // 优先加载本地
    const savedInsights = localStorage.getItem('local_insights');
    setInsights(savedInsights ? JSON.parse(savedInsights) : INITIAL_INSIGHTS);
    const savedJournals = localStorage.getItem('local_journals');
    if (savedJournals) setJournals(JSON.parse(savedJournals));
    const savedNotifications = localStorage.getItem('local_notifications');
    if (savedNotifications) setNotifications(JSON.parse(savedNotifications));

    if (isSupabaseConfigured && supabase) {
      // 同步 Insights
      const { data: insData } = await supabase.from('insights').select('*').order('updated_at', { ascending: false });
      if (insData) {
        const mapped = insData.map((item: any) => ({
          id: item.id, symbol: item.symbol, category: item.category, status: item.status,
          focusPoints: item.focus_points, strategy: item.strategy, entryLevel: item.entry_level,
          updatedAt: item.updated_at, completionStatus: item.completion_status
        }));
        setInsights(mapped);
        localStorage.setItem('local_insights', JSON.stringify(mapped));
      }

      // 同步 Journals
      const { data: jrData } = await supabase.from('journals').select('*').order('date', { ascending: false });
      if (jrData) {
        setJournals(jrData);
        localStorage.setItem('local_journals', JSON.stringify(jrData));
      }

      // 同步 Notifications
      const { data: noteData } = await supabase.from('notifications').select('*').order('timestamp', { ascending: false }).limit(30);
      if (noteData) {
        const mappedNotes = noteData.map((n: any) => ({
          id: n.id,
          title: n.title,
          message: n.message,
          timestamp: n.timestamp,
          isRead: n.is_read,
          type: n.type
        }));
        setNotifications(mappedNotes);
        localStorage.setItem('local_notifications', JSON.stringify(mappedNotes));
      }
    }
    setLoading(false);
  };

  useEffect(() => { fetchAllData(); }, []);

  const handleLogout = () => {
    if (window.confirm("确定退出管理模式吗？")) {
      setIsAdmin(false);
      localStorage.removeItem('is_admin');
      addNotification('系统消息', '已安全退出管理模式', 'system');
    }
  };

  const handleSaveJournal = async (data: Partial<JournalEntry>) => {
    const id = editingJournal ? editingJournal.id : Math.random().toString(36).substr(2, 9);
    const newEntry: JournalEntry = {
      id,
      title: data.title || '',
      content: data.content || '',
      mood: data.mood || '冷静',
      type: (data.type as EntryType) || '随笔',
      source: data.source || '',
      date: data.date || Date.now()
    };

    if (newEntry.type === '新闻' && !editingJournal) {
      addNotification('发现最新资讯', newEntry.title || '捕获到一条市场实时动态', 'news');
    }

    if (isSupabaseConfigured && supabase) await supabase.from('journals').upsert(newEntry);
    const updated = editingJournal ? journals.map(j => j.id === id ? newEntry : j) : [newEntry, ...journals];
    setJournals(updated.sort((a, b) => b.date - a.date));
    localStorage.setItem('local_journals', JSON.stringify(updated));
    setShowJournalForm(false);
    setEditingJournal(undefined);
  };

  const handleDeleteJournal = async (id: string) => {
    if (!window.confirm("确定从瀑布流中移除这条记录吗？")) return;
    if (isSupabaseConfigured && supabase) await supabase.from('journals').delete().eq('id', id);
    const updated = journals.filter(j => j.id !== id);
    setJournals(updated);
    localStorage.setItem('local_journals', JSON.stringify(updated));
  };

  const handleSaveInsight = async (data: Partial<MarketInsight>) => {
    const id = editingInsight ? editingInsight.id : Math.random().toString(36).substr(2, 9);
    const updatedTimestamp = data.updatedAt || Date.now();
    const newInsight: MarketInsight = {
      id, symbol: data.symbol || '', category: data.category || '美股', status: data.status || '震荡',
      focusPoints: data.focusPoints || '', strategy: data.strategy || '', entryLevel: data.entryLevel || '',
      updatedAt: updatedTimestamp, completionStatus: data.completionStatus || '进行中'
    };

    if (editingInsight && editingInsight.status !== newInsight.status) {
      addNotification('行情研判变更', `${newInsight.symbol} 状态从 [${editingInsight.status}] 调整为 [${newInsight.status}]`, 'market');
    }

    if (isSupabaseConfigured && supabase) {
      await supabase.from('insights').upsert({
        id, symbol: newInsight.symbol, category: newInsight.category, status: newInsight.status,
        focus_points: newInsight.focusPoints, strategy: newInsight.strategy, entry_level: newInsight.entryLevel,
        updated_at: updatedTimestamp, completion_status: newInsight.completionStatus
      });
    }
    const updated = editingInsight ? insights.map(i => i.id === id ? newInsight : i) : [newInsight, ...insights];
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = async (id: string) => {
    if (!window.confirm('确定要删除这条记录吗？')) return;
    if (isSupabaseConfigured && supabase) await supabase.from('insights').delete().eq('id', id);
    const updated = insights.filter(i => i.id !== id);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  const handleToggleCompletionStatus = async (id: string) => {
    const item = insights.find(i => i.id === id);
    if (!item) return;
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    const nextStatus = statuses[(statuses.indexOf(item.completionStatus) + 1) % statuses.length];
    const newTime = Date.now();

    addNotification('研判归档', `${item.symbol} 观点现已标记为 [${nextStatus}]`, 'system');

    if (isSupabaseConfigured && supabase) await supabase.from('insights').update({ completion_status: nextStatus, updated_at: newTime }).eq('id', id);
    const updated = insights.map(i => i.id === id ? { ...i, completionStatus: nextStatus, updatedAt: newTime } : i);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  const handleMarkAsRead = async (id: string) => {
    if (isSupabaseConfigured && supabase) {
      await supabase.from('notifications').update({ is_read: true }).eq('id', id);
    }
    setNotifications(prev => {
      const updated = prev.map(n => n.id === id ? { ...n, isRead: true } : n);
      localStorage.setItem('local_notifications', JSON.stringify(updated));
      return updated;
    });
  };

  const handleClearAllNotes = async () => {
    if (window.confirm('确认清除所有历史消息吗？')) {
      if (isSupabaseConfigured && supabase) {
        // 在实际应用中，通常会有用户 ID，这里我们假设清除全部
        await supabase.from('notifications').delete().neq('id', 'keep_all');
      }
      setNotifications([]);
      localStorage.setItem('local_notifications', JSON.stringify([]));
    }
  };

  const handleDeleteNote = async (id: string) => {
    if (isSupabaseConfigured && supabase) {
      await supabase.from('notifications').delete().eq('id', id);
    }
    setNotifications(prev => {
      const updated = prev.filter(n => n.id !== id);
      localStorage.setItem('local_notifications', JSON.stringify(updated));
      return updated;
    });
  };

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(i => i.symbol.toLowerCase().includes(query) || i.focusPoints.toLowerCase().includes(query));
    }
    if (activeCategory !== '全部') result = result.filter(i => i.category === activeCategory);
    if (selectedMonth) {
      result = result.filter(i => `${new Date(i.updatedAt).getFullYear()}年${new Date(i.updatedAt).getMonth() + 1}月` === selectedMonth);
    }
    return result;
  }, [insights, activeCategory, selectedMonth, searchQuery]);

  const filteredJournals = useMemo(() => {
    let result = journals;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(j => 
        j.title?.toLowerCase().includes(query) || 
        j.content.toLowerCase().includes(query) ||
        j.type?.toLowerCase().includes(query)
      );
    }
    return result;
  }, [journals, searchQuery]);

  const { activeItems, archivedItems } = useMemo(() => ({
    activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
    archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
  }), [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' }) : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    return Object.entries(groups).sort((a, b) => sortMode === 'category' ? CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any) : b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  return (
    <div className="min-h-screen flex flex-col selection:bg-amber-100 pb-20">
      <header className="sticky top-0 z-[100] bg-white/80 backdrop-blur-2xl border-b border-gray-100 px-8 h-[72px]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between h-full gap-8">
          <div onClick={handleBrandClick} className="flex items-center gap-3 shrink-0 cursor-pointer group select-none active:scale-90 transition-transform">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isAdmin ? 'bg-amber-500 shadow-xl shadow-amber-200 ring-2 ring-white/50 animate-pulse' : 'bg-[#12141c]'}`}>
              <LayoutGrid className="w-5 h-5 text-white" />
            </div>
            <div className="flex flex-col -space-y-1 relative">
              <h1 className="text-xl font-black text-[#12141c] tracking-tighter">市场周刊</h1>
              {!isAdmin && clickCount > 0 && <div className="absolute -bottom-2 left-0 h-1 bg-amber-400 rounded-full transition-all duration-200" style={{ width: `${(clickCount/5)*100}%` }} />}
            </div>
          </div>
          <div className="flex-grow flex items-center gap-4 max-w-3xl">
            <div className="relative group flex-grow">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <Search className={`w-4 h-4 transition-colors ${searchQuery ? 'text-gray-900' : 'text-gray-300'}`} />
              </div>
              <input type="text" className="w-full bg-gray-100/60 border border-transparent focus:bg-white focus:border-gray-200 py-3 pl-11 pr-10 rounded-2xl text-[14px] font-bold outline-none transition-all placeholder:text-gray-400" placeholder={`在${sortMode === 'journal' ? '瀑布流' : '洞察'}中搜索...`} value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
              {searchQuery && (
                <button onClick={() => setSearchQuery('')} className="absolute inset-y-0 right-0 pr-4 flex items-center text-gray-400 hover:text-gray-600">
                  <span className="text-[10px] font-black uppercase tracking-widest px-1.5 py-0.5 bg-gray-200 rounded-md">清除</span>
                </button>
              )}
            </div>
          </div>
          <div className="flex items-center gap-4 shrink-0">
            <NotificationCenter 
              notifications={notifications} 
              onMarkAsRead={handleMarkAsRead} 
              onClearAll={handleClearAllNotes} 
              onDelete={handleDeleteNote}
            />

            {isAdmin && (
              <div className="flex items-center gap-3 pl-4 border-l border-gray-100">
                <button onClick={() => { if (sortMode === 'journal') setShowJournalForm(true); else setShowForm(true); }} className="bg-[#12141c] text-white flex items-center gap-2 px-6 py-3 rounded-full hover:scale-105 transition-all shadow-xl shadow-gray-200"><Plus className="w-4 h-4" /><span className="text-sm font-black">投递{sortMode === 'journal' ? '信息' : '观点'}</span></button>
                <button onClick={handleLogout} className="p-3 bg-red-50 text-red-500 rounded-full hover:bg-red-100 transition-colors"><Lock className="w-4 h-4" /></button>
              </div>
            )}
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        <aside className="lg:w-64 space-y-12 shrink-0">
          <div className="sticky top-[104px] space-y-10">
            <div>
              <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2"><BookOpen className="w-3.5 h-3.5" /> 研判维度</h3>
              <div className="space-y-1">
                 <button onClick={() => setSortMode('category')} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center gap-3 ${sortMode === 'category' || sortMode === 'timeline' ? 'bg-[#12141c] text-white shadow-xl shadow-gray-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                   <LayoutGrid className="w-4 h-4" /> 核心资产
                 </button>
                 <button onClick={() => setSortMode('journal')} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center gap-3 ${sortMode === 'journal' ? 'bg-amber-500 text-white shadow-xl shadow-amber-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                   <Sparkles className="w-4 h-4" /> 信息瀑布流
                 </button>
              </div>
            </div>

            {(sortMode === 'category' || sortMode === 'timeline') && (
              <div>
                <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2"><CalendarDays className="w-3.5 h-3.5" /> 历史归档</h3>
                <div className="space-y-1">
                  <button onClick={() => setSelectedMonth(null)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === null ? 'bg-gray-200 text-gray-900' : 'text-gray-500 hover:bg-gray-100'}`}>
                    <span>全部记录</span>
                    <span className="text-[10px] px-2 py-0.5 rounded-md bg-white/50">{insights.length}</span>
                  </button>
                  {timelineGroups.map(([month, count]) => (
                    <button key={month} onClick={() => setSelectedMonth(month)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === month ? 'bg-gray-200 text-gray-900' : 'text-gray-500 hover:bg-gray-100'}`}>
                      <span>{month}</span>
                      <span className="text-[10px] px-2 py-0.5 rounded-md bg-white/50">{count}</span>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </aside>

        <main className="flex-grow">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-16">
            <div>
              <h2 className="text-6xl font-black text-[#12141c] tracking-tighter leading-tight italic">
                {sortMode === 'journal' ? <>信息捕捉<br />瀑布流。</> : <>追踪行情，<br />每日洞察。</>}
              </h2>
              {sortMode === 'journal' && (
                <p className="mt-4 text-gray-400 font-bold text-lg">在此汇聚碎片化的市场资讯、研报核心及交易笔记。</p>
              )}
            </div>
          </div>

          {sortMode === 'journal' ? (
            <>
              {isAdmin && (
                <div 
                  onClick={() => setShowJournalForm(true)}
                  className="max-w-3xl mx-auto mb-12 p-6 bg-white rounded-3xl border border-dashed border-gray-200 flex items-center gap-4 text-gray-300 hover:text-gray-400 hover:border-amber-200 hover:bg-amber-50/30 cursor-pointer transition-all group"
                >
                   <div className="w-12 h-12 rounded-2xl bg-gray-50 flex items-center justify-center group-hover:bg-amber-500 group-hover:text-white transition-all">
                      <Zap className="w-6 h-6" />
                   </div>
                   <span className="text-xl font-bold tracking-tight">在这里捕捉市场动态...</span>
                </div>
              )}
              <JournalSection entries={filteredJournals} isAdmin={isAdmin} onEdit={(j) => { setEditingJournal(j); setShowJournalForm(true); }} onDelete={handleDeleteJournal} />
            </>
          ) : (
            <>
              {activeItems.length > 0 ? (
                <div className="space-y-24">
                  {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                    <section key={groupLabel}>
                      <div className="flex items-center gap-6 mb-12">
                        <span className="text-[14px] font-black tracking-widest uppercase bg-[#12141c] text-white px-6 py-2 rounded-2xl">{groupLabel}</span>
                        <div className="flex-grow h-[1px] bg-gray-100" />
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                        {groupItems.map(i => <MarketCard key={i.id} insight={i} onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}} onDelete={isAdmin ? handleDeleteInsight : () => {}} onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}} isEditable={isAdmin} />)}
                      </div>
                    </section>
                  ))}
                </div>
              ) : (
                <div className="text-center py-40 bg-gray-50/30 border-4 border-dashed border-gray-50 rounded-[4rem]">
                  <h3 className="text-2xl font-black text-gray-900">暂无匹配记录</h3>
                </div>
              )}
              {archivedItems.length > 0 && (
                <div className="mt-60 pt-32 border-t border-gray-100">
                  <h3 className="text-3xl font-black mb-16 italic">历史归档</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10 grayscale opacity-40 hover:opacity-100 transition-all duration-700">
                    {archivedItems.map(i => <MarketCard key={i.id} insight={i} onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}} onDelete={isAdmin ? handleDeleteInsight : () => {}} onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}} isEditable={isAdmin} />)}
                  </div>
                </div>
              )}
            </>
          )}
        </main>
      </div>

      {showForm && isAdmin && <InsightForm initialData={editingInsight} onSave={handleSaveInsight} onCancel={() => { setShowForm(false); setEditingInsight(undefined); }} />}
      {showJournalForm && isAdmin && <JournalForm initialData={editingJournal} onSave={handleSaveJournal} onCancel={() => { setShowJournalForm(false); setEditingJournal(undefined); }} />}
      <LoginModal isOpen={showLogin} onClose={() => setShowLogin(false)} onVerify={onVerifyAdmin} />

      <footer className="mt-40 border-t border-gray-100 py-12 px-8">
        <div className="max-w-[1600px] mx-auto flex justify-between items-center italic font-black text-gray-300">
          <span>市场周刊. © {new Date().getFullYear()}</span>
          <div className="flex gap-8 text-xs uppercase tracking-widest">
            <a href="#" className="hover:text-[#12141c] transition-colors">宏观逻辑</a>
            <a href="#" className="hover:text-[#12141c] transition-colors">关于博主</a>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode, JournalEntry, EntryType, AppNotification } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import JournalSection from './components/JournalSection';
import JournalForm from './components/JournalForm';
import NotificationCenter from './components/NotificationCenter';
import { supabase, isSupabaseConfigured } from './services/supabaseClient';
import { 
  Plus, 
  LayoutGrid, 
  ListFilter, 
  CalendarDays, 
  Search, 
  Lock,
  KeyRound,
  BookOpen,
  Zap,
  Sparkles
} from 'lucide-react';

const ADMIN_PASSWORD = "8888"; 

const LoginModal: React.FC<{ isOpen: boolean; onClose: () => void; onVerify: (pwd: string) => void }> = ({ isOpen, onClose, onVerify }) => {
  const [pwd, setPwd] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (isOpen) {
      setTimeout(() => inputRef.current?.focus(), 100);
      setPwd('');
    }
  }, [isOpen]);
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-[#12141c]/80 backdrop-blur-xl animate-in fade-in duration-300">
      <div className="bg-white rounded-[2.5rem] p-10 w-full max-w-sm shadow-2xl border border-gray-100 animate-in zoom-in-95 duration-300">
        <div className="flex flex-col items-center text-center space-y-6">
          <div className="w-16 h-16 bg-amber-100 rounded-3xl flex items-center justify-center text-amber-600"><KeyRound className="w-8 h-8" /></div>
          <div>
            <h3 className="text-2xl font-black text-gray-900 tracking-tight">管理模式解锁</h3>
            <p className="text-gray-400 font-bold text-sm mt-1 uppercase tracking-widest">请输入身份密钥以继续</p>
          </div>
          <input ref={inputRef} type="password" value={pwd} onChange={(e) => setPwd(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && onVerify(pwd)} placeholder="••••" className="w-full bg-gray-50 border-2 border-transparent focus:border-amber-400 focus:bg-white p-5 rounded-2xl text-center text-2xl font-black tracking-[1em] outline-none transition-all placeholder:tracking-normal placeholder:text-sm placeholder:font-bold" />
          <div className="flex gap-3 w-full">
            <button onClick={onClose} className="flex-1 py-4 px-6 rounded-2xl border border-gray-100 text-gray-400 font-black text-sm hover:bg-gray-50 transition-colors">取消</button>
            <button onClick={() => onVerify(pwd)} className="flex-1 py-4 px-6 rounded-2xl bg-[#12141c] text-white font-black text-sm hover:scale-105 active:scale-95 transition-all shadow-xl shadow-gray-200">确认解锁</button>
          </div>
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>([]);
  const [journals, setJournals] = useState<JournalEntry[]>([]);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('journal');
  const [showForm, setShowForm] = useState(false);
  const [showJournalForm, setShowJournalForm] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [editingJournal, setEditingJournal] = useState<JournalEntry | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');

  const [isAdmin, setIsAdmin] = useState(() => localStorage.getItem('is_admin') === 'true');
  const [clickCount, setClickCount] = useState(0);

  // 通知添加工具函数 - 增加 Supabase 支持
  const addNotification = useCallback(async (title: string, message: string, type: AppNotification['type']) => {
    const newNote: AppNotification = {
      id: Math.random().toString(36).substr(2, 9),
      title,
      message,
      timestamp: Date.now(),
      isRead: false,
      type
    };

    if (isSupabaseConfigured && supabase) {
      await supabase.from('notifications').upsert({
        id: newNote.id,
        title: newNote.title,
        message: newNote.message,
        timestamp: newNote.timestamp,
        is_read: newNote.isRead,
        type: newNote.type
      });
    }

    setNotifications(prev => {
      const updated = [newNote, ...prev].slice(0, 30);
      localStorage.setItem('local_notifications', JSON.stringify(updated));
      return updated;
    });
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.shiftKey && e.key.toLowerCase() === 'a') {
        e.preventDefault();
        if (!isAdmin) setShowLogin(true);
        else sortMode === 'journal' ? setShowJournalForm(true) : setShowForm(true);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isAdmin, sortMode]);

  const handleBrandClick = () => {
    if (isAdmin) return;
    setClickCount(prev => {
      const next = prev + 1;
      if (next >= 5) { setShowLogin(true); return 0; }
      return next;
    });
  };

  useEffect(() => {
    if (clickCount > 0) {
      const timer = setTimeout(() => setClickCount(0), 1500);
      return () => clearTimeout(timer);
    }
  }, [clickCount]);

  const onVerifyAdmin = (pwd: string) => {
    if (pwd === ADMIN_PASSWORD) {
      setIsAdmin(true);
      localStorage.setItem('is_admin', 'true');
      setShowLogin(false);
      addNotification('系统消息', '管理模式已解锁', 'system');
    } else {
      alert("密钥错误，请重试");
    }
  };

  const fetchAllData = async () => {
    setLoading(true);
    // 优先加载本地
    const savedInsights = localStorage.getItem('local_insights');
    setInsights(savedInsights ? JSON.parse(savedInsights) : INITIAL_INSIGHTS);
    const savedJournals = localStorage.getItem('local_journals');
    if (savedJournals) setJournals(JSON.parse(savedJournals));
    const savedNotifications = localStorage.getItem('local_notifications');
    if (savedNotifications) setNotifications(JSON.parse(savedNotifications));

    if (isSupabaseConfigured && supabase) {
      // 同步 Insights
      const { data: insData } = await supabase.from('insights').select('*').order('updated_at', { ascending: false });
      if (insData) {
        const mapped = insData.map((item: any) => ({
          id: item.id, symbol: item.symbol, category: item.category, status: item.status,
          focusPoints: item.focus_points, strategy: item.strategy, entryLevel: item.entry_level,
          updatedAt: item.updated_at, completionStatus: item.completion_status
        }));
        setInsights(mapped);
        localStorage.setItem('local_insights', JSON.stringify(mapped));
      }

      // 同步 Journals
      const { data: jrData } = await supabase.from('journals').select('*').order('date', { ascending: false });
      if (jrData) {
        setJournals(jrData);
        localStorage.setItem('local_journals', JSON.stringify(jrData));
      }

      // 同步 Notifications
      const { data: noteData } = await supabase.from('notifications').select('*').order('timestamp', { ascending: false }).limit(30);
      if (noteData) {
        const mappedNotes = noteData.map((n: any) => ({
          id: n.id,
          title: n.title,
          message: n.message,
          timestamp: n.timestamp,
          isRead: n.is_read,
          type: n.type
        }));
        setNotifications(mappedNotes);
        localStorage.setItem('local_notifications', JSON.stringify(mappedNotes));
      }
    }
    setLoading(false);
  };

  useEffect(() => { fetchAllData(); }, []);

  const handleLogout = () => {
    if (window.confirm("确定退出管理模式吗？")) {
      setIsAdmin(false);
      localStorage.removeItem('is_admin');
      addNotification('系统消息', '已安全退出管理模式', 'system');
    }
  };

  const handleSaveJournal = async (data: Partial<JournalEntry>) => {
    const id = editingJournal ? editingJournal.id : Math.random().toString(36).substr(2, 9);
    const newEntry: JournalEntry = {
      id,
      title: data.title || '',
      content: data.content || '',
      mood: data.mood || '冷静',
      type: (data.type as EntryType) || '随笔',
      source: data.source || '',
      date: data.date || Date.now()
    };

    if (newEntry.type === '新闻' && !editingJournal) {
      addNotification('发现最新资讯', newEntry.title || '捕获到一条市场实时动态', 'news');
    }

    if (isSupabaseConfigured && supabase) await supabase.from('journals').upsert(newEntry);
    const updated = editingJournal ? journals.map(j => j.id === id ? newEntry : j) : [newEntry, ...journals];
    setJournals(updated.sort((a, b) => b.date - a.date));
    localStorage.setItem('local_journals', JSON.stringify(updated));
    setShowJournalForm(false);
    setEditingJournal(undefined);
  };

  const handleDeleteJournal = async (id: string) => {
    if (!window.confirm("确定从瀑布流中移除这条记录吗？")) return;
    if (isSupabaseConfigured && supabase) await supabase.from('journals').delete().eq('id', id);
    const updated = journals.filter(j => j.id !== id);
    setJournals(updated);
    localStorage.setItem('local_journals', JSON.stringify(updated));
  };

  const handleSaveInsight = async (data: Partial<MarketInsight>) => {
    const id = editingInsight ? editingInsight.id : Math.random().toString(36).substr(2, 9);
    const updatedTimestamp = data.updatedAt || Date.now();
    const newInsight: MarketInsight = {
      id, symbol: data.symbol || '', category: data.category || '美股', status: data.status || '震荡',
      focusPoints: data.focusPoints || '', strategy: data.strategy || '', entryLevel: data.entryLevel || '',
      updatedAt: updatedTimestamp, completionStatus: data.completionStatus || '进行中'
    };

    if (editingInsight && editingInsight.status !== newInsight.status) {
      addNotification('行情研判变更', `${newInsight.symbol} 状态从 [${editingInsight.status}] 调整为 [${newInsight.status}]`, 'market');
    }

    if (isSupabaseConfigured && supabase) {
      await supabase.from('insights').upsert({
        id, symbol: newInsight.symbol, category: newInsight.category, status: newInsight.status,
        focus_points: newInsight.focusPoints, strategy: newInsight.strategy, entry_level: newInsight.entryLevel,
        updated_at: updatedTimestamp, completion_status: newInsight.completionStatus
      });
    }
    const updated = editingInsight ? insights.map(i => i.id === id ? newInsight : i) : [newInsight, ...insights];
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = async (id: string) => {
    if (!window.confirm('确定要删除这条记录吗？')) return;
    if (isSupabaseConfigured && supabase) await supabase.from('insights').delete().eq('id', id);
    const updated = insights.filter(i => i.id !== id);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  const handleToggleCompletionStatus = async (id: string) => {
    const item = insights.find(i => i.id === id);
    if (!item) return;
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    const nextStatus = statuses[(statuses.indexOf(item.completionStatus) + 1) % statuses.length];
    const newTime = Date.now();

    addNotification('研判归档', `${item.symbol} 观点现已标记为 [${nextStatus}]`, 'system');

    if (isSupabaseConfigured && supabase) await supabase.from('insights').update({ completion_status: nextStatus, updated_at: newTime }).eq('id', id);
    const updated = insights.map(i => i.id === id ? { ...i, completionStatus: nextStatus, updatedAt: newTime } : i);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  const handleMarkAsRead = async (id: string) => {
    if (isSupabaseConfigured && supabase) {
      await supabase.from('notifications').update({ is_read: true }).eq('id', id);
    }
    setNotifications(prev => {
      const updated = prev.map(n => n.id === id ? { ...n, isRead: true } : n);
      localStorage.setItem('local_notifications', JSON.stringify(updated));
      return updated;
    });
  };

  const handleClearAllNotes = async () => {
    if (window.confirm('确认清除所有历史消息吗？')) {
      if (isSupabaseConfigured && supabase) {
        // 在实际应用中，通常会有用户 ID，这里我们假设清除全部
        await supabase.from('notifications').delete().neq('id', 'keep_all');
      }
      setNotifications([]);
      localStorage.setItem('local_notifications', JSON.stringify([]));
    }
  };

  const handleDeleteNote = async (id: string) => {
    if (isSupabaseConfigured && supabase) {
      await supabase.from('notifications').delete().eq('id', id);
    }
    setNotifications(prev => {
      const updated = prev.filter(n => n.id !== id);
      localStorage.setItem('local_notifications', JSON.stringify(updated));
      return updated;
    });
  };

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(i => i.symbol.toLowerCase().includes(query) || i.focusPoints.toLowerCase().includes(query));
    }
    if (activeCategory !== '全部') result = result.filter(i => i.category === activeCategory);
    if (selectedMonth) {
      result = result.filter(i => `${new Date(i.updatedAt).getFullYear()}年${new Date(i.updatedAt).getMonth() + 1}月` === selectedMonth);
    }
    return result;
  }, [insights, activeCategory, selectedMonth, searchQuery]);

  const filteredJournals = useMemo(() => {
    let result = journals;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(j => 
        j.title?.toLowerCase().includes(query) || 
        j.content.toLowerCase().includes(query) ||
        j.type?.toLowerCase().includes(query)
      );
    }
    return result;
  }, [journals, searchQuery]);

  const { activeItems, archivedItems } = useMemo(() => ({
    activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
    archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
  }), [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' }) : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    return Object.entries(groups).sort((a, b) => sortMode === 'category' ? CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any) : b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  return (
    <div className="min-h-screen flex flex-col selection:bg-amber-100 pb-20">
      <header className="sticky top-0 z-[100] bg-white/80 backdrop-blur-2xl border-b border-gray-100 px-8 h-[72px]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between h-full gap-8">
          <div onClick={handleBrandClick} className="flex items-center gap-3 shrink-0 cursor-pointer group select-none active:scale-90 transition-transform">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isAdmin ? 'bg-amber-500 shadow-xl shadow-amber-200 ring-2 ring-white/50 animate-pulse' : 'bg-[#12141c]'}`}>
              <LayoutGrid className="w-5 h-5 text-white" />
            </div>
            <div className="flex flex-col -space-y-1 relative">
              <h1 className="text-xl font-black text-[#12141c] tracking-tighter">市场周刊</h1>
              {!isAdmin && clickCount > 0 && <div className="absolute -bottom-2 left-0 h-1 bg-amber-400 rounded-full transition-all duration-200" style={{ width: `${(clickCount/5)*100}%` }} />}
            </div>
          </div>
          <div className="flex-grow flex items-center gap-4 max-w-3xl">
            <div className="relative group flex-grow">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <Search className={`w-4 h-4 transition-colors ${searchQuery ? 'text-gray-900' : 'text-gray-300'}`} />
              </div>
              <input type="text" className="w-full bg-gray-100/60 border border-transparent focus:bg-white focus:border-gray-200 py-3 pl-11 pr-10 rounded-2xl text-[14px] font-bold outline-none transition-all placeholder:text-gray-400" placeholder={`在${sortMode === 'journal' ? '瀑布流' : '洞察'}中搜索...`} value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
              {searchQuery && (
                <button onClick={() => setSearchQuery('')} className="absolute inset-y-0 right-0 pr-4 flex items-center text-gray-400 hover:text-gray-600">
                  <span className="text-[10px] font-black uppercase tracking-widest px-1.5 py-0.5 bg-gray-200 rounded-md">清除</span>
                </button>
              )}
            </div>
          </div>
          <div className="flex items-center gap-4 shrink-0">
            <NotificationCenter 
              notifications={notifications} 
              onMarkAsRead={handleMarkAsRead} 
              onClearAll={handleClearAllNotes} 
              onDelete={handleDeleteNote}
            />

            {isAdmin && (
              <div className="flex items-center gap-3 pl-4 border-l border-gray-100">
                <button onClick={() => { if (sortMode === 'journal') setShowJournalForm(true); else setShowForm(true); }} className="bg-[#12141c] text-white flex items-center gap-2 px-6 py-3 rounded-full hover:scale-105 transition-all shadow-xl shadow-gray-200"><Plus className="w-4 h-4" /><span className="text-sm font-black">投递{sortMode === 'journal' ? '信息' : '观点'}</span></button>
                <button onClick={handleLogout} className="p-3 bg-red-50 text-red-500 rounded-full hover:bg-red-100 transition-colors"><Lock className="w-4 h-4" /></button>
              </div>
            )}
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        <aside className="lg:w-64 space-y-12 shrink-0">
          <div className="sticky top-[104px] space-y-10">
            <div className="space-y-1">
                 <button onClick={() => setSortMode('category')} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center gap-3 ${sortMode === 'category' || sortMode === 'timeline' ? 'bg-[#12141c] text-white shadow-xl shadow-gray-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                   <LayoutGrid className="w-4 h-4" /> 核心资产
                 </button>
                 <button onClick={() => setSortMode('journal')} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center gap-3 ${sortMode === 'journal' ? 'bg-amber-500 text-white shadow-xl shadow-amber-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                   <Sparkles className="w-4 h-4" /> 信息瀑布流
                 </button>
            </div>

            {(sortMode === 'category' || sortMode === 'timeline') && (
              <div>
                <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2"><CalendarDays className="w-3.5 h-3.5" /> 历史归档</h3>
                <div className="space-y-1">
                  <button onClick={() => setSelectedMonth(null)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === null ? 'bg-gray-200 text-gray-900' : 'text-gray-500 hover:bg-gray-100'}`}>
                    <span>全部记录</span>
                    <span className="text-[10px] px-2 py-0.5 rounded-md bg-white/50">{insights.length}</span>
                  </button>
                  {timelineGroups.map(([month, count]) => (
                    <button key={month} onClick={() => setSelectedMonth(month)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === month ? 'bg-gray-200 text-gray-900' : 'text-gray-500 hover:bg-gray-100'}`}>
                      <span>{month}</span>
                      <span className="text-[10px] px-2 py-0.5 rounded-md bg-white/50">{count}</span>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </aside>

        <main className="flex-grow">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-16">
            <div>
              <h2 className="text-6xl font-black text-[#12141c] tracking-tighter leading-tight italic">
                {sortMode === 'journal' ? <>信息捕捉<br />瀑布流。</> : <>追踪行情，<br />每日洞察。</>}
              </h2>
              {sortMode === 'journal' && (
                <p className="mt-4 text-gray-400 font-bold text-lg">在此汇聚碎片化的市场资讯、研报核心及交易笔记。</p>
              )}
            </div>
          </div>

          {sortMode === 'journal' ? (
            <>
              {isAdmin && (
                <div 
                  onClick={() => setShowJournalForm(true)}
                  className="max-w-3xl mx-auto mb-12 p-6 bg-white rounded-3xl border border-dashed border-gray-200 flex items-center gap-4 text-gray-300 hover:text-gray-400 hover:border-amber-200 hover:bg-amber-50/30 cursor-pointer transition-all group"
                >
                   <div className="w-12 h-12 rounded-2xl bg-gray-50 flex items-center justify-center group-hover:bg-amber-500 group-hover:text-white transition-all">
                      <Zap className="w-6 h-6" />
                   </div>
                   <span className="text-xl font-bold tracking-tight">在这里捕捉市场动态...</span>
                </div>
              )}
              <JournalSection entries={filteredJournals} isAdmin={isAdmin} onEdit={(j) => { setEditingJournal(j); setShowJournalForm(true); }} onDelete={handleDeleteJournal} />
            </>
          ) : (
            <>
              {activeItems.length > 0 ? (
                <div className="space-y-24">
                  {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                    <section key={groupLabel}>
                      <div className="flex items-center gap-6 mb-12">
                        <span className="text-[14px] font-black tracking-widest uppercase bg-[#12141c] text-white px-6 py-2 rounded-2xl">{groupLabel}</span>
                        <div className="flex-grow h-[1px] bg-gray-100" />
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                        {groupItems.map(i => <MarketCard key={i.id} insight={i} onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}} onDelete={isAdmin ? handleDeleteInsight : () => {}} onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}} isEditable={isAdmin} />)}
                      </div>
                    </section>
                  ))}
                </div>
              ) : (
                <div className="text-center py-40 bg-gray-50/30 border-4 border-dashed border-gray-50 rounded-[4rem]">
                  <h3 className="text-2xl font-black text-gray-900">暂无匹配记录</h3>
                </div>
              )}
              {archivedItems.length > 0 && (
                <div className="mt-60 pt-32 border-t border-gray-100">
                  <h3 className="text-3xl font-black mb-16 italic">历史归档</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10 grayscale opacity-40 hover:opacity-100 transition-all duration-700">
                    {archivedItems.map(i => <MarketCard key={i.id} insight={i} onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}} onDelete={isAdmin ? handleDeleteInsight : () => {}} onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}} isEditable={isAdmin} />)}
                  </div>
                </div>
              )}
            </>
          )}
        </main>
      </div>

      {showForm && isAdmin && <InsightForm initialData={editingInsight} onSave={handleSaveInsight} onCancel={() => { setShowForm(false); setEditingInsight(undefined); }} />}
      {showJournalForm && isAdmin && <JournalForm initialData={editingJournal} onSave={handleSaveJournal} onCancel={() => { setShowJournalForm(false); setEditingJournal(undefined); }} />}
      <LoginModal isOpen={showLogin} onClose={() => setShowLogin(false)} onVerify={onVerifyAdmin} />

      <footer className="mt-40 border-t border-gray-100 py-12 px-8">
        <div className="max-w-[1600px] mx-auto flex justify-between items-center italic font-black text-gray-300">
          <span>市场周刊. © 2026 By 大强.</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode, JournalEntry, EntryType, AppNotification } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import JournalSection from './components/JournalSection';
import JournalForm from './components/JournalForm';
import NotificationCenter from './components/NotificationCenter';
import { supabase, isSupabaseConfigured } from './services/supabaseClient';
import { 
  Plus, 
  LayoutGrid, 
  ListFilter, 
  CalendarDays, 
  Search, 
  Lock,
  KeyRound,
  BookOpen,
  Zap,
  Sparkles
} from 'lucide-react';

const ADMIN_PASSWORD = "8888"; 

const LoginModal: React.FC<{ isOpen: boolean; onClose: () => void; onVerify: (pwd: string) => void }> = ({ isOpen, onClose, onVerify }) => {
  const [pwd, setPwd] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (isOpen) {
      setTimeout(() => inputRef.current?.focus(), 100);
      setPwd('');
    }
  }, [isOpen]);
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-[#12141c]/80 backdrop-blur-xl animate-in fade-in duration-300">
      <div className="bg-white rounded-[2.5rem] p-10 w-full max-w-sm shadow-2xl border border-gray-100 animate-in zoom-in-95 duration-300">
        <div className="flex flex-col items-center text-center space-y-6">
          <div className="w-16 h-16 bg-amber-100 rounded-3xl flex items-center justify-center text-amber-600"><KeyRound className="w-8 h-8" /></div>
          <div>
            <h3 className="text-2xl font-black text-gray-900 tracking-tight">管理模式解锁</h3>
            <p className="text-gray-400 font-bold text-sm mt-1 uppercase tracking-widest">请输入身份密钥以继续</p>
          </div>
          <input ref={inputRef} type="password" value={pwd} onChange={(e) => setPwd(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && onVerify(pwd)} placeholder="••••" className="w-full bg-gray-50 border-2 border-transparent focus:border-amber-400 focus:bg-white p-5 rounded-2xl text-center text-2xl font-black tracking-[1em] outline-none transition-all placeholder:tracking-normal placeholder:text-sm placeholder:font-bold" />
          <div className="flex gap-3 w-full">
            <button onClick={onClose} className="flex-1 py-4 px-6 rounded-2xl border border-gray-100 text-gray-400 font-black text-sm hover:bg-gray-50 transition-colors">取消</button>
            <button onClick={() => onVerify(pwd)} className="flex-1 py-4 px-6 rounded-2xl bg-[#12141c] text-white font-black text-sm hover:scale-105 active:scale-95 transition-all shadow-xl shadow-gray-200">确认解锁</button>
          </div>
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>([]);
  const [journals, setJournals] = useState<JournalEntry[]>([]);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('journal');
  const [showForm, setShowForm] = useState(false);
  const [showJournalForm, setShowJournalForm] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [editingJournal, setEditingJournal] = useState<JournalEntry | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');

  const [isAdmin, setIsAdmin] = useState(() => localStorage.getItem('is_admin') === 'true');
  const [clickCount, setClickCount] = useState(0);

  // 通知管理逻辑：对所有用户开放，无需管理员权限
  const addNotification = useCallback(async (title: string, message: string, type: AppNotification['type']) => {
    const newNote: AppNotification = {
      id: Math.random().toString(36).substr(2, 9),
      title,
      message,
      timestamp: Date.now(),
      isRead: false,
      type
    };

    if (isSupabaseConfigured && supabase) {
      await supabase.from('notifications').upsert({
        id: newNote.id,
        title: newNote.title,
        message: newNote.message,
        timestamp: newNote.timestamp,
        is_read: newNote.isRead,
        type: newNote.type
      });
    }

    setNotifications(prev => {
      const updated = [newNote, ...prev].slice(0, 30);
      localStorage.setItem('local_notifications', JSON.stringify(updated));
      return updated;
    });
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.shiftKey && e.key.toLowerCase() === 'a') {
        e.preventDefault();
        if (!isAdmin) setShowLogin(true);
        else sortMode === 'journal' ? setShowJournalForm(true) : setShowForm(true);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isAdmin, sortMode]);

  const handleBrandClick = () => {
    if (isAdmin) return;
    setClickCount(prev => {
      const next = prev + 1;
      if (next >= 5) { setShowLogin(true); return 0; }
      return next;
    });
  };

  useEffect(() => {
    if (clickCount > 0) {
      const timer = setTimeout(() => setClickCount(0), 1500);
      return () => clearTimeout(timer);
    }
  }, [clickCount]);

  const onVerifyAdmin = (pwd: string) => {
    if (pwd === ADMIN_PASSWORD) {
      setIsAdmin(true);
      localStorage.setItem('is_admin', 'true');
      setShowLogin(false);
      addNotification('系统消息', '管理模式已解锁', 'system');
    } else {
      alert("密钥错误，请重试");
    }
  };

  const fetchAllData = async () => {
    setLoading(true);
    const savedInsights = localStorage.getItem('local_insights');
    setInsights(savedInsights ? JSON.parse(savedInsights) : INITIAL_INSIGHTS);
    const savedJournals = localStorage.getItem('local_journals');
    if (savedJournals) setJournals(JSON.parse(savedJournals));
    const savedNotifications = localStorage.getItem('local_notifications');
    if (savedNotifications) setNotifications(JSON.parse(savedNotifications));

    if (isSupabaseConfigured && supabase) {
      const { data: insData } = await supabase.from('insights').select('*').order('updated_at', { ascending: false });
      if (insData) {
        const mapped = insData.map((item: any) => ({
          id: item.id, symbol: item.symbol, category: item.category, status: item.status,
          focusPoints: item.focus_points, strategy: item.strategy, entryLevel: item.entry_level,
          updatedAt: item.updated_at, completionStatus: item.completion_status
        }));
        setInsights(mapped);
        localStorage.setItem('local_insights', JSON.stringify(mapped));
      }

      const { data: jrData } = await supabase.from('journals').select('*').order('date', { ascending: false });
      if (jrData) {
        setJournals(jrData);
        localStorage.setItem('local_journals', JSON.stringify(jrData));
      }

      const { data: noteData } = await supabase.from('notifications').select('*').order('timestamp', { ascending: false }).limit(30);
      if (noteData) {
        const mappedNotes = noteData.map((n: any) => ({
          id: n.id,
          title: n.title,
          message: n.message,
          timestamp: n.timestamp,
          isRead: n.is_read,
          type: n.type
        }));
        setNotifications(mappedNotes);
        localStorage.setItem('local_notifications', JSON.stringify(mappedNotes));
      }
    }
    setLoading(false);
  };

  useEffect(() => { fetchAllData(); }, []);

  const handleLogout = () => {
    if (window.confirm("确定退出管理模式吗？")) {
      setIsAdmin(false);
      localStorage.removeItem('is_admin');
      addNotification('系统消息', '已安全退出管理模式', 'system');
    }
  };

  const handleSaveJournal = async (data: Partial<JournalEntry>) => {
    const id = editingJournal ? editingJournal.id : Math.random().toString(36).substr(2, 9);
    const newEntry: JournalEntry = {
      id,
      title: data.title || '',
      content: data.content || '',
      mood: data.mood || '冷静',
      type: (data.type as EntryType) || '随笔',
      source: data.source || '',
      date: data.date || Date.now()
    };

    if (newEntry.type === '新闻' && !editingJournal) {
      addNotification('发现最新资讯', newEntry.title || '捕获到一条市场实时动态', 'news');
    }

    if (isSupabaseConfigured && supabase) await supabase.from('journals').upsert(newEntry);
    const updated = editingJournal ? journals.map(j => j.id === id ? newEntry : j) : [newEntry, ...journals];
    setJournals(updated.sort((a, b) => b.date - a.date));
    localStorage.setItem('local_journals', JSON.stringify(updated));
    setShowJournalForm(false);
    setEditingJournal(undefined);
  };

  const handleDeleteJournal = async (id: string) => {
    if (!window.confirm("确定从瀑布流中移除这条记录吗？")) return;
    if (isSupabaseConfigured && supabase) await supabase.from('journals').delete().eq('id', id);
    const updated = journals.filter(j => j.id !== id);
    setJournals(updated);
    localStorage.setItem('local_journals', JSON.stringify(updated));
  };

  const handleSaveInsight = async (data: Partial<MarketInsight>) => {
    const id = editingInsight ? editingInsight.id : Math.random().toString(36).substr(2, 9);
    const updatedTimestamp = data.updatedAt || Date.now();
    const newInsight: MarketInsight = {
      id, symbol: data.symbol || '', category: data.category || '美股', status: data.status || '震荡',
      focusPoints: data.focusPoints || '', strategy: data.strategy || '', entryLevel: data.entryLevel || '',
      updatedAt: updatedTimestamp, completionStatus: data.completionStatus || '进行中'
    };

    if (editingInsight && editingInsight.status !== newInsight.status) {
      addNotification('行情研判变更', `${newInsight.symbol} 状态从 [${editingInsight.status}] 调整为 [${newInsight.status}]`, 'market');
    }

    if (isSupabaseConfigured && supabase) {
      await supabase.from('insights').upsert({
        id, symbol: newInsight.symbol, category: newInsight.category, status: newInsight.status,
        focus_points: newInsight.focusPoints, strategy: newInsight.strategy, entry_level: newInsight.entryLevel,
        updated_at: updatedTimestamp, completion_status: newInsight.completionStatus
      });
    }
    const updated = editingInsight ? insights.map(i => i.id === id ? newInsight : i) : [newInsight, ...insights];
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = async (id: string) => {
    if (!window.confirm('确定要删除这条记录吗？')) return;
    if (isSupabaseConfigured && supabase) await supabase.from('insights').delete().eq('id', id);
    const updated = insights.filter(i => i.id !== id);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  const handleToggleCompletionStatus = async (id: string) => {
    const item = insights.find(i => i.id === id);
    if (!item) return;
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    const nextStatus = statuses[(statuses.indexOf(item.completionStatus) + 1) % statuses.length];
    const newTime = Date.now();

    addNotification('研判归档', `${item.symbol} 观点现已标记为 [${nextStatus}]`, 'system');

    if (isSupabaseConfigured && supabase) await supabase.from('insights').update({ completion_status: nextStatus, updated_at: newTime }).eq('id', id);
    const updated = insights.map(i => i.id === id ? { ...i, completionStatus: nextStatus, updatedAt: newTime } : i);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  const handleMarkAsRead = async (id: string) => {
    if (isSupabaseConfigured && supabase) {
      await supabase.from('notifications').update({ is_read: true }).eq('id', id);
    }
    setNotifications(prev => {
      const updated = prev.map(n => n.id === id ? { ...n, isRead: true } : n);
      localStorage.setItem('local_notifications', JSON.stringify(updated));
      return updated;
    });
  };

  const handleClearAllNotes = async () => {
    if (window.confirm('确认清除所有历史消息吗？')) {
      if (isSupabaseConfigured && supabase) {
        await supabase.from('notifications').delete().neq('id', 'keep_all');
      }
      setNotifications([]);
      localStorage.setItem('local_notifications', JSON.stringify([]));
    }
  };

  const handleDeleteNote = async (id: string) => {
    if (isSupabaseConfigured && supabase) {
      await supabase.from('notifications').delete().eq('id', id);
    }
    setNotifications(prev => {
      const updated = prev.filter(n => n.id !== id);
      localStorage.setItem('local_notifications', JSON.stringify(updated));
      return updated;
    });
  };

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(i => i.symbol.toLowerCase().includes(query) || i.focusPoints.toLowerCase().includes(query));
    }
    if (activeCategory !== '全部') result = result.filter(i => i.category === activeCategory);
    if (selectedMonth) {
      result = result.filter(i => `${new Date(i.updatedAt).getFullYear()}年${new Date(i.updatedAt).getMonth() + 1}月` === selectedMonth);
    }
    return result;
  }, [insights, activeCategory, selectedMonth, searchQuery]);

  const filteredJournals = useMemo(() => {
    let result = journals;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(j => 
        j.title?.toLowerCase().includes(query) || 
        j.content.toLowerCase().includes(query) ||
        j.type?.toLowerCase().includes(query)
      );
    }
    return result;
  }, [journals, searchQuery]);

  const { activeItems, archivedItems } = useMemo(() => ({
    activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
    archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
  }), [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' }) : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    return Object.entries(groups).sort((a, b) => sortMode === 'category' ? CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any) : b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  return (
    <div className="min-h-screen flex flex-col selection:bg-amber-100 pb-20">
      <header className="sticky top-0 z-[100] bg-white/80 backdrop-blur-2xl border-b border-gray-100 px-8 h-[72px]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between h-full gap-8">
          <div onClick={handleBrandClick} className="flex items-center gap-3 shrink-0 cursor-pointer group select-none active:scale-90 transition-transform">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isAdmin ? 'bg-amber-500 shadow-xl shadow-amber-200 ring-2 ring-white/50 animate-pulse' : 'bg-[#12141c]'}`}>
              <LayoutGrid className="w-5 h-5 text-white" />
            </div>
            <div className="flex flex-col -space-y-1 relative">
              <h1 className="text-xl font-black text-[#12141c] tracking-tighter">市场周刊</h1>
              {!isAdmin && clickCount > 0 && <div className="absolute -bottom-2 left-0 h-1 bg-amber-400 rounded-full transition-all duration-200" style={{ width: `${(clickCount/5)*100}%` }} />}
            </div>
          </div>
          <div className="flex-grow flex items-center gap-4 max-w-3xl">
            <div className="relative group flex-grow">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <Search className={`w-4 h-4 transition-colors ${searchQuery ? 'text-gray-900' : 'text-gray-300'}`} />
              </div>
              <input type="text" className="w-full bg-gray-100/60 border border-transparent focus:bg-white focus:border-gray-200 py-3 pl-11 pr-10 rounded-2xl text-[14px] font-bold outline-none transition-all placeholder:text-gray-400" placeholder={`在${sortMode === 'journal' ? '瀑布流' : '洞察'}中搜索...`} value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
              {searchQuery && (
                <button onClick={() => setSearchQuery('')} className="absolute inset-y-0 right-0 pr-4 flex items-center text-gray-400 hover:text-gray-600">
                  <span className="text-[10px] font-black uppercase tracking-widest px-1.5 py-0.5 bg-gray-200 rounded-md">清除</span>
                </button>
              )}
            </div>
          </div>
          <div className="flex items-center gap-4 shrink-0">
            {/* 通知中心始终可用，不受管理员权限限制 */}
            <NotificationCenter 
              notifications={notifications} 
              onMarkAsRead={handleMarkAsRead} 
              onClearAll={handleClearAllNotes} 
              onDelete={handleDeleteNote}
            />

            {isAdmin && (
              <div className="flex items-center gap-3 pl-4 border-l border-gray-100">
                <button onClick={() => { if (sortMode === 'journal') setShowJournalForm(true); else setShowForm(true); }} className="bg-[#12141c] text-white flex items-center gap-2 px-6 py-3 rounded-full hover:scale-105 transition-all shadow-xl shadow-gray-200"><Plus className="w-4 h-4" /><span className="text-sm font-black">投递{sortMode === 'journal' ? '信息' : '观点'}</span></button>
                <button onClick={handleLogout} className="p-3 bg-red-50 text-red-500 rounded-full hover:bg-red-100 transition-colors"><Lock className="w-4 h-4" /></button>
              </div>
            )}
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        <aside className="lg:w-64 space-y-12 shrink-0">
          <div className="sticky top-[104px] space-y-10">
            {/* 删除了“研判维度”标题，直接展示导航按钮 */}
            <div className="space-y-1">
                 <button onClick={() => setSortMode('category')} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center gap-3 ${sortMode === 'category' || sortMode === 'timeline' ? 'bg-[#12141c] text-white shadow-xl shadow-gray-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                   <LayoutGrid className="w-4 h-4" /> 核心资产
                 </button>
                 <button onClick={() => setSortMode('journal')} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center gap-3 ${sortMode === 'journal' ? 'bg-amber-500 text-white shadow-xl shadow-amber-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                   <Sparkles className="w-4 h-4" /> 信息瀑布流
                 </button>
            </div>

            {(sortMode === 'category' || sortMode === 'timeline') && (
              <div>
                <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2"><CalendarDays className="w-3.5 h-3.5" /> 历史归档</h3>
                <div className="space-y-1">
                  <button onClick={() => setSelectedMonth(null)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === null ? 'bg-gray-200 text-gray-900' : 'text-gray-500 hover:bg-gray-100'}`}>
                    <span>全部记录</span>
                    <span className="text-[10px] px-2 py-0.5 rounded-md bg-white/50">{insights.length}</span>
                  </button>
                  {timelineGroups.map(([month, count]) => (
                    <button key={month} onClick={() => setSelectedMonth(month)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === month ? 'bg-gray-200 text-gray-900' : 'text-gray-500 hover:bg-gray-100'}`}>
                      <span>{month}</span>
                      <span className="text-[10px] px-2 py-0.5 rounded-md bg-white/50">{count}</span>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </aside>

        <main className="flex-grow">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-16">
            <div>
              <h2 className="text-6xl font-black text-[#12141c] tracking-tighter leading-tight italic">
                {sortMode === 'journal' ? <>信息捕捉<br />瀑布流。</> : <>追踪行情，<br />每日洞察。</>}
              </h2>
              {sortMode === 'journal' && (
                <p className="mt-4 text-gray-400 font-bold text-lg">在此汇聚碎片化的市场资讯、研报核心及交易笔记。</p>
              )}
            </div>
          </div>

          {sortMode === 'journal' ? (
            <>
              {isAdmin && (
                <div 
                  onClick={() => setShowJournalForm(true)}
                  className="max-w-3xl mx-auto mb-12 p-6 bg-white rounded-3xl border border-dashed border-gray-200 flex items-center gap-4 text-gray-300 hover:text-gray-400 hover:border-amber-200 hover:bg-amber-50/30 cursor-pointer transition-all group"
                >
                   <div className="w-12 h-12 rounded-2xl bg-gray-50 flex items-center justify-center group-hover:bg-amber-500 group-hover:text-white transition-all">
                      <Zap className="w-6 h-6" />
                   </div>
                   <span className="text-xl font-bold tracking-tight">在这里捕捉市场动态...</span>
                </div>
              )}
              <JournalSection entries={filteredJournals} isAdmin={isAdmin} onEdit={(j) => { setEditingJournal(j); setShowJournalForm(true); }} onDelete={handleDeleteJournal} />
            </>
          ) : (
            <>
              {activeItems.length > 0 ? (
                <div className="space-y-24">
                  {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                    <section key={groupLabel}>
                      <div className="flex items-center gap-6 mb-12">
                        <span className="text-[14px] font-black tracking-widest uppercase bg-[#12141c] text-white px-6 py-2 rounded-2xl">{groupLabel}</span>
                        <div className="flex-grow h-[1px] bg-gray-100" />
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                        {groupItems.map(i => <MarketCard key={i.id} insight={i} onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}} onDelete={isAdmin ? handleDeleteInsight : () => {}} onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}} isEditable={isAdmin} />)}
                      </div>
                    </section>
                  ))}
                </div>
              ) : (
                <div className="text-center py-40 bg-gray-50/30 border-4 border-dashed border-gray-50 rounded-[4rem]">
                  <h3 className="text-2xl font-black text-gray-900">暂无匹配记录</h3>
                </div>
              )}
              {archivedItems.length > 0 && (
                <div className="mt-60 pt-32 border-t border-gray-100">
                  <h3 className="text-3xl font-black mb-16 italic">历史归档</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10 grayscale opacity-40 hover:opacity-100 transition-all duration-700">
                    {archivedItems.map(i => <MarketCard key={i.id} insight={i} onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}} onDelete={isAdmin ? handleDeleteInsight : () => {}} onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}} isEditable={isAdmin} />)}
                  </div>
                </div>
              )}
            </>
          )}
        </main>
      </div>

      {showForm && isAdmin && <InsightForm initialData={editingInsight} onSave={handleSaveInsight} onCancel={() => { setShowForm(false); setEditingInsight(undefined); }} />}
      {showJournalForm && isAdmin && <JournalForm initialData={editingJournal} onSave={handleSaveJournal} onCancel={() => { setShowJournalForm(false); setEditingJournal(undefined); }} />}
      <LoginModal isOpen={showLogin} onClose={() => setShowLogin(false)} onVerify={onVerifyAdmin} />

      <footer className="mt-40 border-t border-gray-100 py-12 px-8">
        <div className="max-w-[1600px] mx-auto flex justify-between items-center italic font-black text-gray-300">
          <span>市场周刊. © 2026 By 大强.</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode, JournalEntry, EntryType, AppNotification } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import JournalSection from './components/JournalSection';
import JournalForm from './components/JournalForm';
import NotificationCenter from './components/NotificationCenter';
import { supabase, isSupabaseConfigured } from './services/supabaseClient';
import { 
  Plus, 
  LayoutGrid, 
  CalendarDays, 
  Search, 
  Lock,
  KeyRound,
  Zap,
  Sparkles
} from 'lucide-react';

const ADMIN_PASSWORD = "8888"; 

const LoginModal: React.FC<{ isOpen: boolean; onClose: () => void; onVerify: (pwd: string) => void }> = ({ isOpen, onClose, onVerify }) => {
  const [pwd, setPwd] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (isOpen) {
      setTimeout(() => inputRef.current?.focus(), 100);
      setPwd('');
    }
  }, [isOpen]);
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-[#12141c]/80 backdrop-blur-xl animate-in fade-in duration-300">
      <div className="bg-white rounded-[2.5rem] p-10 w-full max-w-sm shadow-2xl border border-gray-100 animate-in zoom-in-95 duration-300">
        <div className="flex flex-col items-center text-center space-y-6">
          <div className="w-16 h-16 bg-amber-100 rounded-3xl flex items-center justify-center text-amber-600"><KeyRound className="w-8 h-8" /></div>
          <div>
            <h3 className="text-2xl font-black text-gray-900 tracking-tight">管理模式解锁</h3>
            <p className="text-gray-400 font-bold text-sm mt-1 uppercase tracking-widest">请输入身份密钥以继续</p>
          </div>
          <input ref={inputRef} type="password" value={pwd} onChange={(e) => setPwd(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && onVerify(pwd)} placeholder="••••" className="w-full bg-gray-50 border-2 border-transparent focus:border-amber-400 focus:bg-white p-5 rounded-2xl text-center text-2xl font-black tracking-[1em] outline-none transition-all placeholder:tracking-normal placeholder:text-sm placeholder:font-bold" />
          <div className="flex gap-3 w-full">
            <button onClick={onClose} className="flex-1 py-4 px-6 rounded-2xl border border-gray-100 text-gray-400 font-black text-sm hover:bg-gray-50 transition-colors">取消</button>
            <button onClick={() => onVerify(pwd)} className="flex-1 py-4 px-6 rounded-2xl bg-[#12141c] text-white font-black text-sm hover:scale-105 active:scale-95 transition-all shadow-xl shadow-gray-200">确认解锁</button>
          </div>
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>([]);
  const [journals, setJournals] = useState<JournalEntry[]>([]);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('journal');
  const [showForm, setShowForm] = useState(false);
  const [showJournalForm, setShowJournalForm] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [editingJournal, setEditingJournal] = useState<JournalEntry | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');

  const [isAdmin, setIsAdmin] = useState(() => localStorage.getItem('is_admin') === 'true');
  const [clickCount, setClickCount] = useState(0);

  const addNotification = useCallback(async (title: string, message: string, type: AppNotification['type']) => {
    const newNote: AppNotification = {
      id: Math.random().toString(36).substr(2, 9),
      title,
      message,
      timestamp: Date.now(),
      isRead: false,
      type
    };

    if (isSupabaseConfigured && supabase) {
      await supabase.from('notifications').upsert({
        id: newNote.id,
        title: newNote.title,
        message: newNote.message,
        timestamp: newNote.timestamp,
        is_read: newNote.isRead,
        type: newNote.type
      });
    }

    setNotifications(prev => {
      const updated = [newNote, ...prev].slice(0, 30);
      localStorage.setItem('local_notifications', JSON.stringify(updated));
      return updated;
    });
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.shiftKey && e.key.toLowerCase() === 'a') {
        e.preventDefault();
        if (!isAdmin) setShowLogin(true);
        else sortMode === 'journal' ? setShowJournalForm(true) : setShowForm(true);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isAdmin, sortMode]);

  const handleBrandClick = () => {
    if (isAdmin) return;
    setClickCount(prev => {
      const next = prev + 1;
      if (next >= 5) { setShowLogin(true); return 0; }
      return next;
    });
  };

  useEffect(() => {
    if (clickCount > 0) {
      const timer = setTimeout(() => setClickCount(0), 1500);
      return () => clearTimeout(timer);
    }
  }, [clickCount]);

  const onVerifyAdmin = (pwd: string) => {
    if (pwd === ADMIN_PASSWORD) {
      setIsAdmin(true);
      localStorage.setItem('is_admin', 'true');
      setShowLogin(false);
      addNotification('系统消息', '管理模式已解锁', 'system');
    } else {
      alert("密钥错误，请重试");
    }
  };

  const fetchAllData = async () => {
    setLoading(true);
    const savedInsights = localStorage.getItem('local_insights');
    setInsights(savedInsights ? JSON.parse(savedInsights) : INITIAL_INSIGHTS);
    const savedJournals = localStorage.getItem('local_journals');
    if (savedJournals) setJournals(JSON.parse(savedJournals));
    const savedNotifications = localStorage.getItem('local_notifications');
    if (savedNotifications) setNotifications(JSON.parse(savedNotifications));

    if (isSupabaseConfigured && supabase) {
      const { data: insData } = await supabase.from('insights').select('*').order('updated_at', { ascending: false });
      if (insData) {
        const mapped = insData.map((item: any) => ({
          id: item.id, symbol: item.symbol, category: item.category, status: item.status,
          focusPoints: item.focus_points, strategy: item.strategy, entryLevel: item.entry_level,
          updatedAt: item.updated_at, completionStatus: item.completion_status
        }));
        setInsights(mapped);
        localStorage.setItem('local_insights', JSON.stringify(mapped));
      }

      const { data: jrData } = await supabase.from('journals').select('*').order('date', { ascending: false });
      if (jrData) {
        setJournals(jrData);
        localStorage.setItem('local_journals', JSON.stringify(jrData));
      }

      const { data: noteData } = await supabase.from('notifications').select('*').order('timestamp', { ascending: false }).limit(30);
      if (noteData) {
        const mappedNotes = noteData.map((n: any) => ({
          id: n.id,
          title: n.title,
          message: n.message,
          timestamp: n.timestamp,
          isRead: n.is_read,
          type: n.type
        }));
        setNotifications(mappedNotes);
        localStorage.setItem('local_notifications', JSON.stringify(mappedNotes));
      }
    }
    setLoading(false);
  };

  useEffect(() => { fetchAllData(); }, []);

  const handleLogout = () => {
    if (window.confirm("确定退出管理模式吗？")) {
      setIsAdmin(false);
      localStorage.removeItem('is_admin');
      addNotification('系统消息', '已安全退出管理模式', 'system');
    }
  };

  const handleSaveJournal = async (data: Partial<JournalEntry>) => {
    const id = editingJournal ? editingJournal.id : Math.random().toString(36).substr(2, 9);
    const newEntry: JournalEntry = {
      id,
      title: data.title || '',
      content: data.content || '',
      mood: data.mood || '冷静',
      type: (data.type as EntryType) || '随笔',
      source: data.source || '',
      date: data.date || Date.now()
    };

    if (newEntry.type === '新闻' && !editingJournal) {
      addNotification('发现最新资讯', newEntry.title || '捕获到一条市场实时动态', 'news');
    }

    if (isSupabaseConfigured && supabase) await supabase.from('journals').upsert(newEntry);
    const updated = editingJournal ? journals.map(j => j.id === id ? newEntry : j) : [newEntry, ...journals];
    setJournals(updated.sort((a, b) => b.date - a.date));
    localStorage.setItem('local_journals', JSON.stringify(updated));
    setShowJournalForm(false);
    setEditingJournal(undefined);
  };

  const handleDeleteJournal = async (id: string) => {
    if (!window.confirm("确定从瀑布流中移除这条记录吗？")) return;
    if (isSupabaseConfigured && supabase) await supabase.from('journals').delete().eq('id', id);
    const updated = journals.filter(j => j.id !== id);
    setJournals(updated);
    localStorage.setItem('local_journals', JSON.stringify(updated));
  };

  const handleSaveInsight = async (data: Partial<MarketInsight>) => {
    const id = editingInsight ? editingInsight.id : Math.random().toString(36).substr(2, 9);
    const updatedTimestamp = data.updatedAt || Date.now();
    const newInsight: MarketInsight = {
      id, symbol: data.symbol || '', category: data.category || '美股', status: data.status || '震荡',
      focusPoints: data.focusPoints || '', strategy: data.strategy || '', entryLevel: data.entryLevel || '',
      updatedAt: updatedTimestamp, completionStatus: data.completionStatus || '进行中'
    };

    if (editingInsight && editingInsight.status !== newInsight.status) {
      addNotification('行情研判变更', `${newInsight.symbol} 状态从 [${editingInsight.status}] 调整为 [${newInsight.status}]`, 'market');
    }

    if (isSupabaseConfigured && supabase) {
      await supabase.from('insights').upsert({
        id, symbol: newInsight.symbol, category: newInsight.category, status: newInsight.status,
        focus_points: newInsight.focusPoints, strategy: newInsight.strategy, entry_level: newInsight.entryLevel,
        updated_at: updatedTimestamp, completion_status: newInsight.completionStatus
      });
    }
    const updated = editingInsight ? insights.map(i => i.id === id ? newInsight : i) : [newInsight, ...insights];
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = async (id: string) => {
    if (!window.confirm('确定要删除这条记录吗？')) return;
    if (isSupabaseConfigured && supabase) await supabase.from('insights').delete().eq('id', id);
    const updated = insights.filter(i => i.id !== id);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  const handleToggleCompletionStatus = async (id: string) => {
    const item = insights.find(i => i.id === id);
    if (!item) return;
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    const nextStatus = statuses[(statuses.indexOf(item.completionStatus) + 1) % statuses.length];
    const newTime = Date.now();

    addNotification('研判归档', `${item.symbol} 观点现已标记为 [${nextStatus}]`, 'system');

    if (isSupabaseConfigured && supabase) await supabase.from('insights').update({ completion_status: nextStatus, updated_at: newTime }).eq('id', id);
    const updated = insights.map(i => i.id === id ? { ...i, completionStatus: nextStatus, updatedAt: newTime } : i);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  const handleMarkAsRead = async (id: string) => {
    if (isSupabaseConfigured && supabase) {
      await supabase.from('notifications').update({ is_read: true }).eq('id', id);
    }
    setNotifications(prev => {
      const updated = prev.map(n => n.id === id ? { ...n, isRead: true } : n);
      localStorage.setItem('local_notifications', JSON.stringify(updated));
      return updated;
    });
  };

  const handleClearAllNotes = async () => {
    if (window.confirm('确认清除所有历史消息吗？')) {
      if (isSupabaseConfigured && supabase) {
        await supabase.from('notifications').delete().neq('id', 'keep_all');
      }
      setNotifications([]);
      localStorage.setItem('local_notifications', JSON.stringify([]));
    }
  };

  const handleDeleteNote = async (id: string) => {
    if (isSupabaseConfigured && supabase) {
      await supabase.from('notifications').delete().eq('id', id);
    }
    setNotifications(prev => {
      const updated = prev.filter(n => n.id !== id);
      localStorage.setItem('local_notifications', JSON.stringify(updated));
      return updated;
    });
  };

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(i => i.symbol.toLowerCase().includes(query) || i.focusPoints.toLowerCase().includes(query));
    }
    if (activeCategory !== '全部') result = result.filter(i => i.category === activeCategory);
    if (selectedMonth) {
      result = result.filter(i => `${new Date(i.updatedAt).getFullYear()}年${new Date(i.updatedAt).getMonth() + 1}月` === selectedMonth);
    }
    return result;
  }, [insights, activeCategory, selectedMonth, searchQuery]);

  const filteredJournals = useMemo(() => {
    let result = journals;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(j => 
        j.title?.toLowerCase().includes(query) || 
        j.content.toLowerCase().includes(query) ||
        j.type?.toLowerCase().includes(query)
      );
    }
    return result;
  }, [journals, searchQuery]);

  const { activeItems, archivedItems } = useMemo(() => ({
    activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
    archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
  }), [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' }) : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    return Object.entries(groups).sort((a, b) => sortMode === 'category' ? CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any) : b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  return (
    <div className="min-h-screen flex flex-col selection:bg-amber-100 pb-20">
      <header className="sticky top-0 z-[100] bg-white/80 backdrop-blur-2xl border-b border-gray-100 px-8 h-[72px]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between h-full gap-8">
          <div onClick={handleBrandClick} className="flex items-center gap-3 shrink-0 cursor-pointer group select-none active:scale-90 transition-transform">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isAdmin ? 'bg-amber-500 shadow-xl shadow-amber-200 ring-2 ring-white/50 animate-pulse' : 'bg-[#12141c]'}`}>
              <LayoutGrid className="w-5 h-5 text-white" />
            </div>
            <div className="flex flex-col -space-y-1 relative">
              <h1 className="text-xl font-black text-[#12141c] tracking-tighter">市场周刊</h1>
              {!isAdmin && clickCount > 0 && <div className="absolute -bottom-2 left-0 h-1 bg-amber-400 rounded-full transition-all duration-200" style={{ width: `${(clickCount/5)*100}%` }} />}
            </div>
          </div>
          <div className="flex-grow flex items-center gap-4 max-w-3xl">
            <div className="relative group flex-grow">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <Search className={`w-4 h-4 transition-colors ${searchQuery ? 'text-gray-900' : 'text-gray-300'}`} />
              </div>
              <input type="text" className="w-full bg-gray-100/60 border border-transparent focus:bg-white focus:border-gray-200 py-3 pl-11 pr-10 rounded-2xl text-[14px] font-bold outline-none transition-all placeholder:text-gray-400" placeholder={`在${sortMode === 'journal' ? '瀑布流' : '洞察'}中搜索...`} value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
              {searchQuery && (
                <button onClick={() => setSearchQuery('')} className="absolute inset-y-0 right-0 pr-4 flex items-center text-gray-400 hover:text-gray-600">
                  <span className="text-[10px] font-black uppercase tracking-widest px-1.5 py-0.5 bg-gray-200 rounded-md">清除</span>
                </button>
              )}
            </div>
          </div>
          <div className="flex items-center gap-4 shrink-0">
            <NotificationCenter 
              notifications={notifications} 
              onMarkAsRead={handleMarkAsRead} 
              onClearAll={handleClearAllNotes} 
              onDelete={handleDeleteNote}
            />

            {isAdmin && (
              <div className="flex items-center gap-3 pl-4 border-l border-gray-100">
                <button 
                  onClick={() => { if (sortMode === 'journal') setShowJournalForm(true); else setShowForm(true); }} 
                  className="bg-[#12141c] text-white flex items-center gap-2 px-5 py-2.5 rounded-full hover:scale-105 transition-all shadow-xl shadow-gray-200"
                >
                  <Plus className="w-4 h-4" />
                  <span className="text-sm font-black whitespace-nowrap">投递{sortMode === 'journal' ? '信息' : '观点'}</span>
                </button>

                {/* 优化后的退出按钮：增加明文标签 */}
                <button 
                  onClick={handleLogout} 
                  className="flex items-center gap-2 px-4 py-2.5 bg-red-50 text-red-500 rounded-full hover:bg-red-100 transition-all group active:scale-95"
                >
                  <Lock className="w-4 h-4 group-hover:rotate-12 transition-transform" />
                  <span className="text-[12px] font-black whitespace-nowrap">退出管理</span>
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        <aside className="lg:w-64 space-y-12 shrink-0">
          <div className="sticky top-[104px] space-y-10">
            <div className="space-y-1">
                 <button onClick={() => setSortMode('category')} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center gap-3 ${sortMode === 'category' || sortMode === 'timeline' ? 'bg-[#12141c] text-white shadow-xl shadow-gray-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                   <LayoutGrid className="w-4 h-4" /> 核心资产
                 </button>
                 <button onClick={() => setSortMode('journal')} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center gap-3 ${sortMode === 'journal' ? 'bg-amber-500 text-white shadow-xl shadow-amber-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                   <Sparkles className="w-4 h-4" /> 信息瀑布流
                 </button>
            </div>

            {(sortMode === 'category' || sortMode === 'timeline') && (
              <div>
                <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2"><CalendarDays className="w-3.5 h-3.5" /> 历史归档</h3>
                <div className="space-y-1">
                  <button onClick={() => setSelectedMonth(null)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === null ? 'bg-gray-200 text-gray-900' : 'text-gray-500 hover:bg-gray-100'}`}>
                    <span>全部记录</span>
                    <span className="text-[10px] px-2 py-0.5 rounded-md bg-white/50">{insights.length}</span>
                  </button>
                  {timelineGroups.map(([month, count]) => (
                    <button key={month} onClick={() => setSelectedMonth(month)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === month ? 'bg-gray-200 text-gray-900' : 'text-gray-500 hover:bg-gray-100'}`}>
                      <span>{month}</span>
                      <span className="text-[10px] px-2 py-0.5 rounded-md bg-white/50">{count}</span>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </aside>

        <main className="flex-grow">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-16">
            <div>
              <h2 className="text-6xl font-black text-[#12141c] tracking-tighter leading-tight italic">
                {sortMode === 'journal' ? <>信息捕捉<br />瀑布流。</> : <>追踪行情，<br />每日洞察。</>}
              </h2>
              {sortMode === 'journal' && (
                <p className="mt-4 text-gray-400 font-bold text-lg">在此汇聚碎片化的市场资讯、研报核心及交易笔记。</p>
              )}
            </div>
          </div>

          {sortMode === 'journal' ? (
            <>
              {isAdmin && (
                <div 
                  onClick={() => setShowJournalForm(true)}
                  className="max-w-3xl mx-auto mb-12 p-6 bg-white rounded-3xl border border-dashed border-gray-200 flex items-center gap-4 text-gray-300 hover:text-gray-400 hover:border-amber-200 hover:bg-amber-50/30 cursor-pointer transition-all group"
                >
                   <div className="w-12 h-12 rounded-2xl bg-gray-50 flex items-center justify-center group-hover:bg-amber-500 group-hover:text-white transition-all">
                      <Zap className="w-6 h-6" />
                   </div>
                   <span className="text-xl font-bold tracking-tight">在这里捕捉市场动态...</span>
                </div>
              )}
              <JournalSection entries={filteredJournals} isAdmin={isAdmin} onEdit={(j) => { setEditingJournal(j); setShowJournalForm(true); }} onDelete={handleDeleteJournal} />
            </>
          ) : (
            <>
              {activeItems.length > 0 ? (
                <div className="space-y-24">
                  {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                    <section key={groupLabel}>
                      <div className="flex items-center gap-6 mb-12">
                        <span className="text-[14px] font-black tracking-widest uppercase bg-[#12141c] text-white px-6 py-2 rounded-2xl">{groupLabel}</span>
                        <div className="flex-grow h-[1px] bg-gray-100" />
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                        {groupItems.map(i => <MarketCard key={i.id} insight={i} onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}} onDelete={isAdmin ? handleDeleteInsight : () => {}} onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}} isEditable={isAdmin} />)}
                      </div>
                    </section>
                  ))}
                </div>
              ) : (
                <div className="text-center py-40 bg-gray-50/30 border-4 border-dashed border-gray-50 rounded-[4rem]">
                  <h3 className="text-2xl font-black text-gray-900">暂无匹配记录</h3>
                </div>
              )}
              {archivedItems.length > 0 && (
                <div className="mt-60 pt-32 border-t border-gray-100">
                  <h3 className="text-3xl font-black mb-16 italic">历史归档</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10 grayscale opacity-40 hover:opacity-100 transition-all duration-700">
                    {archivedItems.map(i => <MarketCard key={i.id} insight={i} onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}} onDelete={isAdmin ? handleDeleteInsight : () => {}} onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}} isEditable={isAdmin} />)}
                  </div>
                </div>
              )}
            </>
          )}
        </main>
      </div>

      {showForm && isAdmin && <InsightForm initialData={editingInsight} onSave={handleSaveInsight} onCancel={() => { setShowForm(false); setEditingInsight(undefined); }} />}
      {showJournalForm && isAdmin && <JournalForm initialData={editingJournal} onSave={handleSaveJournal} onCancel={() => { setShowJournalForm(false); setEditingJournal(undefined); }} />}
      <LoginModal isOpen={showLogin} onClose={() => setShowLogin(false)} onVerify={onVerifyAdmin} />

      <footer className="mt-40 border-t border-gray-100 py-12 px-8">
        <div className="max-w-[1600px] mx-auto flex justify-between items-center italic font-black text-gray-300">
          <span>市场周刊. © 2026 By 大强.</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode, JournalEntry, EntryType, AppNotification } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import JournalSection from './components/JournalSection';
import JournalForm from './components/JournalForm';
import NotificationCenter from './components/NotificationCenter';
import { supabase, isSupabaseConfigured } from './services/supabaseClient';
import { 
  Plus, 
  LayoutGrid, 
  CalendarDays, 
  Search, 
  Lock,
  KeyRound,
  Zap,
  Sparkles
} from 'lucide-react';

const ADMIN_PASSWORD = "8888"; 

const LoginModal: React.FC<{ isOpen: boolean; onClose: () => void; onVerify: (pwd: string) => void }> = ({ isOpen, onClose, onVerify }) => {
  const [pwd, setPwd] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (isOpen) {
      setTimeout(() => inputRef.current?.focus(), 100);
      setPwd('');
    }
  }, [isOpen]);
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-[#12141c]/80 backdrop-blur-xl animate-in fade-in duration-300">
      <div className="bg-white rounded-[2.5rem] p-10 w-full max-w-sm shadow-2xl border border-gray-100 animate-in zoom-in-95 duration-300">
        <div className="flex flex-col items-center text-center space-y-6">
          <div className="w-16 h-16 bg-amber-100 rounded-3xl flex items-center justify-center text-amber-600"><KeyRound className="w-8 h-8" /></div>
          <div>
            <h3 className="text-2xl font-black text-gray-900 tracking-tight">管理模式解锁</h3>
            <p className="text-gray-400 font-bold text-sm mt-1 uppercase tracking-widest">请输入身份密钥以继续</p>
          </div>
          <input ref={inputRef} type="password" value={pwd} onChange={(e) => setPwd(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && onVerify(pwd)} placeholder="••••" className="w-full bg-gray-50 border-2 border-transparent focus:border-amber-400 focus:bg-white p-5 rounded-2xl text-center text-2xl font-black tracking-[1em] outline-none transition-all placeholder:tracking-normal placeholder:text-sm placeholder:font-bold" />
          <div className="flex gap-3 w-full">
            <button onClick={onClose} className="flex-1 py-4 px-6 rounded-2xl border border-gray-100 text-gray-400 font-black text-sm hover:bg-gray-50 transition-colors">取消</button>
            <button onClick={() => onVerify(pwd)} className="flex-1 py-4 px-6 rounded-2xl bg-[#12141c] text-white font-black text-sm hover:scale-105 active:scale-95 transition-all shadow-xl shadow-gray-200">确认解锁</button>
          </div>
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>([]);
  const [journals, setJournals] = useState<JournalEntry[]>([]);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('journal');
  const [showForm, setShowForm] = useState(false);
  const [showJournalForm, setShowJournalForm] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [editingJournal, setEditingJournal] = useState<JournalEntry | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');

  const [isAdmin, setIsAdmin] = useState(() => localStorage.getItem('is_admin') === 'true');
  const [clickCount, setClickCount] = useState(0);

  const addNotification = useCallback(async (title: string, message: string, type: AppNotification['type']) => {
    const newNote: AppNotification = {
      id: Math.random().toString(36).substr(2, 9),
      title,
      message,
      timestamp: Date.now(),
      isRead: false,
      type
    };

    if (isSupabaseConfigured && supabase) {
      await supabase.from('notifications').upsert({
        id: newNote.id,
        title: newNote.title,
        message: newNote.message,
        timestamp: newNote.timestamp,
        is_read: newNote.isRead,
        type: newNote.type
      });
    }

    setNotifications(prev => {
      const updated = [newNote, ...prev].slice(0, 30);
      localStorage.setItem('local_notifications', JSON.stringify(updated));
      return updated;
    });
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.shiftKey && e.key.toLowerCase() === 'a') {
        e.preventDefault();
        if (!isAdmin) setShowLogin(true);
        else sortMode === 'journal' ? setShowJournalForm(true) : setShowForm(true);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isAdmin, sortMode]);

  const handleBrandClick = () => {
    if (isAdmin) return;
    setClickCount(prev => {
      const next = prev + 1;
      if (next >= 5) { setShowLogin(true); return 0; }
      return next;
    });
  };

  useEffect(() => {
    if (clickCount > 0) {
      const timer = setTimeout(() => setClickCount(0), 1500);
      return () => clearTimeout(timer);
    }
  }, [clickCount]);

  const onVerifyAdmin = (pwd: string) => {
    if (pwd === ADMIN_PASSWORD) {
      setIsAdmin(true);
      localStorage.setItem('is_admin', 'true');
      setShowLogin(false);
      addNotification('系统消息', '管理模式已解锁', 'system');
    } else {
      alert("密钥错误，请重试");
    }
  };

  const fetchAllData = async () => {
    setLoading(true);
    const savedInsights = localStorage.getItem('local_insights');
    setInsights(savedInsights ? JSON.parse(savedInsights) : INITIAL_INSIGHTS);
    const savedJournals = localStorage.getItem('local_journals');
    if (savedJournals) setJournals(JSON.parse(savedJournals));
    const savedNotifications = localStorage.getItem('local_notifications');
    if (savedNotifications) setNotifications(JSON.parse(savedNotifications));

    if (isSupabaseConfigured && supabase) {
      const { data: insData } = await supabase.from('insights').select('*').order('updated_at', { ascending: false });
      if (insData) {
        const mapped = insData.map((item: any) => ({
          id: item.id, symbol: item.symbol, category: item.category, status: item.status,
          focusPoints: item.focus_points, strategy: item.strategy, entryLevel: item.entry_level,
          updatedAt: item.updated_at, completionStatus: item.completion_status
        }));
        setInsights(mapped);
        localStorage.setItem('local_insights', JSON.stringify(mapped));
      }

      const { data: jrData } = await supabase.from('journals').select('*').order('date', { ascending: false });
      if (jrData) {
        setJournals(jrData);
        localStorage.setItem('local_journals', JSON.stringify(jrData));
      }

      const { data: noteData } = await supabase.from('notifications').select('*').order('timestamp', { ascending: false }).limit(30);
      if (noteData) {
        const mappedNotes = noteData.map((n: any) => ({
          id: n.id,
          title: n.title,
          message: n.message,
          timestamp: n.timestamp,
          isRead: n.is_read,
          type: n.type
        }));
        setNotifications(mappedNotes);
        localStorage.setItem('local_notifications', JSON.stringify(mappedNotes));
      }
    }
    setLoading(false);
  };

  useEffect(() => { fetchAllData(); }, []);

  // 改进：一键退出，无需 confirm 弹窗
  const handleLogout = () => {
    setIsAdmin(false);
    localStorage.removeItem('is_admin');
    addNotification('系统消息', '已安全退出管理模式', 'system');
  };

  const handleSaveJournal = async (data: Partial<JournalEntry>) => {
    const id = editingJournal ? editingJournal.id : Math.random().toString(36).substr(2, 9);
    const newEntry: JournalEntry = {
      id,
      title: data.title || '',
      content: data.content || '',
      mood: data.mood || '冷静',
      type: (data.type as EntryType) || '随笔',
      source: data.source || '',
      date: data.date || Date.now()
    };

    if (newEntry.type === '新闻' && !editingJournal) {
      addNotification('发现最新资讯', newEntry.title || '捕获到一条市场实时动态', 'news');
    }

    if (isSupabaseConfigured && supabase) await supabase.from('journals').upsert(newEntry);
    const updated = editingJournal ? journals.map(j => j.id === id ? newEntry : j) : [newEntry, ...journals];
    setJournals(updated.sort((a, b) => b.date - a.date));
    localStorage.setItem('local_journals', JSON.stringify(updated));
    setShowJournalForm(false);
    setEditingJournal(undefined);
  };

  const handleDeleteJournal = async (id: string) => {
    if (!window.confirm("确定从瀑布流中移除这条记录吗？")) return;
    if (isSupabaseConfigured && supabase) await supabase.from('journals').delete().eq('id', id);
    const updated = journals.filter(j => j.id !== id);
    setJournals(updated);
    localStorage.setItem('local_journals', JSON.stringify(updated));
  };

  const handleSaveInsight = async (data: Partial<MarketInsight>) => {
    const id = editingInsight ? editingInsight.id : Math.random().toString(36).substr(2, 9);
    const updatedTimestamp = data.updatedAt || Date.now();
    const newInsight: MarketInsight = {
      id, symbol: data.symbol || '', category: data.category || '美股', status: data.status || '震荡',
      focusPoints: data.focusPoints || '', strategy: data.strategy || '', entryLevel: data.entryLevel || '',
      updatedAt: updatedTimestamp, completionStatus: data.completionStatus || '进行中'
    };

    if (editingInsight && editingInsight.status !== newInsight.status) {
      addNotification('行情研判变更', `${newInsight.symbol} 状态从 [${editingInsight.status}] 调整为 [${newInsight.status}]`, 'market');
    }

    if (isSupabaseConfigured && supabase) {
      await supabase.from('insights').upsert({
        id, symbol: newInsight.symbol, category: newInsight.category, status: newInsight.status,
        focus_points: newInsight.focusPoints, strategy: newInsight.strategy, entry_level: newInsight.entryLevel,
        updated_at: updatedTimestamp, completion_status: newInsight.completionStatus
      });
    }
    const updated = editingInsight ? insights.map(i => i.id === id ? newInsight : i) : [newInsight, ...insights];
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = async (id: string) => {
    if (!window.confirm('确定要删除这条记录吗？')) return;
    if (isSupabaseConfigured && supabase) await supabase.from('insights').delete().eq('id', id);
    const updated = insights.filter(i => i.id !== id);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  const handleToggleCompletionStatus = async (id: string) => {
    const item = insights.find(i => i.id === id);
    if (!item) return;
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    const nextStatus = statuses[(statuses.indexOf(item.completionStatus) + 1) % statuses.length];
    const newTime = Date.now();

    addNotification('研判归档', `${item.symbol} 观点现已标记为 [${nextStatus}]`, 'system');

    if (isSupabaseConfigured && supabase) await supabase.from('insights').update({ completion_status: nextStatus, updated_at: newTime }).eq('id', id);
    const updated = insights.map(i => i.id === id ? { ...i, completionStatus: nextStatus, updatedAt: newTime } : i);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  const handleMarkAsRead = async (id: string) => {
    if (isSupabaseConfigured && supabase) {
      await supabase.from('notifications').update({ is_read: true }).eq('id', id);
    }
    setNotifications(prev => {
      const updated = prev.map(n => n.id === id ? { ...n, isRead: true } : n);
      localStorage.setItem('local_notifications', JSON.stringify(updated));
      return updated;
    });
  };

  const handleClearAllNotes = async () => {
    if (window.confirm('确认清除所有历史消息吗？')) {
      if (isSupabaseConfigured && supabase) {
        await supabase.from('notifications').delete().neq('id', 'keep_all');
      }
      setNotifications([]);
      localStorage.setItem('local_notifications', JSON.stringify([]));
    }
  };

  const handleDeleteNote = async (id: string) => {
    if (isSupabaseConfigured && supabase) {
      await supabase.from('notifications').delete().eq('id', id);
    }
    setNotifications(prev => {
      const updated = prev.filter(n => n.id !== id);
      localStorage.setItem('local_notifications', JSON.stringify(updated));
      return updated;
    });
  };

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(i => i.symbol.toLowerCase().includes(query) || i.focusPoints.toLowerCase().includes(query));
    }
    if (activeCategory !== '全部') result = result.filter(i => i.category === activeCategory);
    if (selectedMonth) {
      result = result.filter(i => `${new Date(i.updatedAt).getFullYear()}年${new Date(i.updatedAt).getMonth() + 1}月` === selectedMonth);
    }
    return result;
  }, [insights, activeCategory, selectedMonth, searchQuery]);

  const filteredJournals = useMemo(() => {
    let result = journals;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(j => 
        j.title?.toLowerCase().includes(query) || 
        j.content.toLowerCase().includes(query) ||
        j.type?.toLowerCase().includes(query)
      );
    }
    return result;
  }, [journals, searchQuery]);

  const { activeItems, archivedItems } = useMemo(() => ({
    activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
    archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
  }), [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' }) : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    return Object.entries(groups).sort((a, b) => sortMode === 'category' ? CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any) : b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  return (
    <div className="min-h-screen flex flex-col selection:bg-amber-100 pb-20">
      <header className="sticky top-0 z-[100] bg-white/80 backdrop-blur-2xl border-b border-gray-100 px-8 h-[72px]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between h-full gap-8">
          <div onClick={handleBrandClick} className="flex items-center gap-3 shrink-0 cursor-pointer group select-none active:scale-90 transition-transform">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isAdmin ? 'bg-amber-500 shadow-xl shadow-amber-200 ring-2 ring-white/50 animate-pulse' : 'bg-[#12141c]'}`}>
              <LayoutGrid className="w-5 h-5 text-white" />
            </div>
            <div className="flex flex-col -space-y-1 relative">
              <h1 className="text-xl font-black text-[#12141c] tracking-tighter">市场周刊</h1>
              {!isAdmin && clickCount > 0 && <div className="absolute -bottom-2 left-0 h-1 bg-amber-400 rounded-full transition-all duration-200" style={{ width: `${(clickCount/5)*100}%` }} />}
            </div>
          </div>
          <div className="flex-grow flex items-center gap-4 max-w-3xl">
            <div className="relative group flex-grow">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <Search className={`w-4 h-4 transition-colors ${searchQuery ? 'text-gray-900' : 'text-gray-300'}`} />
              </div>
              <input type="text" className="w-full bg-gray-100/60 border border-transparent focus:bg-white focus:border-gray-200 py-3 pl-11 pr-10 rounded-2xl text-[14px] font-bold outline-none transition-all placeholder:text-gray-400" placeholder={`在${sortMode === 'journal' ? '瀑布流' : '洞察'}中搜索...`} value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
              {searchQuery && (
                <button onClick={() => setSearchQuery('')} className="absolute inset-y-0 right-0 pr-4 flex items-center text-gray-400 hover:text-gray-600">
                  <span className="text-[10px] font-black uppercase tracking-widest px-1.5 py-0.5 bg-gray-200 rounded-md">清除</span>
                </button>
              )}
            </div>
          </div>
          <div className="flex items-center gap-4 shrink-0">
            <NotificationCenter 
              notifications={notifications} 
              onMarkAsRead={handleMarkAsRead} 
              onClearAll={handleClearAllNotes} 
              onDelete={handleDeleteNote}
            />

            {isAdmin && (
              <div className="flex items-center gap-3 pl-4 border-l border-gray-100">
                <button 
                  onClick={() => { if (sortMode === 'journal') setShowJournalForm(true); else setShowForm(true); }} 
                  className="bg-[#12141c] text-white flex items-center gap-2 px-5 py-2.5 rounded-full hover:scale-105 transition-all shadow-xl shadow-gray-200"
                >
                  <Plus className="w-4 h-4" />
                  <span className="text-sm font-black whitespace-nowrap">投递{sortMode === 'journal' ? '信息' : '观点'}</span>
                </button>

                {/* 退出按钮：移除 confirm 逻辑，确保快速响应 */}
                <button 
                  onClick={handleLogout} 
                  className="flex items-center gap-2 px-4 py-2.5 bg-red-50 text-red-500 rounded-full hover:bg-red-500 hover:text-white transition-all group active:scale-95"
                >
                  <Lock className="w-4 h-4 group-hover:rotate-12 transition-transform" />
                  <span className="text-[12px] font-black whitespace-nowrap">退出管理</span>
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        <aside className="lg:w-64 space-y-12 shrink-0">
          <div className="sticky top-[104px] space-y-10">
            <div className="space-y-1">
                 <button onClick={() => setSortMode('category')} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center gap-3 ${sortMode === 'category' || sortMode === 'timeline' ? 'bg-[#12141c] text-white shadow-xl shadow-gray-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                   <LayoutGrid className="w-4 h-4" /> 核心资产
                 </button>
                 <button onClick={() => setSortMode('journal')} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center gap-3 ${sortMode === 'journal' ? 'bg-amber-500 text-white shadow-xl shadow-amber-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                   <Sparkles className="w-4 h-4" /> 信息瀑布流
                 </button>
            </div>

            {(sortMode === 'category' || sortMode === 'timeline') && (
              <div>
                <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2"><CalendarDays className="w-3.5 h-3.5" /> 历史归档</h3>
                <div className="space-y-1">
                  <button onClick={() => setSelectedMonth(null)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === null ? 'bg-gray-200 text-gray-900' : 'text-gray-500 hover:bg-gray-100'}`}>
                    <span>全部记录</span>
                    <span className="text-[10px] px-2 py-0.5 rounded-md bg-white/50">{insights.length}</span>
                  </button>
                  {timelineGroups.map(([month, count]) => (
                    <button key={month} onClick={() => setSelectedMonth(month)} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center justify-between ${selectedMonth === month ? 'bg-gray-200 text-gray-900' : 'text-gray-500 hover:bg-gray-100'}`}>
                      <span>{month}</span>
                      <span className="text-[10px] px-2 py-0.5 rounded-md bg-white/50">{count}</span>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </aside>

        <main className="flex-grow">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-16">
            <div>
              <h2 className="text-6xl font-black text-[#12141c] tracking-tighter leading-tight italic">
                {sortMode === 'journal' ? <>信息捕捉<br />瀑布流。</> : <>追踪行情，<br />每日洞察。</>}
              </h2>
              {sortMode === 'journal' && (
                <p className="mt-4 text-gray-400 font-bold text-lg">在此汇聚碎片化的市场资讯、研报核心及交易笔记。</p>
              )}
            </div>
          </div>

          {sortMode === 'journal' ? (
            <>
              {isAdmin && (
                <div 
                  onClick={() => setShowJournalForm(true)}
                  className="max-w-3xl mx-auto mb-12 p-6 bg-white rounded-3xl border border-dashed border-gray-200 flex items-center gap-4 text-gray-300 hover:text-gray-400 hover:border-amber-200 hover:bg-amber-50/30 cursor-pointer transition-all group"
                >
                   <div className="w-12 h-12 rounded-2xl bg-gray-50 flex items-center justify-center group-hover:bg-amber-500 group-hover:text-white transition-all">
                      <Zap className="w-6 h-6" />
                   </div>
                   <span className="text-xl font-bold tracking-tight">在这里捕捉市场动态...</span>
                </div>
              )}
              <JournalSection entries={filteredJournals} isAdmin={isAdmin} onEdit={(j) => { setEditingJournal(j); setShowJournalForm(true); }} onDelete={handleDeleteJournal} />
            </>
          ) : (
            <>
              {activeItems.length > 0 ? (
                <div className="space-y-24">
                  {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                    <section key={groupLabel}>
                      <div className="flex items-center gap-6 mb-12">
                        <span className="text-[14px] font-black tracking-widest uppercase bg-[#12141c] text-white px-6 py-2 rounded-2xl">{groupLabel}</span>
                        <div className="flex-grow h-[1px] bg-gray-100" />
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                        {groupItems.map(i => <MarketCard key={i.id} insight={i} onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}} onDelete={isAdmin ? handleDeleteInsight : () => {}} onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}} isEditable={isAdmin} />)}
                      </div>
                    </section>
                  ))}
                </div>
              ) : (
                <div className="text-center py-40 bg-gray-50/30 border-4 border-dashed border-gray-50 rounded-[4rem]">
                  <h3 className="text-2xl font-black text-gray-900">暂无匹配记录</h3>
                </div>
              )}
              {archivedItems.length > 0 && (
                <div className="mt-60 pt-32 border-t border-gray-100">
                  <h3 className="text-3xl font-black mb-16 italic">历史归档</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10 grayscale opacity-40 hover:opacity-100 transition-all duration-700">
                    {archivedItems.map(i => <MarketCard key={i.id} insight={i} onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}} onDelete={isAdmin ? handleDeleteInsight : () => {}} onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}} isEditable={isAdmin} />)}
                  </div>
                </div>
              )}
            </>
          )}
        </main>
      </div>

      {showForm && isAdmin && <InsightForm initialData={editingInsight} onSave={handleSaveInsight} onCancel={() => { setShowForm(false); setEditingInsight(undefined); }} />}
      {showJournalForm && isAdmin && <JournalForm initialData={editingJournal} onSave={handleSaveJournal} onCancel={() => { setShowJournalForm(false); setEditingJournal(undefined); }} />}
      <LoginModal isOpen={showLogin} onClose={() => setShowLogin(false)} onVerify={onVerifyAdmin} />

      <footer className="mt-40 border-t border-gray-100 py-12 px-8">
        <div className="max-w-[1600px] mx-auto flex justify-between items-center italic font-black text-gray-300">
          <span>市场周刊. © 2026 By 大强.</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

export type AssetStatus = '看涨' | '看跌' | '震荡';
export type CompletionStatus = '进行中' | '已完成' | '已失效';
export type SortMode = 'timeline' | 'category' | 'journal';
export type MarketMood = '贪婪' | '恐惧' | '冷静' | '警惕';
export type EntryType = '随笔' | '新闻' | '逻辑';

export interface MarketInsight {
  id: string;
  symbol: string;
  category: string;
  status: AssetStatus;
  focusPoints: string;
  strategy: string;
  entryLevel?: string;
  updatedAt: number;
  completionStatus: CompletionStatus;
}

export interface JournalEntry {
  id: string;
  date: number;
  content: string;
  mood: MarketMood;
  title?: string;
  type?: EntryType;
  source?: string;
}

export interface AppNotification {
  id: string;
  title: string;
  message: string;
  timestamp: number;
  isRead: boolean;
  type: 'market' | 'news' | 'system' | '随笔' | '新闻' | '逻辑';
}

export type Category = '全部' | '指数' | '加密货币' | '美股' | 'A股' | '外汇';

export interface AppState {
  insights: MarketInsight[];
  activeCategory: Category;
  isEditing: boolean;
  selectedInsight?: MarketInsight;
  sortMode: SortMode;
}

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode, JournalEntry, EntryType, AppNotification } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import JournalSection from './components/JournalSection';
import JournalForm from './components/JournalForm';
import NotificationCenter from './components/NotificationCenter';
import { supabase, isSupabaseConfigured } from './services/supabaseClient';
import { 
  Plus, 
  LayoutGrid, 
  CalendarDays, 
  Search, 
  Lock,
  KeyRound,
  Zap,
  Sparkles
} from 'lucide-react';

const ADMIN_PASSWORD = "8888"; 

const LoginModal: React.FC<{ isOpen: boolean; onClose: () => void; onVerify: (pwd: string) => void }> = ({ isOpen, onClose, onVerify }) => {
  const [pwd, setPwd] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (isOpen) {
      setTimeout(() => inputRef.current?.focus(), 100);
      setPwd('');
    }
  }, [isOpen]);
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-[#12141c]/80 backdrop-blur-xl animate-in fade-in duration-300">
      <div className="bg-white rounded-[2.5rem] p-10 w-full max-w-sm shadow-2xl border border-gray-100 animate-in zoom-in-95 duration-300">
        <div className="flex flex-col items-center text-center space-y-6">
          <div className="w-16 h-16 bg-amber-100 rounded-3xl flex items-center justify-center text-amber-600"><KeyRound className="w-8 h-8" /></div>
          <div>
            <h3 className="text-2xl font-black text-gray-900 tracking-tight">管理模式解锁</h3>
            <p className="text-gray-400 font-bold text-sm mt-1 uppercase tracking-widest">请输入身份密钥以继续</p>
          </div>
          <input ref={inputRef} type="password" value={pwd} onChange={(e) => setPwd(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && onVerify(pwd)} placeholder="••••" className="w-full bg-gray-50 border-2 border-transparent focus:border-amber-400 focus:bg-white p-5 rounded-2xl text-center text-2xl font-black tracking-[1em] outline-none transition-all placeholder:tracking-normal placeholder:text-sm placeholder:font-bold" />
          <div className="flex gap-3 w-full">
            <button onClick={onClose} className="flex-1 py-4 px-6 rounded-2xl border border-gray-100 text-gray-400 font-black text-sm hover:bg-gray-50 transition-colors">取消</button>
            <button onClick={() => onVerify(pwd)} className="flex-1 py-4 px-6 rounded-2xl bg-[#12141c] text-white font-black text-sm hover:scale-105 active:scale-95 transition-all shadow-xl shadow-gray-200">确认解锁</button>
          </div>
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>([]);
  const [journals, setJournals] = useState<JournalEntry[]>([]);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('journal');
  const [showForm, setShowForm] = useState(false);
  const [showJournalForm, setShowJournalForm] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [editingJournal, setEditingJournal] = useState<JournalEntry | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');

  const [isAdmin, setIsAdmin] = useState(() => localStorage.getItem('is_admin') === 'true');
  const [clickCount, setClickCount] = useState(0);

  const addNotification = useCallback(async (title: string, message: string, type: AppNotification['type']) => {
    const newNote: AppNotification = {
      id: Math.random().toString(36).substr(2, 9),
      title,
      message,
      timestamp: Date.now(),
      isRead: false,
      type
    };

    if (isSupabaseConfigured && supabase) {
      await supabase.from('notifications').upsert({
        id: newNote.id,
        title: newNote.title,
        message: newNote.message,
        timestamp: newNote.timestamp,
        is_read: newNote.isRead,
        type: newNote.type
      });
    }

    setNotifications(prev => {
      const updated = [newNote, ...prev].slice(0, 30);
      localStorage.setItem('local_notifications', JSON.stringify(updated));
      return updated;
    });
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.shiftKey && e.key.toLowerCase() === 'a') {
        e.preventDefault();
        if (!isAdmin) setShowLogin(true);
        else sortMode === 'journal' ? setShowJournalForm(true) : setShowForm(true);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isAdmin, sortMode]);

  const handleBrandClick = () => {
    if (isAdmin) return;
    setClickCount(prev => {
      const next = prev + 1;
      if (next >= 5) { setShowLogin(true); return 0; }
      return next;
    });
  };

  useEffect(() => {
    if (clickCount > 0) {
      const timer = setTimeout(() => setClickCount(0), 1500);
      return () => clearTimeout(timer);
    }
  }, [clickCount]);

  const onVerifyAdmin = (pwd: string) => {
    if (pwd === ADMIN_PASSWORD) {
      setIsAdmin(true);
      localStorage.setItem('is_admin', 'true');
      setShowLogin(false);
      addNotification('系统消息', '管理模式已解锁', 'system');
    } else {
      alert("密钥错误，请重试");
    }
  };

  const fetchAllData = async () => {
    setLoading(true);
    const savedInsights = localStorage.getItem('local_insights');
    setInsights(savedInsights ? JSON.parse(savedInsights) : INITIAL_INSIGHTS);
    const savedJournals = localStorage.getItem('local_journals');
    if (savedJournals) setJournals(JSON.parse(savedJournals));
    const savedNotifications = localStorage.getItem('local_notifications');
    if (savedNotifications) setNotifications(JSON.parse(savedNotifications));

    if (isSupabaseConfigured && supabase) {
      const { data: insData } = await supabase.from('insights').select('*').order('updated_at', { ascending: false });
      if (insData) {
        const mapped = insData.map((item: any) => ({
          id: item.id, symbol: item.symbol, category: item.category, status: item.status,
          focusPoints: item.focus_points, strategy: item.strategy, entryLevel: item.entry_level,
          updatedAt: item.updated_at, completionStatus: item.completion_status
        }));
        setInsights(mapped);
        localStorage.setItem('local_insights', JSON.stringify(mapped));
      }

      const { data: jrData } = await supabase.from('journals').select('*').order('date', { ascending: false });
      if (jrData) {
        setJournals(jrData);
        localStorage.setItem('local_journals', JSON.stringify(jrData));
      }

      const { data: noteData } = await supabase.from('notifications').select('*').order('timestamp', { ascending: false }).limit(30);
      if (noteData) {
        const mappedNotes = noteData.map((n: any) => ({
          id: n.id,
          title: n.title,
          message: n.message,
          timestamp: n.timestamp,
          isRead: n.is_read,
          type: n.type
        }));
        setNotifications(mappedNotes);
        localStorage.setItem('local_notifications', JSON.stringify(mappedNotes));
      }
    }
    setLoading(false);
  };

  useEffect(() => { fetchAllData(); }, []);

  const handleLogout = () => {
    setIsAdmin(false);
    localStorage.removeItem('is_admin');
    addNotification('系统消息', '已安全退出管理模式', 'system');
  };

  const handleSaveJournal = async (data: Partial<JournalEntry>) => {
    const id = editingJournal ? editingJournal.id : Math.random().toString(36).substr(2, 9);
    const newEntry: JournalEntry = {
      id,
      title: data.title || '',
      content: data.content || '',
      mood: data.mood || '冷静',
      type: (data.type as EntryType) || '随笔',
      source: data.source || '',
      date: data.date || Date.now()
    };

    // 为新增的记录添加通知，对应其 EntryType
    if (!editingJournal) {
      const notificationTitle = `[${newEntry.type}] 新内容投递`;
      const notificationMessage = newEntry.title || (newEntry.content.length > 50 ? newEntry.content.substring(0, 50) + '...' : newEntry.content);
      addNotification(notificationTitle, notificationMessage, newEntry.type as any);
    }

    if (isSupabaseConfigured && supabase) await supabase.from('journals').upsert(newEntry);
    const updated = editingJournal ? journals.map(j => j.id === id ? newEntry : j) : [newEntry, ...journals];
    setJournals(updated.sort((a, b) => b.date - a.date));
    localStorage.setItem('local_journals', JSON.stringify(updated));
    setShowJournalForm(false);
    setEditingJournal(undefined);
  };

  const handleDeleteJournal = async (id: string) => {
    if (!window.confirm("确定从瀑布流中移除这条记录吗？")) return;
    if (isSupabaseConfigured && supabase) await supabase.from('journals').delete().eq('id', id);
    const updated = journals.filter(j => j.id !== id);
    setJournals(updated);
    localStorage.setItem('local_journals', JSON.stringify(updated));
  };

  const handleSaveInsight = async (data: Partial<MarketInsight>) => {
    const id = editingInsight ? editingInsight.id : Math.random().toString(36).substr(2, 9);
    const updatedTimestamp = data.updatedAt || Date.now();
    const newInsight: MarketInsight = {
      id, symbol: data.symbol || '', category: data.category || '美股', status: data.status || '震荡',
      focusPoints: data.focusPoints || '', strategy: data.strategy || '', entryLevel: data.entryLevel || '',
      updatedAt: updatedTimestamp, completionStatus: data.completionStatus || '进行中'
    };

    if (editingInsight && editingInsight.status !== newInsight.status) {
      addNotification('行情研判变更', `${newInsight.symbol} 状态从 [${editingInsight.status}] 调整为 [${newInsight.status}]`, 'market');
    }

    if (isSupabaseConfigured && supabase) {
      await supabase.from('insights').upsert({
        id, symbol: newInsight.symbol, category: newInsight.category, status: newInsight.status,
        focus_points: newInsight.focusPoints, strategy: newInsight.strategy, entry_level: newInsight.entryLevel,
        updated_at: updatedTimestamp, completion_status: newInsight.completionStatus
      });
    }
    const updated = editingInsight ? insights.map(i => i.id === id ? newInsight : i) : [newInsight, ...insights];
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = async (id: string) => {
    if (!window.confirm('确定要删除这条记录吗？')) return;
    if (isSupabaseConfigured && supabase) await supabase.from('insights').delete().eq('id', id);
    const updated = insights.filter(i => i.id !== id);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  const handleToggleCompletionStatus = async (id: string) => {
    const item = insights.find(i => i.id === id);
    if (!item) return;
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    const nextStatus = statuses[(statuses.indexOf(item.completionStatus) + 1) % statuses.length];
    const newTime = Date.now();

    addNotification('研判归档', `${item.symbol} 观点现已标记为 [${nextStatus}]`, 'system');

    if (isSupabaseConfigured && supabase) await supabase.from('insights').update({ completion_status: nextStatus, updated_at: newTime }).eq('id', id);
    const updated = insights.map(i => i.id === id ? { ...i, completionStatus: nextStatus, updatedAt: newTime } : i);
    setInsights(updated);
    localStorage.setItem('local_insights', JSON.stringify(updated));
  };

  const handleMarkAsRead = async (id: string) => {
    if (isSupabaseConfigured && supabase) {
      await supabase.from('notifications').update({ is_read: true }).eq('id', id);
    }
    setNotifications(prev => {
      const updated = prev.map(n => n.id === id ? { ...n, isRead: true } : n);
      localStorage.setItem('local_notifications', JSON.stringify(updated));
      return updated;
    });
  };

  const handleClearAllNotes = async () => {
    if (window.confirm('确认清除所有历史消息吗？')) {
      if (isSupabaseConfigured && supabase) {
        await supabase.from('notifications').delete().neq('id', 'keep_all');
      }
      setNotifications([]);
      localStorage.setItem('local_notifications', JSON.stringify([]));
    }
  };

  const handleDeleteNote = async (id: string) => {
    if (isSupabaseConfigured && supabase) {
      await supabase.from('notifications').delete().eq('id', id);
    }
    setNotifications(prev => {
      const updated = prev.filter(n => n.id !== id);
      localStorage.setItem('local_notifications', JSON.stringify(updated));
      return updated;
    });
  };

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(i => i.symbol.toLowerCase().includes(query) || i.focusPoints.toLowerCase().includes(query));
    }
    if (activeCategory !== '全部') result = result.filter(i => i.category === activeCategory);
    if (selectedMonth) {
      result = result.filter(i => `${new Date(i.updatedAt).getFullYear()}年${new Date(i.updatedAt).getMonth() + 1}月` === selectedMonth);
    }
    return result;
  }, [insights, activeCategory, selectedMonth, searchQuery]);

  const filteredJournals = useMemo(() => {
    let result = journals;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(j => 
        j.title?.toLowerCase().includes(query) || 
        j.content.toLowerCase().includes(query) ||
        j.type?.toLowerCase().includes(query)
      );
    }
    return result;
  }, [journals, searchQuery]);

  const { activeItems, archivedItems } = useMemo(() => ({
    activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
    archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
  }), [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' }) : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    return Object.entries(groups).sort((a, b) => sortMode === 'category' ? CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any) : b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  return (
    <div className="min-h-screen flex flex-col selection:bg-amber-100 pb-20">
      <header className="sticky top-0 z-[100] bg-white/80 backdrop-blur-2xl border-b border-gray-100 px-8 h-[72px]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between h-full gap-8">
          <div onClick={handleBrandClick} className="flex items-center gap-3 shrink-0 cursor-pointer group select-none active:scale-90 transition-transform">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isAdmin ? 'bg-amber-500 shadow-xl shadow-amber-200 ring-2 ring-white/50 animate-pulse' : 'bg-[#12141c]'}`}>
              <LayoutGrid className="w-5 h-5 text-white" />
            </div>
            <div className="flex flex-col -space-y-1 relative">
              <h1 className="text-xl font-black text-[#12141c] tracking-tighter">市场周刊</h1>
              {!isAdmin && clickCount > 0 && <div className="absolute -bottom-2 left-0 h-1 bg-amber-400 rounded-full transition-all duration-200" style={{ width: `${(clickCount/5)*100}%` }} />}
            </div>
          </div>
          <div className="flex-grow flex items-center gap-4 max-w-3xl">
            <div className="relative group flex-grow">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <Search className={`w-4 h-4 transition-colors ${searchQuery ? 'text-gray-900' : 'text-gray-300'}`} />
              </div>
              <input type="text" className="w-full bg-gray-100/60 border border-transparent focus:bg-white focus:border-gray-200 py-3 pl-11 pr-10 rounded-2xl text-[14px] font-bold outline-none transition-all placeholder:text-gray-400" placeholder={`在${sortMode === 'journal' ? '瀑布流' : '洞察'}中搜索...`} value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
              {searchQuery && (
                <button onClick={() => setSearchQuery('')} className="absolute inset-y-0 right-0 pr-4 flex items-center text-gray-400 hover:text-gray-600">
                  <span className="text-[10px] font-black uppercase tracking-widest px-1.5 py-0.5 bg-gray-200 rounded-md">清除</span>
                </button>
              )}
            </div>
          </div>
          <div className="flex items-center gap-4 shrink-0">
            <NotificationCenter 
              notifications={notifications} 
              onMarkAsRead={handleMarkAsRead} 
              onClearAll={handleClearAllNotes} 
              onDelete={handleDeleteNote}
            />

            {isAdmin && (
              <div className="flex items-center gap-3 pl-4 border-l border-gray-100">
                <button 
                  onClick={() => { if (sortMode === 'journal') setShowJournalForm(true); else setShowForm(true); }} 
                  className="bg-[#12141c] text-white flex items-center gap-2 px-5 py-2.5 rounded-full hover:scale-105 transition-all shadow-xl shadow-gray-200"
                >
                  <Plus className="w-4 h-4" />
                  <span className="text-sm font-black whitespace-nowrap">投递{sortMode === 'journal' ? '信息' : '观点'}</span>
                </button>

                <button 
                  onClick={handleLogout} 
                  className="flex items-center gap-2 px-4 py-2.5 bg-red-50 text-red-500 rounded-full hover:bg-red-500 hover:text-white transition-all group active:scale-95"
                >
                  <Lock className="w-4 h-4 group-hover:rotate-12 transition-transform" />
                  <span className="text-[12px] font-black whitespace-nowrap">退出管理</span>
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        <aside className="lg:w-64 space-y-12 shrink-0">
          <div className="sticky top-[104px] space-y-10">
            <div className="space-y-1">
                 <button onClick={() => setSortMode('category')} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center gap-3 ${sortMode === 'category' || sortMode === 'timeline' ? 'bg-[#12141c] text-white shadow-xl shadow-gray-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                   <LayoutGrid className="w-4 h-4" /> 核心资产
                 </button>
                 <button onClick={() => setSortMode('journal')} className={`w-full text-left px-4 py-3.5 rounded-2xl text-[14px] font-black transition-all flex items-center gap-3 ${sortMode === 'journal' ? 'bg-amber-500 text-white shadow-xl shadow-amber-200' : 'text-gray-500 hover:bg-gray-100'}`}>
                   <Sparkles className="w-4 h-4" /> 信息瀑布流
                 </button>
            </div>

