                  <div className="absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-all transform translate-y-1 group-hover:translate-y-0">
                     <button 
                       onClick={(e) => { e.stopPropagation(); onDelete(n.id); }}
