                      className={`mt-6 flex items-center gap-2 w-fit px-4 py-2 rounded-xl cursor-pointer transition-all border ${styles.cardBorder} bg-white/50 hover:bg-white hover:shadow-md hover:scale-[1.02] active:scale-95 shadow-sm group/link`}
