                      <span className="text-[11px] font-bold truncate max-w-[180px] sm:max-w-[300px] text-gray-500">{entry.source}</span>
                    </a>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

